UPDATE breweries SET description='長野県に蔵を構える酒ぬのや本金酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。サイズ1800ml／720ml／300ml本醸造 精米歩合60% 毎日、飲みたい酒を目指して 現在のラインナップでは最も長い間愛飲していただいている黄色ラベルの本金です。サイズ1800ml／720ml純米大吟醸 精米歩合39% つうに人気の本醸造生原酒 太一の生原酒、それが樋の口です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=2;
UPDATE breweries SET description='長野県に蔵を構える株式会社舞姫は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。同じ霧ケ峰の伏流水を仕込み水に使いながら、それぞれに特徴のある個性豊かな酒を 醸し続けてきたその5つの蔵は、「諏訪五蔵」と呼ばれるようになりました。以来、「顔の見える酒づくり」をモットーとし、伝統と革新の酒造りを行っています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('美山錦・ひとごこち', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('低温発酵', ''), brewing_features) WHERE id=9;
UPDATE breweries SET description='長野県に蔵を構える株式会社田中屋酒造店は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。【水尾】奥信濃の地酒 飯山 醸造元 田中屋酒造店 そして基本に忠実な良い造り。人の笑顔を願い、地酒を醸す 長野県の最北、奥信濃と呼ばれる豪雪地で、「ここでなければ造れないものを造る」という思いのもと、土地の水、土地の米にこだわり、この地に暮らす杜氏・蔵人とともに、風土を詰め込んだ“地酒”を造り続けています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('9:00～17:30', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=14;
