UPDATE breweries SET description='長野県に蔵を構える株式会社豊島屋は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。豊かな自然環境に恵まれた長野県で、水と良質な米、そしてすべてが手作業で丁寧に醸造された酒、それが神渡冥利の大吟醸原酒です。神渡　純米吟醸ワイン樽貯蔵　MIWATARI CONNECTIONで培った製法を活かし、神渡と坂城葡萄酒醸造の魅力が最大限に生かされた新感覚の日本酒です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・祝・ひとごこち・金紋錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過・原酒', ''), brewing_features) WHERE id=6;
UPDATE breweries SET description='長野県に蔵を構える志賀泉酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。水を替えてからは、抜群に酒が旨くなり 「少し香りがあって辛過ぎず飲み飽きしない酒」を目指し、 これからも地元産にこだわりながら酒の中身に磨きをかけ、 日本酒文化を盛り上げていきます。年々造りを知れば知るほどその難しさや自分の未熟さを思い知らされますが、毎年進化を重ねられるように自分の出来る限りをこだわりぬいて全力で造っています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('中山 治', ''), president_name), toji_name=COALESCE(NULLIF('中山 佳紀', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・ひとごこち', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=16;
