UPDATE breweries SET description='長野県に蔵を構える合資会社丸永酒造場は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。純米大吟醸 Frozen 純米吟醸 Frozen 特別純米 Frozen 特別本醸造 Frozen たくさんは醸せませんが、そのぶん丁寧に時間を掛け原料処理から搾りまで、醸造行程の全てを手造りで行っています。本醸造 原酒生酒しぼりたて 信州の地酒　高波（たかなみ）。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=57;
UPDATE breweries SET description='長野県に蔵を構える木内醸造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。初代は木内清兵衛といい、先祖は武田信玄にゆかりの深い旧家で、当時「田口藩」の藩領であった大澤村の庄屋を代々務めてきた。弟の吾市が家業の醸造業を継ぐことになったが、この三代目が木内醸造の基盤を築き上げる。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('8:00～17:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=46;
