UPDATE breweries SET description='長野県に蔵を構える美寿々酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。澄んだ空気と素朴な自然環境、蔵の裏山から湧き出る軟水と、 この地で育った酒造米「美山錦」による、丹誠込めた手造りの酒は評価も高く、 その希少価値もあいまって、酒通の間で話題となりました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('美山錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=59;
UPDATE breweries SET description='長野県に蔵を構える株式会社よしのやは、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。江戸時代の寛永年間創業 「善光寺外苑　西之門　よしのや」 二十歳未満の者の飲酒は法律で禁止されています。清酒・みそ 品評会受賞歴 日々、製造技術の向上に努め、その成果を品評会に出品しております。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('直売店舗', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('8:30～17:30', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=32;
UPDATE breweries SET description='長野県に蔵を構える合資会社宮島酒店は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。全ての酒造米を地元伊那谷にて契約栽培し、｢土着の蔵｣として信州の風土に根差した味わい豊かな純米醸造酒のみを醸しています。そのため酒造米の全てを農薬を使用しないかその使用を低減した契約栽培米とし、素材の持ち味を明確に表現できる純米醸造酒のみを製造しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=64;
