UPDATE breweries SET description='長野県に蔵を構える株式会社桝一市村酒造場は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。桝一市村酒造場について 純米酒 山廃木桶仕込み 長野県でいちばん小さな町、小布施。江戸時代から変わらぬ木造建築や、店先に鎮座する木桶、印半纏を着た人たちが目印。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('以下蔵人一', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・雄町・美山錦・備前雄町', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('山廃・木桶', ''), brewing_features) WHERE id=29;
