UPDATE breweries SET description='長野県に蔵を構える磐栄運送株式会社諏訪御湖鶴酒造場は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。今を生きる蔵人のブレない酒づくり 理想の味わいを究め、世界に通じる品質を何度でも再現しようとするなら、酒づくりは属人的な技術や勘を超えなければならない。酒造りの全工程において0.1℃の温度、0.1%の水分にまでこだわり、重要なプロセスには、とことん人の手間をかけるのが御湖鶴の流儀。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('直営', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('10:00～16:30', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・美山錦・ひとごこち・金紋錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過生原酒・無濾過・原酒', ''), brewing_features) WHERE id=7;
UPDATE breweries SET description='長野県に蔵を構える和田龍酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。信州上田・北国街道の酒蔵 - 和田龍酒造 明治20年創業、信州上田の造り酒屋　和田龍酒造 信州上田北国街道の造り酒屋 中山道追分宿から善光寺を経て北陸道高田宿に至る北国街道。>>>和田龍ブランド紹介へ ■和田龍登水(とすい)ブランド 少量生産で、よりこだわりのあるお酒を、蔵元の思いを乗せてお届けしたい。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・美山錦・祝・ひとごこち', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=75;
UPDATE breweries SET description='長野県に蔵を構える山三酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。山三酒造 | Yamasan Sake Brewery online storeオンラインストア 山三酒造は、信州上田の地で１８６７年創業した日本酒蔵です。地域に根ざし、原料のお米の一粒、水の一滴までこだわり、伝統と革新の融合によって魅力的な日本酒づくりに挑戦しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・愛山・ひとごこち・金紋錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過生原酒・無濾過・原酒', ''), brewing_features) WHERE id=76;
UPDATE breweries SET description='長野県に蔵を構えるEH酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。また、蔵で醸造されたお酒の数々をテイスティングできます。そしていま、エクセルヒューマンが酔園の歴史と伝統を受け継ぎ、21世紀の酒造りを目指す「ＥＨ酒造」として新たな歴史の一歩を踏み出しました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過', ''), brewing_features) WHERE id=60;
UPDATE breweries SET description='福島県会津若松市に蔵を構える鶴乃江酒造 株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。仕込み水には良質な磐梯山・阿武隈山系伏流水（中軟水）を使用し、会津杜氏・南部杜氏の伝統の技を受け継ぎながら、米の旨味を引き出す真摯な酒造りを追求しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=80;
UPDATE breweries SET description='長野県に蔵を構える株式会社遠藤酒造場は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。創業元治元年（１８６４年）、須坂藩御用達の酒蔵として創業し、以後、藩主への献上酒を納めてきました。以来、初代蔵元、遠藤徳三郎の強い信念でもあった「旨い酒造り」を代々受け継ぎ、常に進取の気性で挑戦を続けております。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('遠藤秀三郎 担当', ''), president_name), toji_name=COALESCE(NULLIF('一人', ''), toji_name), opening_hours=COALESCE(NULLIF('8:30〜17:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('彗星・祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒・古酒', ''), brewing_features) WHERE id=34;
UPDATE breweries SET description='長野県に蔵を構える沓掛酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。創業300余年 歴史と伝統のその先へTRADITIONAL 江戸元禄年間(1688～1704)に創業し、長野県上田市下塩尻の千曲川と虚空蔵山（標高1076.9m）に挟まれた北国街道沿いにて酒造業を営んで300余年。先人たちの知恵と技術を受け継ぎ、新しい手法を取り入れながら弛まぬ努力で酒造りを続けて参ります。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('杜氏', ''), president_name), toji_name=COALESCE(NULLIF('就任', ''), toji_name), opening_hours=COALESCE(NULLIF('8:30～17:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=73;
UPDATE breweries SET description='福島県会津若松市に蔵を構える花春酒造 株式会社は、享保3年（1718年）創業の歴史を誇る老舗酒蔵です。１７１８年（享保３年）に創業以来、 「香りやさしく、口当たりやわらかく、きれいな味わい、のどごしの良さ」を求め、地元会津産米を自社精米し、会津に根ざす日本酒を蔵人一丸となり醸しています。花春のこだわりについて 四方を山々に囲まれた会津地方は、一斉に花々の開く春、蒸し暑い夏、紅葉の美しい秋、雪深く寒さ厳しい冬の四季が、里から山へ、山から里へと足早に移ろい、変化にとんだ自然から豊かな恵みが与えられています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('新井田 傳', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒・袋吊り', ''), brewing_features) WHERE id=78;
UPDATE breweries SET description='長野県に蔵を構える信州銘醸株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。HOME of 信州銘醸 2026年5月20日受賞報告 令和7酒造年度全国新酒鑑評会金賞受賞 今後も美酒醸造に邁進してまいります。今後も日々酒造技術・品質向上を目指します。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('滝澤 恭次', ''), president_name), toji_name=COALESCE(NULLIF('蔵人言葉', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・ひとごこち', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛・きもと・袋吊り', ''), brewing_features) WHERE id=77;
UPDATE breweries SET description='福島県喜多方市に蔵を構える合資会社 吉の川酒造店は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。仕込み水には良質な磐梯山・阿武隈山系伏流水（中軟水）を使用し、会津杜氏・南部杜氏の伝統の技を受け継ぎながら、米の旨味を引き出す真摯な酒造りを追求しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=87;
UPDATE breweries SET description='長野県に蔵を構える喜久水酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。信州の地酒　喜久水酒造｜南信州 飯田市唯一の酒蔵 プライベートブランド醸造支援 ONLINE SHOP 㐂久水を、より特別な一本へ。地域資源の活用、地域ブランド、観光促進に プライベートブランド醸造支援 北緯35度のテロワール 地域のニーズに合わせて、日本酒をはじめとしてシードル、焼酎など様々な酒類を開発・製造しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('直営店', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛・原酒', ''), brewing_features) WHERE id=36;
