UPDATE breweries SET description='福島県白河市に蔵を構える千駒酒造 株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。いままでの千駒とはまた、ひと味違った新銘柄。シャープなキレにこだわりました５／７より一般販売開始千駒からの新提案。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('櫻井 慶', ''), president_name), toji_name=COALESCE(NULLIF('菊地 忠治', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=79;
UPDATE breweries SET description='長野県に蔵を構える株式会社湯川酒造店は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。長野県清酒品評会 首席優等賞を受賞しました 木曽路の 時代  とともに今までも、これからも 木曽路の宿場町で脈々と受け継がれてきた酒造り。14代目の須磨夫は「木曽路」を商標登録し、先代の寛史は法人化して「木曽路」の販路を全国に広げ、さらに新銘柄として「十五代九郎右衛門」を立ち上げました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('湯川寛史', ''), president_name), toji_name=COALESCE(NULLIF('湯川 慎一', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・雄町・美山錦・祝・愛山', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛・山廃', ''), brewing_features) WHERE id=68;
UPDATE breweries SET description='長野県に蔵を構える株式会社土屋酒造店は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。佐久地域に根ざし、佐久地域の自然の恵みをいただきながら、伝承の古式醸法と新醸造技術の調和からお客様に喜んで飲んで頂ける手造りの地酒の逸品を醸しております。伝承の古式醸法と新醸造技術の調和から生まれた吟醸酒は長野県下で先駆けて発売し多くの鑑評会で金賞を重ねております。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('土屋 聡', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛・山廃', ''), brewing_features) WHERE id=43;
