UPDATE breweries SET description='福島県耶麻郡西会津町に蔵を構える栄川酒造 合資会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。栄川酒造コーポレートサイト 歴史、伝統、土地、人。それらを活かし、そして酒造りとどう向き合うのかを 200年の伝統を誇る造り酒屋の日本酒 純米大吟醸　越後街道野澤宿 720ml 200年の伝統を誇る造り酒屋の日本酒 雪深き厳寒の郷、西会津の澄んだ空気、清冽な水。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=110;
