UPDATE breweries SET description='新潟県新潟市に蔵を構える高野酒造株式会社は、明治32年（1899年）創業の歴史を誇る老舗酒蔵です。古くから受け継がれる伝統文化や歴史的な町並みも魅力のひとつです。世界有数の醸造集積地で、日本酒の魅力に触れる 日本酒蔵、ワイナリー、ビール醸造所が集中する世界でも有数の醸造の集積地、「にしかん」エリア。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('高野 英之', ''), president_name), toji_name=COALESCE(NULLIF('一人', ''), toji_name), opening_hours=COALESCE(NULLIF('10:00～16:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('五百万石・祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=222;
