UPDATE breweries SET description='福島県会津若松市に蔵を構える名倉山酒造 株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。名倉山は大正７年、今で言うところの酒の鑑定官のような仕事をしていた初代・松本善六によって創業。以来、とことん酒質にこだわり、南部杜氏の流れを組み、革新的な酒造りに取り組んでいます。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=113;
UPDATE breweries SET description='長野県に蔵を構える株式会社中善酒造店は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。ゴールのみえない日本酒の味造りの道をひたすら突き進み、古くから伝わる伝統文化を受け継いで、将来に繋いでいきたい。先祖代々受け継がれたこの蔵と、日本古来から続く伝統の酒造りをこのメンバーで守り、常に向上心を忘れず、木曽で愛され続ける地酒にしていきたいと思います。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('社長 南', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('美山錦・ひとごこち', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=70;
UPDATE breweries SET description='新潟県上越市に蔵を構える株式会社武蔵野酒造は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。決して辛すぎず、飲み飽きしない酒造り 越後杜氏による伝統的な酒造りに徹し、雪深い高田の地で地元の米、水を大切に酒造りを続けています。雪の恵みによる清冽な天然水、上質な米、越後杜氏の技術。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('代表取締役', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=217;
UPDATE breweries SET description='長野県に蔵を構える株式会社丸世酒造店は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。丸世酒造店 | 丸世酒造店は、長野県中野市に位置する創業1870年の酒蔵です。初代が「世の中が丸くなりますように」との願いを込めて創業し、五代にわたり日本酒を醸し続けています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('ひとごこち・金紋錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=10;
UPDATE breweries SET description='新潟県南魚沼市に蔵を構える八海醸造株式会社は、大正11年（1922年）創業の歴史を誇る老舗酒蔵です。蔵人たちが長年培ってきた知恵と伝統的な技術を集結させ、愚直に「よい酒を、多くの人に」という理念を実現させる——。八海山のこだわり ｜ 八海山 Hakkaisan Wellness 酒としての旨みは十分にありながら、 食事を邪魔せず、いつまでも飲み飽きない酒。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('彗星', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=211;
