UPDATE breweries SET description='新潟県新発田市に蔵を構える金升酒造株式会社は、文政5年（1822年）創業の歴史を誇る老舗酒蔵です。創業文政5年、新潟・新発田の酒蔵、金升酒造から季節と定番の日本酒を全国へお届けします。純米大吟醸 / アルコール度数16度 / 原料米 越淡麗 自社栽培米 40％精米 当蔵最高峰、華やかな風味の純米大吟醸 自社栽培米「越淡麗」を40％に磨き、杜氏、蔵人が渾身の技で醸しました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('8:30〜17:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('五百万石・越淡麗', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒・長期熟成・古酒', ''), brewing_features) WHERE id=241;
UPDATE breweries SET description='長野県に蔵を構える岩波酒造合資会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。西に日本アルプス、東に美ヶ原を望む城下町・松本で、1872年（明治5年）の創業以来、地元に根ざした酒づくりを続けてきました。越後杜氏の伝統が培ったすっきりとしたキレ味に、旨みを重ねる — いま岩波酒造は、蔵元と杜氏が手を携え「ウマミとキレの調和」をテーマに酒を醸しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('代表社員 小岩井', ''), president_name), toji_name=COALESCE(NULLIF('佐田 直久', ''), toji_name), opening_hours=COALESCE(NULLIF('08:30 - 17:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過生原酒・無濾過・原酒', ''), brewing_features) WHERE id=53;
