UPDATE breweries SET description='新潟県阿賀野市に蔵を構える越つかの酒造株式会社は、天明元年（1781年）創業の歴史を誇る老舗酒蔵です。この地に天明の初め（1781年頃）塚野家の初代・塚野丈左衛門義照が陣屋の出店「河内屋」を名乗って酒造りを始めたものが『塚野酒造』の始まりとされています。一方『越酒造』は、豊栄市内島見において、大吟醸酒・吟醸酒・純米酒・という特定名称酒のみを製造販売する蔵として、昭和62年より醸造を開始しました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('歴史', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('古酒', ''), brewing_features) WHERE id=255;
