UPDATE breweries SET description='新潟県中魚沼郡津南町に位置する津南醸造株式会社は、昭和28年（1953年）に創業しました。地域の素材で作るテロワール日本酒津南醸造は、地域内で作る津南産の酒米「五百万石」にこだわり、酒造りをしています。また仕込み水は標高2000メートル級の山々に降り積もった雪が水源となり、名水百選にも選ばれた豊かで清冽な水に恵まれています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('代表取締役 鈴木', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('五百万石・祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒・古酒', ''), brewing_features) WHERE id=213;
