UPDATE breweries SET description='新潟県加茂市に蔵を構える雪椿酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。企画 2025年11月13日 【優秀賞受賞】「越乃雪椿 特別純米 挑戦醸造 720mlビン」第96回 関東信越国税局酒類鑑評会 純米酒の部　優秀賞　受賞 雪椿酒造のウェブショップです。昔ながらの手造りにこだわった新潟の純米蔵です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('雄町', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=260;
UPDATE breweries SET description='新潟県長岡市に蔵を構える住乃井酒造株式会社は、宝暦8年（1758年）創業の歴史を誇る老舗酒蔵です。住乃井酒造は、宝暦8年（1758年）の創業以来、酒造り一筋に歩んできました。この自然の摂理に素直に頭を垂れ、自然の営みを謙虚に見つめながら、技をつくし、研究に努めた結果到達したのが、私たちの山廃仕込です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('山廃', ''), brewing_features) WHERE id=279;
