UPDATE breweries SET description='新潟県長岡市に蔵を構えるお福酒造株式会社は、明治31年（1898年）創業の歴史を誇る老舗酒蔵です。現在では、全国の酒蔵で酒造りの主流として使用されており、創業者の岸五郎の意思を受け継いだお米の良さを活かしきる酒造りをしています。その魅力を引き出すため、初代岸五郎が掲げた「安全な造りでお客様を満足させる」という信念を受けつぎ喜ばれる酒造りを続けています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('直営店', ''), president_name), toji_name=COALESCE(NULLIF('吉井民夫', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('五百万石・祝・越淡麗・一本〆', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=269;
UPDATE breweries SET description='新潟県東蒲原郡阿賀町に蔵を構える下越酒造株式会社は、明治13年（1880年）創業の歴史を誇る老舗酒蔵です。イベントや酒蔵など最新の情報をチェック 2026/08/08夏季休業のお知らせ 2026/08/04出展のお知らせ 2026/07/23第31回和酒フェス 「酒造りは米磨きから」を貫き、伝統的製法「寒仕込み」に拘る。下越酒造では現在でも極寒期に伝統的製法である「寒仕込み」に拘り、厳しい醪の温度管理の中、低温発酵での酒造りが進行しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('長谷川 久晃', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('低温発酵', ''), brewing_features) WHERE id=272;
