UPDATE breweries SET description='秋田県大仙市に蔵を構える有限会社 奥田酒造店は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。千代緑の仕込蔵は創業の三百五十年ほど前より幾度か建替えられ、現在の仕込蔵は九十年余の時を経ておりますが、その間ずっと、蔵人と代を重ねた『家つき酵母』の協同作業によって千代緑を醸し続けてきました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('瓶燗火入れ', ''), brewing_features) WHERE id=535;
UPDATE breweries SET description='新潟県新発田市に蔵を構える王紋酒造株式会社は、寛政2年（1790年）創業の歴史を誇る老舗酒蔵です。酒造りには変わらない思い 「米と水と気候と技術を生かした、品質の高い清酒を造り続ける」を理念に、創業より200有余年。酒造りには変わらない思いを持ち続け、地元の良質な米と水、酒造りに適した気候、そして歴史を重んじながらも進化し続ける越後杜氏の技術から生まれる清酒。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('会長 長谷川', ''), president_name), toji_name=COALESCE(NULLIF('田中', ''), toji_name), opening_hours=COALESCE(NULLIF('9:00～18:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('五百万石・祝・越淡麗', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('山廃・古酒', ''), brewing_features) WHERE id=281;
UPDATE breweries SET description='秋田県大館市に蔵を構える株式会社北鹿は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。こだわりの酒造り｜秋田の清酒 北鹿｜日本酒｜大吟醸｜純米酒｜雪中貯蔵 秋田の清酒 北鹿｜日本酒｜大吟醸｜純米酒｜雪中貯蔵 伝統とこだわりの酒造り蔵人たちの伝承と浪漫が始まります。日本酒は、米、水、麹を原料とし発酵させてつくるお酒で日本で生まれ、日本独自の技術で作られています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・秋田酒こまち', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛', ''), brewing_features) WHERE id=541;
UPDATE breweries SET description='秋田県湯沢市に蔵を構える両関酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。コンセプトConcept 先人が築き上げてきた伝統の技術に、更なる改良を加え発展させ、未来へ引き継いでいく。人の和で醸した良酒が、飲む人の心を和ませ、人の和を繋いでいくことを願って、私たちは伝統と文化を伝え続けます。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('限定酒 吟醸酒', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒・袋吊り', ''), brewing_features) WHERE id=546;
