UPDATE breweries SET description='秋田県大仙市に蔵を構える合名会社秋田富士酒造店は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。米の「旨み」を最大限に引き出す酒づくりに 世界的に高い評価を獲得する主力銘柄 純米原酒「X3」シリーズや 熟成酒梅酒「悠久の梅雫」など 個性豊かな酒づくりを通して、 新たな価値創造に努めてきました。そして、その成果として生まれたのが、 熟成酒の代表銘柄「山吹」です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=539;
UPDATE breweries SET description='兵庫県神戸市灘区に蔵を構える沢の鶴株式会社は、享保2年（1717年）創業の歴史を誇る老舗酒蔵です。吟醸酒と純米酒、本醸造酒の違いを知ろう 日本酒と料理酒の違いは。それ以来、米を目利きする力を代々受け継いできた私たちは、純米酒・米だけの酒にこだわり続け、おかげさまで「沢の鶴」の純米酒は、多くの方々からの高い評価を受け、売上げでも、常に上位にあります。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過・原酒・長期熟成・古酒', ''), brewing_features) WHERE id=614;
UPDATE breweries SET description='兵庫県神戸市東灘区に蔵を構える株式会社安福又四郎商店は、宝暦元年（1751年）創業の歴史を誇る老舗酒蔵です。仕込み水には良質な六甲山系宮水・播磨揖保川水系伏流水（中硬水）を使用し、丹波杜氏の伝統の技を受け継ぎながら、米の旨味を引き出す真摯な酒造りを追求しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=622;
UPDATE breweries SET description='兵庫県神戸市東灘区に蔵を構える株式会社神戸酒心館は、宝暦元年（1751年）創業の歴史を誇る老舗酒蔵です。РУССКИЙ ЯЗЫК 「福寿」という酒銘は、 七福神の一柱「福禄寿」が由来となっています。宝暦元年（1751年）の創業以来、 伝統を重んじながらも革新的な技術を取り入れて、 270年以上にわたって多くの人の幸福な時間に寄り添い続けています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛', ''), brewing_features) WHERE id=620;
