UPDATE breweries SET description='兵庫県神戸市東灘区に蔵を構える髙嶋酒類食品株式会社は、明治3年（1870年）創業の歴史を誇る老舗酒蔵です。初代髙嶋平介は灘五郷の酒造家より酒粕を買い、酒粕の仲買業を営んでおりましたが、明治3年（西暦1870年）に、酒粕から粕取り焼酎の製造を始めるべく焼酎製造免許を取得しました。よってこの年を私どもは創業年と定めております。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('代表取締役', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('9:30～18:30', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=623;
UPDATE breweries SET description='秋田県湯沢市に蔵を構える秋田県醗酵工業株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。オエノングループは、大吟醸・吟醸・純米吟醸をはじめ、純米や本醸造、普通酒、生酒・生貯蔵酒、にごり酒など様々な日本酒（清酒）を取り揃えております。伝統の技に裏打ちされた確かな味わいをお楽しみください。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('組合優等賞', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=554;
