UPDATE breweries SET description='秋田県鹿角市に蔵を構える千歳盛酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。明治5年の創業以来、地元鹿角を中心に長い間親しまれてきた定番のシリーズです。創業者の田村茂助により不老長寿の願いを込め「千歳」と命名され、大正11年に世の繁栄と更なる長寿を願い「千歳盛」となった歴史ある酒銘です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('社長 佐', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('9:00～17:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('低温発酵', ''), brewing_features) WHERE id=540;
