UPDATE breweries SET description='新潟県阿賀野市に蔵を構える白龍酒造株式会社は、天保10年（1839年）創業の歴史を誇る老舗酒蔵です。「ヨーグルトリキュール モウモウ」はこちら>> 特撰純米大吟醸 茂左衛門 白龍の蔵を開いた初代・笹屋茂左衛門の名を冠した特撰純米大吟醸酒ができました。酒造りの匠「越後杜氏」の伝統の技を注ぎ込んで醸した奥深くふくよかな旨みの酒です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('五百万石', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過・原酒', ''), brewing_features) WHERE id=289;
UPDATE breweries SET description='兵庫県神戸市東灘区に位置する宝酒造株式会社は、平成13年（2001年）に創業しました。神戸・灘にある「松竹梅白壁蔵」には、 昔ながらの手造りの原理を再現した、 新しい設備がそなわっています。酒づくりの初心に戻り、それをかたちにすると 〝現代の技術〟と〝伝統の技〟が融合した 「松竹梅白壁蔵」になりました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛・きもと', ''), brewing_features) WHERE id=625;
UPDATE breweries SET description='兵庫県神戸市東灘区に蔵を構える白鶴酒造株式会社は、1743年 (寛保3年)年に創業しました。【SAKETIMES】山田錦と双璧をなす酒米を目指して─ 白鶴酒造が開発した酒米「白鶴錦」に秘められた可能性 PRODUCT LINEUP プレミアムPREMIUM 大切なひとときを彩る、こだわりの商品です。4. ホームページ提供の一時中断について 当社は、システムの保守・障害、火災・停電、地震などの天災、その他運用・技術上当社ホームページ提供の一時中断が必要であると判断した場合には、事前通知を行うことなく一時中断する場合があります。歴史ある建造物は白鶴酒造資料館は神戸市指定有形民俗文化財としても親しまれており、伝統と革新を融合させた味わいを全国の日本酒ファンへ届けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('四季醸造', ''), brewing_features) WHERE id=616;
UPDATE breweries SET description='兵庫県神戸市東灘区に蔵を構える菊正宗酒造株式会社は、万治2年（1659年）創業の歴史を誇る老舗酒蔵です。良質な酒米と宮水という、六甲山系の自然の恵みを丹波杜氏の職人技で醸した辛口を携え、地の利を生かして港から遠くは松前（北海道）にまで取引に出かけたという本嘉納家。また、明治22年（1889年）には本嘉納家8代目秋香翁が「どうしても良い酒を造る」の信念でドイツから顕微鏡を購入し、西洋の学問を身に付けた技術者を招聘。歴史ある建造物は菊正宗酒造記念館・国の重要有形民俗文化財収蔵としても親しまれており、伝統と革新を融合させた味わいを全国の日本酒ファンへ届けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('万治二年', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛', ''), brewing_features) WHERE id=617;
