UPDATE breweries SET description='兵庫県神戸市東灘区に蔵を構える櫻正宗株式会社は、寛永2年（1625年）創業の歴史を誇る老舗酒蔵です。その後、酒造に重きを置き、1717（享保2）年に初代山邑太左衛門を名乗り、創業しました。その頃、六代目太左衛門は当時の酒銘「薪水」が 女性的で酒客の好みに合わないことから 醸造法の改良とともに酒銘の検討をしました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=627;
