UPDATE breweries SET description='新潟県長岡市に蔵を構える長谷川酒造株式会社は、天保13年（1842年）創業の歴史を誇る老舗酒蔵です。ここ長岡・摂田屋で伝統を受け継ぎながら、時と自然に寄り添い、手づくりにこだわり、その年にしか生まれない酒を醸しています。長谷川酒造では、酒造りに恵まれた環境で、機械に頼らず、昔ながらの手作業にこだわり酒造りを行っています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=257;
UPDATE breweries SET description='兵庫県西宮市に蔵を構える松竹梅酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。灘五郷の風土が際立つ灘の酒 2,055円税込みtax included 灘五郷の風土、厳選したお米と仕込み水としての宮水。フレッシュでさわやかな本醸造酒 501円税込みtax included 良質の酒米で作った酒を生のまま低温で熟成させ、瓶詰め時に低温瞬間殺菌しました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('代表取締役 石田', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=634;
