UPDATE breweries SET description='兵庫県西宮市に蔵を構える白鷹株式会社は、文久2年（1862年）創業の歴史を誇る老舗酒蔵です。自家醸造100％で本当に自信のある本物の“生粋の灘酒”だけを創業以来提供し続けてきた白鷹が、皆様にこだわりの逸品をお届けいたします。白鷹3代目　辰馬悦蔵が蒐集した考古資料から縄文土器や銅鐸を中心に、初代辰馬悦叟が蒐集した富岡鉄斎作品まで、これまでは分野•テーマ別に開催していた収蔵品を同時に出品する展観です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('辰馬朱滿子 日時', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('11:00～19:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛・原酒・袋吊り', ''), brewing_features) WHERE id=632;
