UPDATE breweries SET description='福岡県三井郡大刀洗町大字栄田に蔵を構える博多焼酎 研醸 株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。創業以来、一貫して「焙煎麦焼酎」にこだわり続け、麦の煎り加減を幾度も試行錯誤しながら理想の香ばしさを追求してまいりました。創業以来、一貫として焙煎麦焼酎に拘ってきた、麦の煎り加減を試行錯誤して出来上がった焙煎麦を原料とて仕込み、蒸留する事により麦の香ばしさと味わいが醸し出されます。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('長期熟成', ''), brewing_features) WHERE id=985;
