UPDATE breweries SET description='福岡県八女市本町に蔵を構える株式会社 喜多屋は、文政3年（1820年）創業の歴史を誇る老舗酒蔵です。「酒を通して多くの喜びを伝えたい」という志を大切に、情熱を込めた酒造りを続けています。開発の背景には、受け継がれてきた酒造りへの信念と、新時代への希望が込められています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('木下宏太郎 本社', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=945;
