UPDATE breweries SET description='山形県酒田市に蔵を構える東北銘醸株式会社は、明治26年（1893年）創業の歴史を誇る老舗酒蔵です。山形県産米を使用し、生酛造りで醸し… 初孫「香が星（かがぼし）」純米大吟醸を発売します 令和8年９月2日（火） 山形県産出羽燦々（でわさんさん）１００％使用の純米大吟醸を季節限定で発売致します。その想いを胸に、いままでもこれからも上質な生酛造りに注力、邁進いたします。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('佐藤　雅士', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('10:00～16:30', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('出羽燦々', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛', ''), brewing_features) WHERE id=896;
UPDATE breweries SET description='福岡県久留米市小頭町に蔵を構える鷹正宗 株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。価格改定のお知らせ　－本格芋焼酎－ 原材料に国産の清酒、ゆず果汁、液糖の3種のみでシンプルに造ったこだわりの無添加リキュール。単式蒸留焼酎（国内製造）、いちご果汁、食物繊維／酸味料、香料、甘味料（ステビア） 【通販サイト限定】はじめての梅酒　20度 300ml 【通販サイト限定】はじめての梅酒　20度 300ml <ご購入はこちら>　鷹正宗創業初の梅酒。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('社長 濵', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒・長期熟成', ''), brewing_features) WHERE id=994;
