UPDATE breweries SET description='京都府京丹後市に蔵を構える竹野酒造有限会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。近江こだわり米工房の濱田氏の尽力で「滋賀旭」として見事に復活を遂げた、栽培期間中農薬不使用で育てた原種（田渕農園産）を100%使用しています。近江こだわり米工房の濱田氏の尽力で「滋賀旭」として見事に復活を遂げた、栽培期間中農薬不使用で育てた原種（田渕農園産）を100%使用しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('氏名', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・祝・亀の尾', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('山廃・無濾過・原酒・直汲み', ''), brewing_features) WHERE id=1120;
UPDATE breweries SET description='秋田県横手市に蔵を構える阿櫻酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。全国五大杜氏の一つである秋田の山内杜氏 照井俊男のもと、情熱を燃やす蔵人達により、技の粋を集めた酒造りをしております。近年、酒造技術の改良と酒質の向上に励み、全国にその技術水準の高さを知らしめるなど、そのたゆまざる努力が今日の銘醸地秋田の基礎をつくり上げました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('信川晃洋 阿櫻', ''), president_name), toji_name=COALESCE(NULLIF('照井 俊男', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('低温発酵', ''), brewing_features) WHERE id=555;
