UPDATE breweries SET description='京都府宮津市に蔵を構えるハクレイ酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。ハクレイを代表するお酒 料理によく合う丹後の地酒 伝統ある酒蔵を実際に見学いただけます。酒造りを体感できる「天の蔵」では、お客さま係の社員が試飲と酒蔵のご案内し、 蔵の歴史や銘柄の由来の説明、そして酒造りの説明も承ります。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=1126;
UPDATE breweries SET description='福岡県久留米市三潴町草場に蔵を構える池亀酒造 株式会社は、明治8年（1875年）創業の歴史を誇る老舗酒蔵です。良き伝統は守りながら、頑なではなく柔軟な酒造りに取り組み、 酔う酒ではなく、新鮮な驚きと感動を与える酒文化を発信します。源蔵は、進取の精神に富んだ人物で、筑後川の水を使用した新しい醸造法を考案、 養成した杜氏を派遣して筑後地方の酒造りに貢献しました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('社長 蒲池', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('木桶', ''), brewing_features) WHERE id=933;
UPDATE breweries SET description='福岡県うきは市浮羽町西隈上に蔵を構える株式会社 いそのさわは、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。私たち「いそのさわ」は、 この地の清らかな天然水を仕込み水とし、 一滴一滴に想いをこめて、 うきはの自然と共に酒を醸しています。1833年創業の酒蔵が紡ぐ、伝統製法とこだわりの味を楽しむ蔵元施設。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('施設', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=992;
UPDATE breweries SET description='京都府京丹後市に蔵を構える木下酒造有限会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。玉川 木下酒造有限会社 | 京都府北部・久美浜にある175年の歴史を誇る地酒『玉川』の蔵元 心を込めて旨い酒を造る 木下酒造は天保13年（1842年）、京丹後久美浜の地で創業しました。代表銘柄である「玉川」の由来は蔵のすぐ隣に川上谷川という川があり、玉砂利を敷き詰めた感の、清流であったそうです。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('木下 善人', ''), president_name), toji_name=COALESCE(NULLIF('資格選考試', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過生原酒・無濾過・原酒', ''), brewing_features) WHERE id=1121;
UPDATE breweries SET description='京都府亀岡市に蔵を構える大石酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。梅酒 麗「うらら」720ml 美山 てんごりが本醸造部門でトロフィーを受賞しました。毎年イギリスで開催される世界の酒コンテスト「インターナショナル・ワイン・チャレンジ」２０２０年度の本醸造部門において、当社の「美山 てんごり」がGOLD（金）を受賞し、中でもカテゴリ内最上の「トロフィー」に選ばれました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('9:30 〜 17:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=1132;
