UPDATE breweries SET description='兵庫県宍粟市に蔵を構える山陽盃酒造株式会社は、天保8年（1837年）創業の歴史を誇る老舗酒蔵です。185年以上培ってきた日本酒の醸造技術を活かして、杜氏が研究し尽くし、たどり着いたシードルは「香りが爽やかで、透明感ある味わい」。そのために新旧の技術を駆使し、手間ひま惜しまず、真剣に目の前の酒と向き合って酒づくりしています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('就任 平成', ''), president_name), toji_name=COALESCE(NULLIF('就任 平成', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('愛山', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('長期熟成', ''), brewing_features) WHERE id=656;
UPDATE breweries SET description='京都府綾部市に蔵を構える若宮酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。京都産の米にこだわり、 丹波・但馬両杜氏より受け継いだ蔵元杜氏の下、 綾部の山紫水明な環境下で 酒造りに必要なタイミングを逃さず 良質な酒を醸しています。京都産の米にこだわり、丹波・但馬両杜氏より受け継いだ蔵元杜氏の下、綾部の山紫水明な環境下で酒造りに必要なタイミングを逃さず良質な酒を醸しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('杜氏', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=1129;
