UPDATE breweries SET description='愛知県名古屋市に位置する金虎酒造株式会社は、昭和20年（1945年）に創業しました。伝統に裏付けられた変革の逸品 伝統の酒造りの技と、若き造り手達の次代への情熱が結実して生まれた逸品です。名古屋の老舗酒蔵と若き杜氏の情熱があるからこそできる、自慢の商品を紹介します。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=1373;
