UPDATE breweries SET description='京都府京都市伏見区に蔵を構える月桂冠株式会社は、1637年 (寛永14年)年に創業しました。吟醸、純米、本醸造の違い 香り・コク、特定名称の各製法で生み出される特徴。純米大吟醸酒、純米吟醸酒、大吟醸酒 1637年（寛永14年）創業、京都伏見で最古の酒蔵・月桂冠。歴史ある建造物は内蔵酒造場（近代化産業遺産）としても親しまれており、伝統と革新を融合させた味わいを全国の日本酒ファンへ届けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=1141;
