UPDATE breweries SET description='京都府京都市上京区に蔵を構える佐々木酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。川端康成が「この酒の風味こそ京都の味」と好んだ それぞれに洛中の年輪を刻み、技と味を伝承した京都・洛中・佐々木酒造。昭和の文豪・川端康成に「京の味」と称された銘酒「古都」、京都のわらべうたに由来する「まるたけえびす」など、千年の都が育んだ味がここで産まれます。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=1133;
UPDATE breweries SET description='京都府京都市伏見区に蔵を構える株式会社京姫酒造は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。特に大吟醸や純米吟醸に名付けられた『匠』という銘柄は、 京姫の技を結集した作品ではば広い層のお客様にご愛飲いただいております。長い歴史の中で培われてきた醸造技術を継承しながらも、 多様化するニーズにお応えするべく品質を追求し満足いただける商品づくりを目指していきます。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒・袋吊り', ''), brewing_features) WHERE id=1139;
UPDATE breweries SET description='京都府京都市伏見区に蔵を構える東山酒造有限会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。ONLINE SHOP 京都伏見でこだわりの酒造りを追求する東山酒造は、杜氏伝承の日本酒の歴史と伝統を重んじた仕込みを継承し、本来の日本酒の旨さを追求したこだわりの純米酒を育て続けています。現在は、南部杜氏 矢追誠司が、長年培ってきた「技」と「経験」でじっくりと醸しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('伝承', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・雄町・祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('低温発酵', ''), brewing_features) WHERE id=1148;
UPDATE breweries SET description='京都府京都市伏見区に蔵を構える都鶴酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。都鶴酒造 | 京都市伏見区の酒蔵 都鶴酒造とは銘柄一角都鶴お知らせ会社案内お問い合わせ トップ都鶴酒造とは銘柄一角都鶴お知らせ会社案内お問い合わせ 誠心誠意のまっすぐな想い。すべてを純京都にこだわり抜き、伏見で小さな酒蔵だからこそできる、一本一本への愛情を込めた酒造り。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('取締役社長 内田', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=1154;
UPDATE breweries SET description='福岡県北九州市八幡東区に蔵を構える溝上酒造 株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。溝上酒造の酒造りへの思いやこだわりを 酒造りへの思いを詳しく見る 溝上酒造の創業は弘化元年（1844年）。歴史と伝統を守りつつ日々進歩を目指しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('溝上 智彦', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=993;
