UPDATE breweries SET description='愛知県江南市に蔵を構える勲碧酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。清流木曽川の恵みを十分に授かった素材と 百余年という年月を経て培ってきた技術を 組み合わせて酒を醸し続けて参りました。勲碧でつくるお酒は、木曽川清流の仕込み水とお酒に合わせた酒米を使用しているため、 口当たりがやさしく、奥深い旨みがあるのが特徴です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('兼杜氏 村瀬公康', ''), president_name), toji_name=COALESCE(NULLIF('村瀬公康', ''), toji_name), opening_hours=COALESCE(NULLIF('9:00～18:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・雄町・祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒・古酒', ''), brewing_features) WHERE id=1381;
