UPDATE breweries SET description='愛知県碧南市に蔵を構える永井治一郎は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。Start content １５０年余り続く伝統の地酒 慶応２年（1866）の開業以来１５０年余り「おいしい」「旨い」といわれる品質を第一と考え、 良質な硬水の自家井泉と厳選した酒造好適米「山田錦」を用いて、丁寧にお酒を造っています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒・古酒', ''), brewing_features) WHERE id=1399;
UPDATE breweries SET description='京都府京都市伏見区に蔵を構える株式会社増田德兵衞商店は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。だからこそ手造りにこだわり、酒そのものに加えてその周りにある酒器や料理、伝統行事、芸術など幅広く酒と文化の関わりに注目し、嗜みとしての酒を大事にしてきました。京都伏見の酒蔵としての伝統を守りながらも誰もがそうしてきたことには とどまらず世間に流されない、型破りな酒を目指します。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('9:00 ～ 17:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('長期熟成・古酒', ''), brewing_features) WHERE id=1151;
