UPDATE breweries SET description='愛知県豊田市に蔵を構える浦野合資会社は、元治元年（1864年）創業の歴史を誇る老舗酒蔵です。元治元年（1864年）三河の霊峰・猿投山の天然記念物「菊石」の名を崇敬する猿投神社より拝受し、代表銘柄として猿投村（現：豊田市）に創業致しました。以来160年、伝統的な手造りの味を大切にしながら、多くの皆様と地酒を通じて出会える新たな機会を試みています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('直売 販売店', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=1406;
UPDATE breweries SET description='愛知県愛西市に位置する渡辺酒造株式会社は、令和7年（2025年）に創業しました。創業以来受け継いできた酒造りへの想いはそのままに、今後は「弥栄の酒 寿」を中心に、より一層日本酒文化の発展に努めてまいります。七代目杜氏・渡辺秀幸が160年受け継がれた技と心を注ぎ込み、この地にしか出せない優雅な味わいを完成させました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('山田 栄治', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=1387;
UPDATE breweries SET description='静岡県藤枝市に蔵を構える株式会社志太泉酒造は、明治15年（1882年）創業の歴史を誇る老舗酒蔵です。志太泉は、明治15年初代「望月久作」が、創業しました。はやくから吟醸造りに取り組み、昭和35年4月には、吟醸酒「白鷺」として発売を開始しました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('以外', ''), president_name), toji_name=COALESCE(NULLIF('手法', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・祝・愛山', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=1845;
