UPDATE breweries SET description='愛知県豊田市に蔵を構える中垣酒造株式会社は、明治33年（1900年）創業の歴史を誇る老舗酒蔵です。創業時より「甘口であり旨口の清酒を醸す」をコンセプトに、 代表ブランド賜冠（シカン）を製造・販売しております。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('住所 愛知県', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=1407;
UPDATE breweries SET description='愛知県海部郡蟹江町に蔵を構える山田酒造株式会社は、明治4年（1871年）創業の歴史を誇る老舗酒蔵です。愛知・岐阜の蔵元が3日間で50蔵出店し、総勢140銘柄以上のお酒が堪能できます。銘柄「醉泉」「最愛」は伝統製法で濃醇で骨太なキレのある味わい 山廃仕込みの日本酒は速醸酛造りのものと比べ、酵母を繁殖させるために時間がかかります。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('勘違', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛・山廃・低温発酵', ''), brewing_features) WHERE id=1391;
