UPDATE breweries SET description='愛知県常滑市に位置する澤田酒造株式会社は、昭和44年（1969年）に創業しました。それは、米の旨さを引き出し、濃醇でありながら雑味を出さないようにするには、古いけれど伝統の方法が一番と考えているからです。当社では、最高級の兵庫県特A地区「東条 山田錦」をはじめ、北陸産「五百万石」、広島県産「八反錦・千本錦」、そして地元で契約栽培する愛知県産「若水・夢吟香」などの酒造好適米を使用しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('直売所', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・五百万石・八反錦・千本錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛', ''), brewing_features) WHERE id=1396;
