UPDATE breweries SET description='愛知県北設楽郡設楽町に蔵を構える関谷醸造株式会社は、元治元年（1864年）創業の歴史を誇る老舗酒蔵です。関谷醸造は元治元年（一八六四年）に、 自然豊かな、愛知県設楽町にて創業しました。以来、日本酒の可能性を柔軟に追求し、 伝統の技と革新的な技術を用いた、 高品質の酒造りを行っています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('氏名 必須', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('8:30～17:30', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・雄町・五百万石・美山錦・八反錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛・きもと・山廃・無濾過生原酒・無濾過', ''), brewing_features) WHERE id=1409;
UPDATE breweries SET description='山口県岩国市に位置する旭酒造株式会社は、昭和23年（1948年）に創業しました。仕込み水には良質な寂地山系地下伏流水（軟水）を使用し、丁寧な手造りの精神を受け継ぎながら、米の旨味を引き出す真摯な酒造りを追求しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=1921;
UPDATE breweries SET description='京都府京都市伏見区に蔵を構える松本酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。桃山丘陵をくぐった清冽な水が、水脈となって地下に深く息づき、当蔵の敷地内にて汲み上げ、仕込み水としております。創業した江戸時代以降、移りゆく時代の中で培ってきた酒造りへの思いをこの京都の地からこれからも表現していく所存です。歴史ある建造物は酒蔵・煉瓦煙突が国の近代化産業遺産・京都市景観重要建造物としても親しまれており、伝統と革新を融合させた味わいを全国の日本酒ファンへ届けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('挨拶', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・五百万石', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=1152;
UPDATE breweries SET description='静岡県静岡市清水区に蔵を構える株式会社神沢川酒造場は、大正元年（1912年）創業の歴史を誇る老舗酒蔵です。米は優良な原料米を厳選 神沢川の水に合う米を厳選し、数種の銘柄を使い分けます。「山田錦」「吟ぎんが」「雄町」など銘柄によって産地を決め、平成17年からは静岡県開発の酒造好適米「誉富士」も使用しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('望月正隆 杜氏', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('9:00～17:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・雄町', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=1844;
UPDATE breweries SET description='福岡県八女市本町に蔵を構える株式会社 高橋商店は、享保2年（1717年）創業の歴史を誇る老舗酒蔵です。江戸時代から三百年、八女の地で受け継がれてきた手仕事がある。一粒の米から香りと旨みを引き出す技に、蔵人の想いを重ねて。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('8:30～17:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=952;
