UPDATE breweries SET description='愛知県名古屋市に蔵を構える東春酒造株式会社は、慶応元年（1865年）創業の歴史を誇る老舗酒蔵です。名古屋市守山で150年以上の歴史 創業は、江戸末期・元治２年(１８６５年)。杜氏、名古屋城の櫓を建造する予定の材木を譲り受け、創業者・佐藤東兵衛が当地(善光寺街道筋)に酒蔵を建造。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('佐藤 幸彦', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・五百万石・祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('山廃', ''), brewing_features) WHERE id=1374;
