UPDATE breweries SET description='静岡県静岡市清水区に蔵を構える英君酒造株式会社は、明治14年（1881年）創業の歴史を誇る老舗酒蔵です。吟醸香をまとった食中酒 現代にも愛される酒造りに 伝統の静岡酵母と現代の技術を掛け合わせ 製造工程のご案内をしています。夜間作業撤廃の為に導入されたロボットですが、思い通りの品質の高い麹を製麹することが難しく、現在はステンレス製の箱だけを使用し蔵人の手造りで製麹しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('望月裕祐 杜', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・雄町・備前雄町', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過生原酒・無濾過・原酒', ''), brewing_features) WHERE id=1861;
UPDATE breweries SET description='山口県山口市に蔵を構える金光酒造株式会社は、昭和元年（1926年）創業の歴史を誇る老舗酒蔵です。酒造りへの磨かれた技、執念、徹底したこだわり、熟練の技が醸し出す、金光酒造伝統の味をぜひご堪能ください。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('金光明雄 山口', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=1915;
