UPDATE breweries SET description='静岡県静岡市駿河区に位置する株式会社駿河酒造場は、平成22年（2010年）に創業しました。静岡酵母や伝統酵母を使い、低温発酵・低音貯蔵などにこだわった、静岡の気候のような穏やかな香りと味わいのミディアムテイスト。about FEATURE すべてのクラスで全量大吟醸造りに用いる袋取り樽しぼりの贅沢仕上げ。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('低温発酵', ''), brewing_features) WHERE id=1848;
UPDATE breweries SET description='静岡県藤枝市に蔵を構える初亀醸造株式会社は、寛永13年（1636年）創業の歴史を誇る老舗酒蔵です。Online Shop 初亀醸造のお酒　ラインナップ 1636年に「足名屋」として創業、静岡で最も古い酒蔵の一つ。銘柄『初亀』は「初日のように光り輝き、亀のように末永く栄える」願いから名付けられました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=1855;
