UPDATE breweries SET description='愛知県西尾市に位置する相生ユニビオ株式会社は、昭和29年（1954年）に創業しました。原料を厳選し、明治5年創業より培った職人の技と伝統の旧式製法で丁寧に造り上げています。科学技術や添加物では決して作り出せない 「琥珀色の輝き」や「豊潤でふくよかな味わい」こそ、 私たちが大切にする伝統の味です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('代表取締役 小川', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('古酒', ''), brewing_features) WHERE id=1401;
UPDATE breweries SET description='愛知県半田市に位置する伊東株式会社は、平成12年（2000年）に創業しました。仕込み水に用いている豊富な井戸水は、ミネラルを多く含み、酵母の育成にも良い影響を与え、敷嶋独特のキレの良さをもたらしています。そのためにお米をしっかりと溶かして食事の味を受け止められるだけの厚みを出しながら、上質な酸、そして良質な仕込み水に由来す るミネラル感で〆るお酒を造っています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=1398;
