UPDATE breweries SET description='山口県萩市に蔵を構える株式会社澄川酒造場は、大正10年（1921年）創業の歴史を誇る老舗酒蔵です。2021年で創業100年を迎えた澄川酒造場。澄川宜史が4代目蔵元杜氏になってからの日本酒造りのこだわりは他の追随を許さない。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('杜氏', ''), president_name), toji_name=COALESCE(NULLIF('澄川宜史', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・雄町・愛山', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('直汲み', ''), brewing_features) WHERE id=1930;
