UPDATE breweries SET description='山口県萩市に蔵を構える有限会社岡崎酒造場は、大正13年（1924年）創業の歴史を誇る老舗酒蔵です。創業は大正13年（西暦1924年）地元山口の酒米を中心に日本酒・リキュールなどを製造しています Concept長門峡の清流に育まれた手造りの酒 大正13年より創業。水は萩市阿武川の清流をつかい手造りで日本酒を製造しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過', ''), brewing_features) WHERE id=1934;
