UPDATE breweries SET description='岐阜県大垣市に蔵を構える渡辺酒造醸は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。この地に明治35年、渡辺酒造醸は創業しました。創業から100年以上経った現在も地元の方々に愛され続けるため、“この地”“この蔵”でしか出せない味に、こだわり、追求しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('渡辺愛佐子', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=2134;
UPDATE breweries SET description='岐阜県美濃加茂市に蔵を構える御代桜醸造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。岐阜の地の豊かな自然に育まれた米と清冽な水から生まれる、脈々と受け継がれる小細工のない風土の酒。米と水とそして醸し手達の情熱が生み出す日本酒の限りない可能性を模索し、新しい価値を創りたいと志して挑戦し続ける酒。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=2141;
UPDATE breweries SET description='山口県萩市に蔵を構える岩崎酒造株式会社は、明治34年（1901年）創業の歴史を誇る老舗酒蔵です。2026年1月14日受付分まで「年末年始休業は12/30～1/5」 創業当時、蔵元である岩崎家に女の子が次々と誕生したことからその娘（こ）らが福々しいよい娘に育ってほしいとの願いを込めて福娘と名付けられました。創業は明治３４年（西暦１９０１年）で、創業以来原料である酒米の品質にこだわって酒造りを行ってきました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('岩崎 喜一郎', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('9:00〜18:30', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('直汲み', ''), brewing_features) WHERE id=1936;
