UPDATE breweries SET description='静岡県藤枝市に蔵を構える杉井酒造は、天保13年（1842年）創業の歴史を誇る老舗酒蔵です。一度に大量の洗米が可能なため、本醸造等大型の仕込みの時に利用します。やる事自体は家庭でお米を炊く事と同じで簡単ですが、すし職人が炊いたお米が、適度な硬さと柔らかさを持つように、満足のいくお酒を造るためには酒造りにおいても職人としての技が必要になります。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('就任', ''), president_name), toji_name=COALESCE(NULLIF('兼任 静岡県藤枝', ''), toji_name), opening_hours=COALESCE(NULLIF('8:00～12:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛・山廃', ''), brewing_features) WHERE id=1856;
