UPDATE breweries SET description='岐阜県多治見市に蔵を構える株式会社三千盛は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。昭和30年代のはじめに、濃い甘口のお酒が主流であった中で、創業から引き継がれた製法を守りつつ、時代に合わせた味作りへの努力を続け、精米歩合50％・日本酒度＋10の特別な超からくちのお酒「三千盛」が誕生しました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=2151;
UPDATE breweries SET description='岐阜県各務原市に蔵を構える小町酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。長良川蔵元は、伝承技により、名水百選「長良川」の伏流水と安心できる国産酒米で旨みある酒を醸しております。酒は人が造るものでなく生物が醸すものという想いで、発酵力を最大限に引き出す事を重視し、 伝承技である醗酵自体の自然終息、つまりは酵母が自然な状態で発酵を終息するという「完全発酵」にて、 ”旨味”ある”ほっとする酒”を醸しております。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=2130;
