UPDATE breweries SET description='山口県周南市に蔵を構える株式会社中島屋酒造場は、文政6年（1823年）創業の歴史を誇る老舗酒蔵です。今や希少となった、江戸時代から伝承される正統的な醸造法である「生酛造り」で醸した酒名「カネナカ」。生酛（きもと）に起因する香り、味わいが個性豊かで、旨みとふくらみのある酸味が熱燗にも対応する腰の強さが特徴です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛・きもと・無濾過生原酒・無濾過・原酒', ''), brewing_features) WHERE id=1917;
