UPDATE breweries SET description='石川県金沢市に蔵を構える有限会社武内酒造店は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。仕込み水には良質な霊峰白山連峰雪解け伏流水（中軟水）を使用し、能登杜氏の伝統の技を受け継ぎながら、米の旨味を引き出す真摯な酒造りを追求しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=2241;
UPDATE breweries SET description='岐阜県中津川市に蔵を構える有限会社大橋酒造は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。対象商品は、1.8Lサイズの「吟醸」「純米」「本醸造」でございます。価格改定日　2026年7月1日ご注文分より　　　　　　　　今後も、創業以来受け継がれてきた伝統を大切にしながら、皆さまにご満足いただけ　　　　　　　る酒造りに励んでまいります。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('福田 清治', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=2156;
UPDATE breweries SET description='山口県萩市に蔵を構える八千代酒造合名会社は、明治20年（1887年）創業の歴史を誇る老舗酒蔵です。銘柄は、「君が代」の一節「千代に八千代に…」から、この酒を飲む人々の家系が行く末永く栄えることを祈って「八千代」と名付けました。また「La+ YACHIYO」の由来は、惑星同士の共鳴現象を提言した天文学者ラプラスの名前から着想、価値を加える「＋」の記号、スペルに含まれる「place=場所」等の意味を含んでいます。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=1931;
UPDATE breweries SET description='岐阜県高山市に蔵を構える有限会社舩坂酒造店は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。この美しい自然から生み出された湧水と良質な酒造米を用いて、代々続く伝統の技術で醸しだした日本酒をつくりあげています。自分用からプレゼントまで失敗しない選び方5つのポイントとおすすめ銘柄 上撰 深山菊 雪だるま徳利 【秋限定】特別純米深山菊　ひやおろし しぼりたて生酒　深山菊 みかん酒 蜜柑子-かんこ- 当店の銘柄をご紹介します。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('直伝', ''), president_name), toji_name=COALESCE(NULLIF('平岡誠治 一覧', ''), toji_name), opening_hours=COALESCE(NULLIF('8:30～18:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=2164;
UPDATE breweries SET description='岐阜県中津川市に蔵を構える山内酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。どの純米酒も、昔からの手順を守り、手作りにこだわり、手間を惜しむことなく作っています。仕込み水は、鉄分の多い山を避けて阿寺断層から湧き出る清水を濾過して使用しております。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('五百万石', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛・きもと・木桶', ''), brewing_features) WHERE id=2155;
UPDATE breweries SET description='岐阜県中津川市に蔵を構えるはざま酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。お酒を楽しむすべての方に Story of HAZAMA 恵那山の伏流水を仕込み水に使用 その清らかな水のごとく 最高の日本酒を世界の人々へ 最も大切なこと、 それは蔵人全員が という一つの目標に向かうこと。江戸中期より酒造りを始め、以来200年以上にわたり醸造業を営んでいます。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('案内 恵那山', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=2154;
UPDATE breweries SET description='岐阜県下呂市に蔵を構える奥飛騨酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。すっきり淡麗辛口とゆず果汁たっぷりのゆず酒・ゆず胡椒をセットにしました 奥飛騨 ゆず酒＆うめ酒 セット こだわりのゆず酒とうめ酒ができました。こちらから⇒初緑 純米大吟醸720ml、 初緑 美山錦720ml、 皆様のおかげで昨年10月に創業300年を、迎えることができました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('女将', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・美山錦・祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('山廃・無濾過生原酒・無濾過・原酒', ''), brewing_features) WHERE id=2167;
UPDATE breweries SET description='石川県金沢市に蔵を構えるやちや酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。今年も前田家由来の紫宸殿雛人形を飾りました 2/3(火)〜4/3(金)まで、前田家由来の紫宸殿雛人形を展示しております。観光メディア「Atlas Log」にて紹介されました 日本酒の伝統と革新が交差する場所──250年以上の歴史を持つ「やちや酒造」の新たな挑戦 大阪万博に出展します。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('組合主催自', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=2244;
UPDATE breweries SET description='山口県周南市に蔵を構える株式会社山縣本店は、明治8年（1875年）創業の歴史を誇る老舗酒蔵です。瀬戸内の豊かな気候で育った 山口県産のお米、伝統技術へのこだわり、 そして杜氏の瑞々しい感性で 防長鶴は美しく生まれ変わりました。その２つを総称して「防長（ぼうちょう）」、 さらに蔵の近くにナベヅルが飛来していたことから 創業時の銘柄は「防長鶴（ぼうちょうつる）」でした。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('以下蔵人', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・雄町・祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過生原酒・無濾過・原酒・長期熟成', ''), brewing_features) WHERE id=1913;
