UPDATE breweries SET description='石川県白山市に蔵を構える株式会社小堀酒造店は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。飲む人の心を豊かにする一杯の追求 2026.08.03代表取締役辞任ならびに今後の経営体制に関するご報告 流れいずる醗酵のまち鶴来で、 萬歳楽は「事のはじまり」を意味し、 古来より新たな門出で舞われた 「おめでたい舞楽」が由来。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('辞任', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・五百万石', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=2247;
