UPDATE breweries SET description='石川県河北郡津幡町に蔵を構える株式会社久世酒造店は、天明6年（1786年）創業の歴史を誇る老舗酒蔵です。創業天明六年(1786年)以来、自社の田にて独自の酒米(長生米)を作り、仕込み水は、(硬水)と(軟水)の2種類を使い分けて仕込んでおります。江戸時代から受け継がれる伝統の技で　飲む人の長生きを願って、心を込めて酒造りをしています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('9:00〜18:30', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('古酒', ''), brewing_features) WHERE id=2240;
UPDATE breweries SET description='岐阜県瑞浪市に蔵を構える中島醸造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。中島醸造の新鮮な酒粕をひとつひとつ丁寧に袋詰めされた純米吟醸の酒粕です。「帆船」　「歩み」　「忘れっぽい天使」の3点を使用した3種類のお酒を「始禄」銘柄にて発売。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛・古酒', ''), brewing_features) WHERE id=2148;
UPDATE breweries SET description='岐阜県高山市に蔵を構える有限会社原田酒造場は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。京都に近い灘・伏見の酒造りにいち早く注目した初代当主・打江屋長五郎は庄屋から酒屋へ事業転換すべく懸命に酒造りに専念したと伝わっております。以来、江戸・明治・昭和の激動の時代を十代にわたり清酒醸造を守り続けてきました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('案内 商品', ''), president_name), toji_name=COALESCE(NULLIF('菅田雅之', ''), toji_name), opening_hours=COALESCE(NULLIF('9:00 - 18:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=2166;
