UPDATE breweries SET description='石川県加賀市に蔵を構える松浦酒造有限会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。超軟水の仕込み水を生かしたやさしい味わいの食中酒として、穏やかな香りと食欲を誘う生き生きとした酸を大切にしております。日本の醸造酒は米と水と微生物達の神秘の力によって醸されており、糀の酵素は米のデンプン質を糖化するのはもちろん、さらにお料理の味わいをも糖化し味わいを膨らませてくれます。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('松浦 文昭', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・雄町・出羽燦々・八反錦・愛山', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('全量純米', ''), brewing_features) WHERE id=2255;
