UPDATE breweries SET description='埼玉県比企郡に蔵を構える松岡醸造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。そこに杜氏の腕と最新技術が加わることで「帝松」は生まれる。帝松の酒造りに使用しているこの特異な仕込み水は、地殻変動によって海が隆起してできた石灰岩の山々が連なる秩父山で濾過された天然水です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('代表取締役', ''), president_name), toji_name=COALESCE(NULLIF('自清酒鑑評', ''), toji_name), opening_hours=COALESCE(NULLIF('9:30～17:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・雄町・祝・備前雄町', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒・袋吊り・低温発酵', ''), brewing_features) WHERE id=2481;
