UPDATE breweries SET description='愛媛県西条市に蔵を構える石鎚酒造株式会社は、大正9年（1920年）創業の歴史を誇る老舗酒蔵です。石鎚酒造オフィシャルサイト｜食中に活きる酒造り - Simplified Chinese Traditional Chinese 手造りの酒を念頭において、大型の仕込みでは出来ない手作業が成せる、 私ども蔵元の姿勢と情熱を酒に表現しています。酒蔵の位置するこの地は、西日本最高峰「石鎚山」のふところで 名水の町として呼び声の高い愛媛県西条市にあり、仕込み水にこの石鎚山系の清冽な水を使用、西条・周桑平野の穀倉地帯を控えており、酒造りに非常に適した気候、風土の中にあります。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('家族中心', ''), president_name), toji_name=COALESCE(NULLIF('越智稔', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・雄町・愛山・備前雄町', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過・原酒・袋吊り', ''), brewing_features) WHERE id=2684;
UPDATE breweries SET description='埼玉県さいたま市に蔵を構える鈴木酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。創業150周年記念酒「究極のまるいお酒　π」発売開始しました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('埼玉', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('10:00～17:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過・原酒', ''), brewing_features) WHERE id=2501;
