UPDATE breweries SET description='愛媛県松山市に蔵を構える雪雀酒造株式会社は、大正4年（1915年）創業の歴史を誇る老舗酒蔵です。瀬戸内の穏やかな気候のなかで厳選した原材料と中硬水の仕込み水 そして、杜氏の技が三位一体となって醸しだされた雪雀至高の純米大吟醸酒。100年以上の伝統を誇る酒蔵が愛媛県産·山田錦を100%使用し、精米歩合38%まで警沢に磨き上げて生み出した純米大吟醸。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=2689;
UPDATE breweries SET description='埼玉県さいたま市に蔵を構える株式会社 小山本家酒造は、文化5年（1808年）創業の歴史を誇る老舗酒蔵です。｢金紋世界鷹｣ブランドサイト ｢東京盛｣ブランドサイト ｢おいしい大吟醸｣ブランドサイト About Koyamahonke 脈々と紡いできた技術と精神を大切に。創業者の小山屋又兵衛が、埼玉の良質な水を活かした酒造りに取り組んだことがきっかけでした。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=2512;
UPDATE breweries SET description='埼玉県上尾市に蔵を構える北西酒造株式会社は、明治27年（1894年）創業の歴史を誇る老舗酒蔵です。文楽をこよなく愛した創業者の亀吉は、この三位一体の精神を米、麹、水で造り出す日本酒に生かしたいという想いを込め、銘柄を"文楽"と命名しました。秩父からの質の良い中硬水を仕込み水につかい、蔵人が目指す酒質に合わせて吟味した酒米を丁寧に醸した文楽の日本酒は、淡麗な味わいが特徴です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('応援', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('雄町・愛山・赤磐雄町', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過生原酒・無濾過・原酒', ''), brewing_features) WHERE id=2490;
