UPDATE breweries SET description='愛媛県八幡浜市に蔵を構える梅美人酒造株式会社は、大正5年（1916年）創業の歴史を誇る老舗酒蔵です。【梅美人酒造】 創業から105年、愛媛県八幡浜市で日本酒、焼酎、リキュール、クラフトジンの製造販売を行っています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=2702;
UPDATE breweries SET description='埼玉県行田市に蔵を構える横田酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。横田酒造 – 埼玉の地酒 日本橋・浮城の醸造元 横田酒造は、文化2年（1805年）創業。『日本橋』の酒銘は、横田庄右衛門が若き頃、お江戸『日本橋」の酒問屋で修行し、独立する際、「初心忘れるべからず」との思いを込めて、自らの修行の地を酒銘にしたことに由来します。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('自醸酒鑑評', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・美山錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('きもと・山廃・無濾過生原酒・無濾過・原酒', ''), brewing_features) WHERE id=2510;
UPDATE breweries SET description='愛媛県西予市に位置する株式会社媛囃子は、昭和16年（1941年）に創業しました。仕込み水には良質な石鎚山系清冽伏流水（超軟水）を使用し、越智杜氏・伊予杜氏の伝統の技を受け継ぎながら、米の旨味を引き出す真摯な酒造りを追求しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=2708;
UPDATE breweries SET description='岡山県瀬戸内市に蔵を構える高祖酒造は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。天保元年（1830年）創業以来、うまくちの酒「清酒 千寿」を醸しております。高度に精米した岡山産の朝日米やアケボノと名水の誉れ高き吉井川の伏流水をふんだんに使い、寡黙で実直な熟練の杜氏が、その巧みな技を最後の一搾りにまで刻み込み醸造しております。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('発祥', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=3197;
