UPDATE breweries SET description='岡山県浅口市に位置する平喜酒造は、昭和3年（1928年）に創業しました。伝統の技と最新技術の融合した酒造りを行う、皆様に愛される酒蔵です。以来、歴史ある伝統工法を繋ぎながら機械技術も取り入れ、 うまい酒を作り続けています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('戸塚 堅二郎', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('雄町', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('四季醸造', ''), brewing_features) WHERE id=3208;
UPDATE breweries SET description='岡山県美作市に蔵を構える田中酒造場は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。田中酒造場/岡山県美作市の酒蔵 伝統の技法を守り続けて130年余(明治18年/1885年創業)の蔵元です。創業以来の銘柄で地元大原町・西粟倉・東粟倉を中心に美作町・兵庫県佐用方面までご愛飲いただいております。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('9:00～19:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・雄町', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('山廃・原酒', ''), brewing_features) WHERE id=3224;
UPDATE breweries SET description='岡山県赤磐市に蔵を構える利守酒造は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。「雄町」を栽培する農家、醸造を担当する職人、さらにそれを支える数多くの人々――。私が「軽部産・雄町米の復活を」と思い立った昭和40年代当時、清酒の大部分は「三増酒」と呼ばれる醸造用アルコールと糖類(ブドウ糖・水飴)、化学調味料などを多量に添加した、甘いベタベタとした酒でした。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('概要 蔵元情報', ''), president_name), toji_name=COALESCE(NULLIF('備前', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('雄町・赤磐雄町', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('山廃・古酒', ''), brewing_features) WHERE id=3195;
UPDATE breweries SET description='青森県上北郡七戸町に蔵を構える株式会社盛田庄兵衛は、安永6年（1777年）創業の歴史を誇る老舗酒蔵です。受け継いできたのは南部杜氏の伝統的手法と基本に徹する心の姿勢。私たちには『真心』という大切にしてきた銘柄があります。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('体制', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('華想い', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=3441;
