UPDATE breweries SET description='三重県四日市市に蔵を構える石川酒造株式会社は、天保元年（1830年）創業の歴史を誇る老舗酒蔵です。コンテスト受賞酒・人気商品 コンテスト受賞酒・人気商品 石川酒造は天保元年（１８３０年）創業。酒造りでは、手作りにこだわり、１つ１つの作業を丁寧に極力手作業で行っています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('石川 卓史', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=3803;
UPDATE breweries SET description='愛媛県松山市に蔵を構える水口酒造株式会社は、明治28年（1895年）創業の歴史を誇る老舗酒蔵です。1895年（明治28年）の創業以来130年の年月を超えて、道後温泉本館と共に歩み続け、この道後の地にて丁寧にお酒を造り続けています。初代水口大七郎から始まる水口酒造は、時代は変わっても頑固なまでに丁寧な酒造りを続けてきました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('代表取締役', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=2691;
UPDATE breweries SET description='青森県黒石市に蔵を構える株式会社鳴海醸造店は、文化3年（1806年）創業の歴史を誇る老舗酒蔵です。蔵に入ってからは、詰め口の手伝いと共に営業活動を行っていましたが、日本酒を取り巻く多くの方々と接するうち、その熱い思いに揺さぶられ、自分の酒造りに対する情熱も、日一日と大きく膨らんでいきました。日本の道百選にも選ばれたこの通りの一角に、文化三年（１８０６年）より続く造り酒屋、「稲村屋」こと鳴海醸造店があります。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('限定発売 限定品', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('華吹雪・華想い', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=3448;
