UPDATE breweries SET description='三重県四日市市に蔵を構える伊藤酒造株式会社は、弘化4年（1847年）創業の歴史を誇る老舗酒蔵です。熱燗のお話で盛り上がりましたので、限定セットを出品しております　くわしくはこちら 2024年11月26日 ジェントリさまに記事掲載「男性の休日を彩る伊藤酒造の日本酒｜伝統と革新が生んだ4つの『極上の一杯』を紹介」をいただきました。酒造準備期間～酒造期間中（9月～3月頃）は、醸造エリア外のみの見学とご説明、試飲の提供となりますのでご了承下さい。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('杜氏', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('山廃・古酒', ''), brewing_features) WHERE id=3804;
