UPDATE breweries SET description='青森県上北郡六ヶ所村に位置する六ヶ所地域振興開発株式会社は、平成18年（2006年）に創業しました。村では増産体制の確立、農商業、観光振興面への効果なども視野に入れ、 焼酎製造工場を２００６年（平成１８年）３月に完成させ、 「六趣醸造工房」と命名されました。2006年（H18年）3月六趣醸造工房として完成。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('10:00 - 15:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=3456;
UPDATE breweries SET description='青森県弘前市に位置する三浦酒造株式会社は、昭和5年（1930年）に創業しました。名前の由来、実は酒造りに適した米、酒米の「豊盃米」にあります。「豊盃」という名の由来は、その名のとおり豊かな盃という意味と、かつての津軽藩祖為信公が、戦で家臣が著しく志気喪失した時、志気を鼓舞するために唄った歌、いまでは津軽民謡として有名な「ホーハイ節」。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('三浦 剛史', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('8:30〜17:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・祝・亀の尾・華吹雪・華想い', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=3451;
UPDATE breweries SET description='岡山県津山市に蔵を構える多胡本家酒造場は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。加茂川の伏流水を汲み上げ、熟練の名杜氏と蔵人たちの技が加味された清酒です。吟味を重ねたこだわりの素材を使用し、非加熱・無濾過で酵母が生きています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('直売所 買', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過・原酒', ''), brewing_features) WHERE id=3223;
UPDATE breweries SET description='青森県十和田市に蔵を構える鳩正宗株式会社は、明治32年（1899年）創業の歴史を誇る老舗酒蔵です。地元の水、地元の米、そして地元の技によるメイドイン十和田にこだわった酒造りを続けています。酒造りについて詳しく知る 「和醸良酒（わじょうりょうしゅ）」 良い酒を造るには、技術はもちろん大事。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('稲本 修明', ''), president_name), toji_name=COALESCE(NULLIF('佐藤企', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('華吹雪', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('低温発酵', ''), brewing_features) WHERE id=3442;
