UPDATE breweries SET description='三重県四日市市に蔵を構える株式会社宮﨑本店は、弘化3年（1846年）創業の歴史を誇る老舗酒蔵です。三重の土地に鎮座まします伊勢神宮と 屋号に因んだ「宮」、鈴鹿連邦の山並みに積もる 「雪」を銘柄の由来とする宮の雪。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=3810;
UPDATE breweries SET description='三重県多気郡明和町に蔵を構える旭酒造株式会社は、明治8年（1875年）創業の歴史を誇る老舗酒蔵です。旭酒造 | 創業明治八年・伊勢志摩の酒蔵 創業明治八年・伊勢志摩の酒蔵 日本酒夏の日本酒、開栓後はどう保存する。歓迎会シーズンを自分のペースで楽しむ、悪酔いしないためのお酒のコツ🌸2026年3月25日料理二十四節気】雨水から啓蟄へ——“春の入口”を、伊勢の地酒で楽しむ2026年2月25日 日本の伝統と匠の技を守る 創業は明治八年。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=3817;
UPDATE breweries SET description='青森県八戸市に蔵を構える八戸酒類株式会社八鶴工場は、天明6年（1786年）創業の歴史を誇る老舗酒蔵です。清冽な自然水と、津軽・南部の豊富な良質米を用いて南部流儀の伝統技法と五感で醸す手造りの「八戸のうまし酒」です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('直売所', ''), president_name), toji_name=COALESCE(NULLIF('自醸清酒鑑', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・華吹雪・華想い', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛・山廃・無濾過・原酒', ''), brewing_features) WHERE id=3445;
UPDATE breweries SET description='三重県名張市に蔵を構える木屋正酒造株式会社は、文政元年（1818年）創業の歴史を誇る老舗酒蔵です。仕込み水には良質な名張川伏流水（赤目四十八滝水系）（中硬水）を使用し、蔵元杜氏の伝統の技を受け継ぎながら、米の旨味を引き出す真摯な酒造りを追求しています。歴史ある建造物は主屋・土蔵群が登録有形文化財としても親しまれており、伝統と革新を融合させた味わいを全国の日本酒ファンへ届けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('8:30〜17:30', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=3823;
UPDATE breweries SET description='三重県多気郡多気町に位置する井村屋株式会社は、令和3年（2021年）に創業しました。福和蔵は井村屋が製造・販売している日本酒銘柄です。当社においても日本酒の味を決める重要な要素としてテロワールにこだわり、三重県という豊かな風土で育まれた素材にこだわり、日々よりよい酒造りを行っています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('10:00～18:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('四季醸造', ''), brewing_features) WHERE id=3818;
UPDATE breweries SET description='三重県名張市に蔵を構える合名会社福持酒造場は、明治8年（1875年）創業の歴史を誇る老舗酒蔵です。仕込み水には良質な鈴鹿山脈・宮川清流伏流水（中軟水）を使用し、伊賀杜氏・丹波杜氏の伝統の技を受け継ぎながら、米の旨味を引き出す真摯な酒造りを追求しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=3824;
UPDATE breweries SET description='三重県三重郡菰野町に蔵を構える合名会社早川酒造は、大正4年（1915年）創業の歴史を誇る老舗酒蔵です。仕込み水には良質な鈴鹿山脈・宮川清流伏流水（中軟水）を使用し、伊賀杜氏・丹波杜氏の伝統の技を受け継ぎながら、米の旨味を引き出す真摯な酒造りを追求しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('交代', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=3805;
UPDATE breweries SET description='東京都あきる野市に蔵を構える野﨑酒造株式会社は、明治17年（1884年）創業の歴史を誇る老舗酒蔵です。仕込み水には良質な奥多摩山系・秩父古生層湧水（軟水）を使用し、越後杜氏・社員醸造の伝統の技を受け継ぎながら、米の旨味を引き出す真摯な酒造りを追求しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('五百万石・祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=4111;
UPDATE breweries SET description='岡山県赤磐市に蔵を構える室町酒造は、元禄元年（1688年）創業の歴史を誇る老舗酒蔵です。モンドセレクションにて２０００年より連続受賞中のこだわり酒。瀬戸契約栽培米 純米酒 瀬戸雄町 契約栽培圃場地「瀬戸地域」の雄町米を用いた純米酒。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('雄町', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過・原酒', ''), brewing_features) WHERE id=3194;
UPDATE breweries SET description='青森県三戸郡五戸町に蔵を構える八戸酒類株式会社五戸工場は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。清冽な自然水と、津軽・南部の豊富な良質米を用いて南部流儀の伝統技法と五感で醸す手造りの「八戸のうまし酒」です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('直売所', ''), president_name), toji_name=COALESCE(NULLIF('自醸清酒鑑', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・華吹雪・華想い', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛・山廃・無濾過・原酒', ''), brewing_features) WHERE id=3443;
UPDATE breweries SET description='東京都に蔵を構える土屋酒造株式会社は、明治6年（1873年）創業の歴史を誇る老舗酒蔵です。仕込み水には良質な奥多摩山系・秩父古生層湧水（軟水）を使用し、越後杜氏・社員醸造の伝統の技を受け継ぎながら、米の旨味を引き出す真摯な酒造りを追求しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=4118;
UPDATE breweries SET description='三重県名張市に蔵を構える瀧自慢酒造株式会社は、明治元年（1868年）創業の歴史を誇る老舗酒蔵です。Tweets by takijimann 契約栽培された伊賀産三重山田錦を35％まで精米した純米大吟醸。瀧自慢の銘柄の由来となった滝の伏流水が持つ仕込み水の柔らかさから、飲み飽きせずついつい杯を重ねたくなる、優しい飲み心地です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・雄町・吟風・備前雄町', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過', ''), brewing_features) WHERE id=3825;
UPDATE breweries SET description='三重県伊賀市に蔵を構える森喜酒造株式会社は、明治28年（1895年）創業の歴史を誇る老舗酒蔵です。すべての麹を伝統的な製法である「蓋麹法」と呼ばれる方法で造っています。酵母無添加の生酛、山廃酛 森喜酒造では2016年より生酛、山廃のお酒は酵母を添加せず、天然の乳酸菌と蔵付き酵母を取り込み、酒母を育てています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛・山廃・全量純米', ''), brewing_features) WHERE id=3820;
