UPDATE breweries SET description='岡山県浅口市に蔵を構える丸本酒造は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。常に問題意識をもち、新しい技術に関心をもち、飲み手の方々の意見を聞き、挑戦し続けていく姿勢が必要です。昭和7～11年（1932～36） 新型醸造機器・器具の導入、醸造場の建設により、増産をはかる。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('直送商品', ''), president_name), toji_name=COALESCE(NULLIF('自醸清酒品', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('古酒', ''), brewing_features) WHERE id=3209;
UPDATE breweries SET description='東京都八王子市に位置する東京八王子酒造は、平成26年（2014年）に創業しました。その面影を残す黒塀通りの一角に私たちの醸造所はあります。コンパクトでありながら充実の設備を取り揃えた都市型の醸造所は、少量生産かつ年間醸造が可能なマイクロブルワリーとして、1年を通して常にフレッシュで付加価値の高い酒造りを実現。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=4117;
UPDATE breweries SET description='青森県八戸市に蔵を構える八戸酒造株式会社は、元文5年（1740年）創業の歴史を誇る老舗酒蔵です。元文五年（一七四〇年）、初代駒井庄三郎が青雲の志で近江国を出、陸奥の地にて酒造りの道に入り、以来蔵元代々酒を造り続けてきました。現在、8代目庄三郎は青森県の地酒として県産の米と酵母にこだわり、仕込み水は八戸・蟹沢地区の名水を使用した、時代が求める環境と健康に配慮した安全で美味しい酒造りに挑戦しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('駒井 庄三郎', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=3446;
UPDATE breweries SET description='東京都港区に蔵を構える東京港醸造は、文化9年（1812年）創業の歴史を誇る老舗酒蔵です。明治時代に廃業しましたが、2011年、東京港醸造として復活。醸造責任者・寺澤善実のもと、都心で醸す唯一の酒蔵として、少量ながら新鮮で高品質な製品を皆様の元へお届けします。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=4116;
