UPDATE breweries SET description='三重県多気郡大台町に蔵を構える元坂酒造株式会社は、文化2年（1805年）創業の歴史を誇る老舗酒蔵です。それを実現する為に必要なのは、米が持つ本来の味をまっすぐに表現する技術、そして優れた原料米。米の旨味を感じさせる酒造り、伝統の山廃酛 日本酒は近年、技術力の飛躍的な進化の過程にあります。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('元坂 新', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('山廃', ''), brewing_features) WHERE id=3815;
UPDATE breweries SET description='東京都府中市に蔵を構える合名会社野口酒造店は、万延元年（1860年）創業の歴史を誇る老舗酒蔵です。江戸から明治へ大きく変遷していく時代に野口酒造店は創業しました。武蔵国の総社 大國魂神社の神人（じにん）という役職にあった野口家が神社の御神酒造りを依頼され当家初代、野口久兵衛が「中屋」と名乗り酒造りをはじめました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('野口英一郎 住所', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=4115;
UPDATE breweries SET description='千葉県流山市に蔵を構える流山キッコーマン株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。仕込み水には良質な房総丘陵・利根川水系伏流水（中軟水）を使用し、越後杜氏・南部杜氏の伝統の技を受け継ぎながら、米の旨味を引き出す真摯な酒造りを追求しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('社長 佐', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=4282;
UPDATE breweries SET description='東京都青梅市に蔵を構える小澤酒造株式会社は、元禄15年（1702年）創業の歴史を誇る老舗酒蔵です。仕込みの一本一本に対する真剣な心配りと、丁寧で優れた技があってこそ真に心のこもった酒が生まれてくるのだと信じております。秩父古生層の岩盤を掘り抜いた洞窟の奥から湧き出づる仕込水、連なる山々と豊かな緑、澄み切った奥多摩の空気、選りすぐった原料米、磨き上げた技。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('売店 芸術', ''), president_name), toji_name=COALESCE(NULLIF('樫村 信二', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=4108;
UPDATE breweries SET description='大阪府阪南市に蔵を構える浪花酒造有限会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。酒ディプロマ(SAKE DIPLOMA)二次試験論述対策⑳～琉球泡盛編 琉球泡盛～沖縄伝統の全麹仕込み 忙しい方は⑤のみをご覧ください。①前回（山口県）の復習 産業技術センターで開発された酵母４つはなんですか。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('成子 善一', ''), president_name), toji_name=COALESCE(NULLIF('優等賞', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('雄町・祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=3238;
UPDATE breweries SET description='千葉県成田市に蔵を構える滝沢本店は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。TAKIZAWA HONTEN ORIGIN長命泉の由来 成田山は江戸の時代より、 関東の霊場として賑わってまいりました。当蔵初代の滝澤栄蔵が成田詣での際 水の良さに感銘を受け、現在の地で酒屋をはじめました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('代表取締役', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('雄町・祝・備前雄町', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('中取り', ''), brewing_features) WHERE id=4277;
UPDATE breweries SET description='千葉県君津市に蔵を構える須藤本家は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。須藤本家 〜千葉 久留里の酒造〜 酒造りは事業にあらず、家業なり 明治18年から続く酒造りの伝統を守る一方で、 常に高品質で安定した酒造を行うために、 先進的な設備の導入を積極的に行っています。須藤本家ならではの蓄積された蒸留技術を活かしリリースされた「房総ウイスキー」は、自社製モルトと独自ルートで確保した英国産スコッチのブレンドで、スモーキーさは控えめ、日本人好みの華やかな甘い香りのフレーバーに仕上がっています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=4285;
UPDATE breweries SET description='千葉県君津市に蔵を構える宮崎酒造店は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。米（国産）、米こうじ（国産米）、醸造アルコール（国内製造） [ 　　　　　お召し上がり方：冷酒　　　　　 ]　　詳しい情報はこちら 峯の精 03 旨辛吟醸酒（ぎんから） [1979年　東京サミット乾杯酒］ ほのかに香る辛口の吟醸酒。米（国産）、米こうじ（国産米）、醸造アルコール（国内製造） [ お召し上がり方：冷酒、常温、ぬる燗、熱燗 ]　　詳しい情報はこちら この場所だから生まれた 自然の水に恵まれた、上総の地で150年。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=4284;
UPDATE breweries SET description='東京都東村山市に蔵を構える豊島屋酒造株式会社は、慶長元年（1596年）創業の歴史を誇る老舗酒蔵です。「屋守 純米中取」が東京代表として評価 今回のIWC2026では、当蔵の代表銘柄である 「屋守（おくのかみ） 純米中取」が、純米酒部門において高い評価をいただきました。ボトル、ラベル、外箱細部に至るまでこだわりぬいた、この上なく贅沢な逸品です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('直売所', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過・原酒', ''), brewing_features) WHERE id=4114;
UPDATE breweries SET description='千葉県松戸市に蔵を構える宝酒造株式会社は、1842年 (天保13年)年に創業しました。そして、それぞれの事業領域で常に環境適合の視点を大切に独創的で確かな技術に裏付けられた商品やサービスをみなさまに提供することで自然と社会と人間との調和をめざしています。「醸造」と「蒸留」という2つの酒造りの技術と知見をあわせもつ当社は、清酒・焼酎・チューハイといった「和酒」から、本みりんなど「和」の調味料、原料用アルコールまで、幅広いカテゴリーの商品を製造・販売しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('社長', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=4280;
UPDATE breweries SET description='千葉県富津市に蔵を構える小泉酒造は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。仕込み水には良質な房総丘陵・利根川水系伏流水（中軟水）を使用し、越後杜氏・南部杜氏の伝統の技を受け継ぎながら、米の旨味を引き出す真摯な酒造りを追求しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('自醸清酒鑑', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=4290;
UPDATE breweries SET description='千葉県君津市に蔵を構える森酒造店は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。明治初期の創業以来、１３０年余り、自然豊かな 房総丘陵の山里で、熟練された越後杜氏の技 のもと、あくまでも手造りにこだわりその伝統を 受け継いできた酒蔵です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=4288;
UPDATE breweries SET description='岐阜県飛騨市に蔵を構える有限会社渡辺酒造店は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。スタッフ紹介-お約束します 原材料や醸造技術にとことんこだわり続ける酒。享保17年（1732） 享保17年（1732）に渡邉家の初代久右衛門が当地で「荒城屋」と称して業を起こし、２代目久右衛門は両替業を始めると共に、生糸を製造して京都に販売し、産を成しました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過生原酒・無濾過・原酒', ''), brewing_features) WHERE id=2169;
UPDATE breweries SET description='三重県四日市市に蔵を構える丸彦酒造株式会社は、慶応3年（1867年）創業の歴史を誇る老舗酒蔵です。本醸造生貯蔵酒　三重の寒梅　Jr.が販売開始 大寒の日にしぼりあげた逸品　純米吟醸 三重の寒梅 大寒しぼり販売スタートしました 冬季限定商品　しぼりたて新酒「三重の寒梅 初しぼり720mℓ」販売開始 縁結び大学に紹介されました。本醸造生貯蔵酒　三重の寒梅　Jr.が販売開始 大寒の日にしぼりあげた逸品　純米吟醸 三重の寒梅 大寒しぼり販売スタートしました 三重の寒梅 初しぼりが登場 ホームページをリニューアルしました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('藤原 大地', ''), president_name), toji_name=COALESCE(NULLIF('運命的', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒・古酒', ''), brewing_features) WHERE id=3808;
UPDATE breweries SET description='千葉県君津市に蔵を構える吉崎酒造は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。この竹酒は独特の技法で節の間にかずさの名水・久留里の水で仕込んだ清酒を封じ込めてあります。独特の技法で節の間に清酒を封じ込めており、ほんのり甘く、まろやかな味わいのお酒「ふしぎな竹酒」を記念日などの特別な日のギフトにどうぞ。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=4286;
