UPDATE breweries SET description='千葉県勝浦市に蔵を構える東灘醸造は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。鳴海（なるか）醸造元 | 東灘醸造ホームページ 外房勝浦の地酒 東灘醸造 カツオの水揚げ高全国有数の漁業基地・外房勝浦に弊社は慶応三年創業しました。現在約200石のとても小さな蔵ですが、全量手造りによる丁寧な酒造りを続けています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('取締役社長 君塚', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('雄町', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=4296;
UPDATE breweries SET description='千葉県夷隅郡御宿町に蔵を構える岩瀬酒造は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。お酒造りのこだわり（超硬水仕込み） 蔵から10分程で「月の沙漠」と命名された御宿海岸が拡がっています。岩の井の力強い味わいは、その超硬水を仕込み水として使用していることから生み出されています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('岩瀬能和', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('9:00 〜 17:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('山廃・古酒', ''), brewing_features) WHERE id=4299;
UPDATE breweries SET description='千葉県山武市に蔵を構える梅一輪酒造は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。目標とする日本酒は、「料理にそっと寄り添う名脇役」 梅一輪の銘柄は、俳人　服部嵐雪の句「梅一輪　一輪ほどの　暖かさ」からとりました。創業以来、弊社はこの信念のもと地元に密着した酒造りと営業に邁進してまいりました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('古酒', ''), brewing_features) WHERE id=4300;
UPDATE breweries SET description='千葉県香取市に蔵を構える馬場本店酒造は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。熱い湯気が立ち上る蔵の中を行き交う人々の姿は、馬場本店酒造の伝統的な仕込み風景です。精米歩合35% 最上白味醂さいじょうしろみりん 国産もち米を使用し、江戸時代から手造りの製法を守っている伝統みりん。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('馬場 善広', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('9:00～17:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=4309;
UPDATE breweries SET description='千葉県銚子市に蔵を構える石上酒造は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。仕込み水には良質な房総丘陵・利根川水系伏流水（中軟水）を使用し、越後杜氏・南部杜氏の伝統の技を受け継ぎながら、米の旨味を引き出す真摯な酒造りを追求しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('石上藤吾 資本金', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=4304;
