UPDATE breweries SET description='千葉県香取市に蔵を構える飯田本家は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。小見川の酒蔵「飯田本家」銘酒大姫 大姫　純米・本醸造・生酒 飯田本家Information 清酒「大姫」の醸造元・飯田本家は、黒部川沿いに懐かしいただずまいを見せています。創業は明治10年（1877年）、以前から小見川で米問屋を営んでいました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=4312;
UPDATE breweries SET description='千葉県鴨川市に蔵を構える秀楽酒造は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。創業者・渥美金次郎は明治維新、横須賀藩主西尾氏に同行し、房総鴨川で一番美味しい湧き水を求めて当地に移住。当社秀楽は創業当時からの伝統の味を守りつつ、｢秀でた酒を楽しく｣という心意気をモットーに現代のニーズにも応えた日本酒を提供し続けます。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('渥美 俊行', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=4293;
