UPDATE breweries SET description='神奈川県足柄上郡大井町に蔵を構える石井醸造株式会社は、明治3年（1870年）創業の歴史を誇る老舗酒蔵です。石井醸造酒蔵見学について 蔵特有の濃醇な味わい。もろみを通常の三回に分けて仕込む「三段仕込み」ではなく、四回に分ける「四段仕込み」 にこだわり、最後の四回目の仕込みを、 通常の掛け米では用いない「もち米」を使うことによりでるコク、蔵特有の濃醇な味わいをぜひご賞味ください。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=4612;
UPDATE breweries SET description='千葉県香取市に蔵を構える東薫酒造は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。下総佐原に東薫酒造は、江戸時代の華やいだ文政８年（1825年）に創業しました。その伊能家は前述の通り、佐原で酒造業を営む名主であり東薫酒造の創業者は、伊能家に弟子入りし、酒造業を習得発展させたと伝えられております。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('熊谷茂夫 詳細', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=4308;
UPDATE breweries SET description='千葉県成田市に蔵を構える鍋店は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。一方、元禄２年 (1689年 ) に佐倉藩より現在の製造免許にあたる酒造株（1,050 株）を戴き、成田山門前にて醸造を開始しました。「不動」は 2004 年（平成 16 年）日本酒が持つ「米」「醸造」から生まれる味わいをより楽しんでいただきたいという想いから誕生しました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('取締役会長 大塚', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・彗星', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過・原酒', ''), brewing_features) WHERE id=4311;
