UPDATE breweries SET description='神奈川県愛甲郡愛川町に蔵を構える大矢孝酒造株式会社は、天保元年（1830年）創業の歴史を誇る老舗酒蔵です。仕込み水には良質な丹沢山系・箱根山系伏流水（中軟水）を使用し、南部杜氏・越後杜氏の伝統の技を受け継ぎながら、米の旨味を引き出す真摯な酒造りを追求しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=4618;
UPDATE breweries SET description='青森県上北郡おいらせ町に蔵を構える桃川株式会社は、明治22年（1889年）創業の歴史を誇る老舗酒蔵です。現代の技術と先人たちの知恵…続きを読む 桃川の大杉玉桃川の大杉玉について杉玉の歴史・由来について杉玉の発祥は、奈良県桜井市にある日本最古の神社、大神（おおみわ）神社にあると言われています。創業当時、百石川（現在の奥入瀬川の旧称）の水を使用していたことから「百（もも）」を果物の「桃（もも）」に代えて「桃川（ももかわ）」と名付けられました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('上田 友司', ''), president_name), toji_name=COALESCE(NULLIF('自醸清酒鑑', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=3444;
UPDATE breweries SET description='千葉県香取郡神崎町に蔵を構える寺田本家は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。創業以来、この生命あふれる水を仕込み水として使い続けています。重さにして15kgほどの蒸米を木桶に分け入れひょいと担いで蔵人は重さも忘れたように軽やかに走り、麻布をひろげたサナの上に、蒸米をザッと広げます。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('代表取締役', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('11:00～15:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('木桶', ''), brewing_features) WHERE id=4310;
