UPDATE breweries SET description='千葉県君津市に蔵を構える和蔵酒造貞元蔵は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。黒麹仕込み、二次仕込法など焼酎専用蔵だからこそ可能な伝統的製法を採用。和蔵酒造の酒を支え続ける「和蔵人（WAKURA-BITO）」 竹岡蔵オフィシャルFacebookページ WAKURA LINEUP 和蔵酒造の竹岡蔵で醸造している日本酒と貞元蔵で醸造している本格焼酎、リキュール。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('社長   原', ''), president_name), toji_name=COALESCE(NULLIF('制度', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過生原酒・無濾過・原酒・古酒', ''), brewing_features) WHERE id=4289;
