UPDATE breweries SET description='神奈川県厚木市に蔵を構える黄金井酒造株式会社は、文政元年（1818年）創業の歴史を誇る老舗酒蔵です。黄金井酒造-神奈川県あつぎの地酒 200年の歴史が育む、多彩な酒を生み出す蔵 1818年、東丹沢の麓・七沢の地に創業した黄金井酒造は、清酒づくりを礎に二百年の時を歩んできた蔵です。丹沢山系の清らかな水と、代々受け継がれてきた麹づくり・発酵の技をもとに、清酒「盛升 さかります」を中心とした酒造りを大切にしてきました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('直売所 日本酒', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('8:30～17:30', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=4619;
UPDATE breweries SET description='宮城県名取市に蔵を構える佐々木酒造店は、明治4年（1871年）創業の歴史を誇る老舗酒蔵です。明治4年（1871）の創業以来、「地酒はその土地の液体化である」をレガシーとして私たちは、この名取市閖上の地で酒をつくってきました。屋号を「浪の音」、銘柄を「宝船浪の音」としました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=4698;
UPDATE breweries SET description='宮城県遠田郡美里町に蔵を構える川敬商店は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。黄金が流れる沢の傍らで創業したことから、銘柄を「黄金澤」といたしました。創業から１２０年以来、主要銘柄として守り続け、日本全国をはじめ海外でもご愛顧いただいております。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('川名 眞紀子', ''), president_name), toji_name=COALESCE(NULLIF('川名 由倫', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('山廃・原酒', ''), brewing_features) WHERE id=4706;
UPDATE breweries SET description='青森県弘前市に蔵を構える株式会社松緑酒造は、明治37年（1904年）創業の歴史を誇る老舗酒蔵です。世界自然遺産である悠久なる白神山地 津軽の誇り、岩木山の伏流水を用い 青森の豊かな自然が育んだ酒造好適米を軸に 醸造アルコールを添加しない純米蔵として 現代に求められる安全で美味しいお酒を志し 更に新たな一歩を踏み出しています。創業から百年を越してなお 松の緑のように瑞々しく 次の百年を生きる古城の銘酒を目指しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・祝・華想い', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=3453;
