UPDATE breweries SET description='宮城県加美郡加美町に蔵を構える田中酒造店は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。1789年の創業以来、200年以上に渡って守りぬいた伝統的な酒造りで皆様に愛され続けています。日本有数の米どころであり昔から酒づくりが盛んなこの土地に、伊達藩随一の呉服商だった初代・田中林兵衛が寛政元年（1789年）に創業したのが田中酒造店です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛・きもと', ''), brewing_features) WHERE id=4704;
UPDATE breweries SET description='宮城県仙台市に蔵を構える仙台伊澤家 勝山酒造は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。わたしたちはこの“Samurai‑style（侍の流儀）”を、酒造哲学として醸造の隅々まで息づかせています。侍魂を宿す酒 仙台藩伊達家御用藏 勝山酒造 勝山酒造の創業家・伊澤家の始まりは、鎌倉時代の1190年。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('照井派', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('長期熟成', ''), brewing_features) WHERE id=4695;
UPDATE breweries SET description='岡山県岡山市に蔵を構える宮下酒造は、大正4年（1915年）創業の歴史を誇る老舗酒蔵です。宮下酒造は100年の歴史があり、日本酒は「極聖」、地ビールは「独歩」が代表銘柄です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('大集結', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・雄町・祝・愛山', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒・古酒', ''), brewing_features) WHERE id=3188;
UPDATE breweries SET description='宮城県気仙沼市に蔵を構える角星は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。創業以来「品質第一」を旨とし、端麗さの中にも旨味を感じる酒質を追求。水鳥記（みずとりき）「蔵の華」「山田錦」「雄町」「愛山」などを使った純米のラインナップ両國（金紋・金盃）（りょうごく）選りすぐりの酒造用米と伝統の技術で飲み飽きしないキリっとした辛口の酒です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('斉藤嘉一郎', ''), president_name), toji_name=COALESCE(NULLIF('伝統', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・雄町・愛山', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=4713;
UPDATE breweries SET description='宮城県栗原市に蔵を構える萩野酒造は、天保11年（1840年）創業の歴史を誇る老舗酒蔵です。私たちは、良いものを少しだけ造るというコンセプトのもと、日本酒独自の伝統や歴史を守りながら新しい技術も取り入れ、常に進化する酒造りを目指します。山と田んぼに囲まれ、蔵近くの山からこんこんと自然水が湧出する恵まれた環境の中、私たちは人の手をかけた手造りの酒造りに取組んでおります。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('佐藤 曜平', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('9:30～12:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛', ''), brewing_features) WHERE id=4711;
