UPDATE breweries SET description='神奈川県伊勢原市に蔵を構える吉川醸造株式会社は、大正元年（1912年）創業の歴史を誇る老舗酒蔵です。吉川醸造では、洗米から仕込み水まで全て、井戸から豊富に湧き出る良質な水を利用しています。吉川醸造の水は、日本では希少な硬度150～160の硬水（弱アルカリ性）。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('合頭 義理', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛・山廃', ''), brewing_features) WHERE id=4616;
