UPDATE breweries SET description='茨城県常総市に蔵を構える野村醸造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。野村醸造は、明治30年の創業以来、熟練の杜氏によって丹精を込めて、昔ながらの酒造りを行なっています。主に地元茨城県産の食材を使い無添加、手造りを基本として、和テイストの多彩な食品を展開しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('野村 一夫', ''), president_name), toji_name=COALESCE(NULLIF('指導', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=5510;
