UPDATE breweries SET description='茨城県笠間市に蔵を構える磯蔵酒造有限会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。ISOKURA SAKE BREWERY 創業明治元年、茨城県笠間市稲田にある磯蔵酒造です。「いい酒」というのは、環境に始まり、材料から醸造、流通、そして皆さんに飲んでいただく瞬間まで、たくさんの「人」に支えられてこそ初めて成り立ちます。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('11:00～18:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・五百万石・祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過生原酒・無濾過・原酒・袋吊り・氷温貯蔵', ''), brewing_features) WHERE id=5515;
UPDATE breweries SET description='福井県大野市に蔵を構える株式会社南部酒造場は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。失われようとしている技術や味を継承し、古き良きものから新しい創造を生み出すため、私たちは伝統的かつ挑戦的な酒造りを行っています。「手造りに徹して目の届く量を丁寧に醸し、より高品位の酒を世に送り出す」を理念に掲げ、純米酒にこだわった酒造りを行っています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('五百万石', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=5256;
UPDATE breweries SET description='福井県三方上中郡に蔵を構える鳥浜酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。大正９年の創業以来、ずっと守り続けてきたまろやかな甘口の味わい。地元・三方五湖特産のうなぎや鯉など、しっかりと味付けされた伝統料理に良く合う地酒です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・五百万石', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=5267;
