UPDATE breweries SET description='宮城県富谷市に蔵を構える内ヶ崎酒造店は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。製品ラインナップを見る 「昔ながらの造り」へのこだわり 少量生産の酒は、どの商品に対しても一本一本丁寧に仕込んでいます。酒造業は寛文元年（1661年）、二代目作右衛門の創業以来、350有余年県内屈指の歴史と伝統を誇っています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('情報 会社概要', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('美山錦・祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=4696;
UPDATE breweries SET description='茨城県笠間市に蔵を構える須藤本家株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。自然へのこだわりから、醸す商品は炭素濾過をしていない無濾過で、ほとんどが完全な生酒という世界でもまれな酒蔵です。こだわり その壱自然が織り成す奥深い味わい 当蔵は炭素濾過、その他諸々の濾過、遠心分離等人為的な濾過はバランスを崩すため、行っておりません。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・雄町・五百万石・美山錦・亀の尾', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛・無濾過', ''), brewing_features) WHERE id=5513;
