UPDATE breweries SET description='岩手県岩手郡雫石町に蔵を構える菊の司酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。活性炭素を一切使用せず、自然のままの味を大切にした無濾過にこだわり、素材本来の風味やコクをそのまま楽しめる純粋な味わいです。伝統と革新を両立させながら、次世代に向けた新しい酒造りにも挑戦しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過生原酒・無濾過・原酒・低温発酵', ''), brewing_features) WHERE id=5571;
UPDATE breweries SET description='岩手県花巻市に蔵を構える合資会社川村酒造店は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。創業者の川村ヨ右衛門（*）は、南部杜氏組合の設立に尽力し、副組合長として南部杜氏協会の基礎を造った重要人物。伝統の南部の酒造りを継ぎ、良質な酒米の米の持つポテンシャルを最大限に引き出しながら、完全発酵させ、コシが強くしっかりしたボディを持つキレよい酒を生む。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('川村 直孝', ''), president_name), toji_name=COALESCE(NULLIF('組合', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=5578;
