UPDATE breweries SET description='岩手県盛岡市に蔵を構える株式会社桜顔酒造は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。少⼦⾼齢化、後継者不⾜、景気低迷なに厳しい環境の中で、優れた技術や知識を持ちながらも、持ち味を⽣かし切れず成⻑が⽌まってしまう中⼩企業が多くあります。昔からながらのこの伝統の技は、今も杜氏たちに受け継がれ、守られてきています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('代表取締役', ''), president_name), toji_name=COALESCE(NULLIF('自醸清酒鑑', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=5569;
