UPDATE breweries SET description='茨城県つくば市に蔵を構える株式会社稲葉酒造は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。稲葉酒造 - 茨城県つくば市にある、伝統を土台に新しい酒造りに挑戦する酒蔵 男女川 みなのがわ筑波山神社の御神酒として、昔から造り続けられているお酒。なお、当日お酒をお召し上がりになれない方も 酒粕ジェラート、甘酒、仕込み水で淹れたコーヒー等を お楽しみいただけます。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('杜氏 稲葉伸子', ''), president_name), toji_name=COALESCE(NULLIF('稲葉伸子 全国', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・五百万石', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過生原酒・無濾過・原酒・直汲み・袋吊り', ''), brewing_features) WHERE id=5518;
UPDATE breweries SET description='宮城県大崎市に蔵を構える新澤醸造店は、明治6年（1873年）創業の歴史を誇る老舗酒蔵です。蔵人と共に寝食を忘れ「究極の酒造り」に力を注ぎ、2002年（平成14年）『究極の食中酒』銘柄「伯楽星」（商標登録第5312399号）が誕生致しました。一般的な日本酒精米は70%前後と言われておりますが、究極を追求し続けた結果、1%未満精米をも実現する技術を手に入れることができました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('新澤巖夫蔵', ''), president_name), toji_name=COALESCE(NULLIF('世界最高', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・雄町', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('長期熟成・古酒', ''), brewing_features) WHERE id=4702;
