UPDATE breweries SET description='香川県仲多度郡琴平町に蔵を構える西野金陵株式会社は、寛政元年（1789年）創業の歴史を誇る老舗酒蔵です。香川の地酒 日本酒の蔵元「金陵」こんぴらさんの御神酒醸造元 2026年8月17日（月）AM 2：00～4：00 クレジット決済サービス一次停止のお知らせ（2026年8月10日） 「金陵 父の日ギフト」絶賛受付中です。2,700万円 (自己資本150億円) 183名（パート・アルバイトを含む） 化学品事業本部創業：万治元年（1658年） 酒類部創業：寛政元年（1789年） 会社設立：大正7年（1918年）9月25日 こころをこめた酒造りで、食文化を創造。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('代表取締役', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=5593;
UPDATE breweries SET description='奈良県生駒市に蔵を構える菊司醸造 株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。大阪と奈良を結ぶ奈良街道の宿場町であった小瀬（おぜ）の地で、江戸時代の1705年（宝永2年）より酒造りを脈々と続けて、2005年に創業300年を迎えました。現在は蔵元自ら杜氏となって、高精白・手造り・小仕込・瓶燗・冷蔵庫貯蔵等、手間を惜しまずこだわりを持ってお酒を造っております。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=5783;
