UPDATE breweries SET description='奈良県奈良市に蔵を構える奈良豊澤酒造 株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。平成７年に発売するやいなや、当蔵を代表する人気銘柄に。そのため、創業以来、ほとんど機械化せずに手造りに徹した酒造りを行ってまいりました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('豊祝', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('14:00～21:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・雄町・祝・備前雄町', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒・低温発酵', ''), brewing_features) WHERE id=5780;
UPDATE breweries SET description='奈良県生駒市に蔵を構える上田酒造 株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。こだわり抜いた商品ラインナップ 上田酒造までのアクセス この季節、おすすめのお酒 ※焼酎やお米、奈良漬け等の取り扱いもございます。米・米麹及び水（またはこれらと醸造アルコール）を原料として特別に吟味して造ったお酒。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=5782;
UPDATE breweries SET description='茨城県潮来市に蔵を構える愛友酒造株式会社は、文化元年（1804年）創業の歴史を誇る老舗酒蔵です。クラシックな純米酒から独創的な味わいの限定酒まで幅広く取り揃えており、季節ごとの特別な銘柄もご用意しています。酒蔵見学や試飲などを通じて、日本酒の豊かな文化と伝統に触れていただきながら、オンラインでのご注文や店舗での販売も行っており、いつでもどこでも日本酒をお楽しみいただけます。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('八代目当主', ''), president_name), toji_name=COALESCE(NULLIF('自醸清酒鑑', ''), toji_name), opening_hours=COALESCE(NULLIF('9:00 ～ 17:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('雄町', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=5502;
UPDATE breweries SET description='茨城県猿島郡境町に蔵を構える萩原酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。仕込み水には良質な筑波山・久慈川水系伏流水（中軟水）を使用し、南部杜氏・越後杜氏の伝統の技を受け継ぎながら、米の旨味を引き出す真摯な酒造りを追求しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=5507;
