UPDATE breweries SET description='奈良県天理市に蔵を構える稲田酒造 合名会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。【稲田酒造】銘柄「黒松稲天」を造る清酒製造業 【稲田酒造】銘柄「黒松稲天」を造る清酒製造業 | 天理教の御神酒を扱う、創業1877年(明治10)の老舗の造り酒屋「稲田酒造」。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('近所', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=5785;
UPDATE breweries SET description='岩手県釜石市に蔵を構える株式会社浜千鳥は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。創業大正12年（1923年）、この地とともに。なかでも「ゆめほなみ 本醸造」は隣地の大槌町で発足した酒米研究会によって栽培された大槌町産米「吟ぎんが」を100%使用し、地元農家の方々と活発な意見交換会や各地へ視察に赴くなど地域に密着した酒造りを目指しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過生原酒・無濾過・原酒', ''), brewing_features) WHERE id=5583;
UPDATE breweries SET description='奈良県香芝市に蔵を構える株式会社 大倉本家は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。自家栽培米 ひのひかり で仕込んだこだわりの味。創業以来育んできた技法を守りつつ、個性ある質のよい酒造りを目指し 技術の研鑽に励んでいます。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('山廃', ''), brewing_features) WHERE id=5790;
UPDATE breweries SET description='岩手県紫波郡紫波町に蔵を構える高橋酒造店は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。1670年代に上方から取り入れられた大量仕込み樽の製法は、藩内で広まり、その製法を学んだ多くの杜氏（日本酒の醸造工程を行う職人集団）が現代に至るまで《南部杜氏》として日本各地で活躍しています。■堀の井（高橋酒造店） 「堀の井」の名前は、創業時に堀米の井戸の水で仕込んだお酒が美味しいと評判だったことからつけられました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('発祥', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=5576;
UPDATE breweries SET description='岩手県二戸市に蔵を構える株式会社南部美人は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。技術の伝承と究極の日本酒造りを目指す、 南部美人の日本酒づくりのこだわりを紹介いたします。酒造りは何年やっても、毎年が一年生 南部美人は、日本三大杜氏の筆頭に数えられる 南部杜氏の洗練された技術と伝統を現在に受け継ぎ、 この言葉を胸に日本酒造りに実直に取り組んでいます。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('直営店', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・美山錦・愛山', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=5588;
UPDATE breweries SET description='岩手県紫波郡紫波町に蔵を構える合名会社吾妻嶺酒造店は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。兄が蔵元、弟が杜氏の兄弟蔵｡ 一六八四年創業、生まれ変わったあづまみね。350年の歴史の中で様々なものが変化してきましたが、我々の心を込めた酒造りへの情熱は少しも変わっていません。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('発祥', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('美山錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=5575;
