UPDATE breweries SET description='茨城県常陸大宮市に蔵を構える根本酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。「一麹、ニ酛、三造り」と言われる日本酒造りには、厳選された材料と根本酒造400年の歴史にわたる蔵人たちの経験と技が生きています。伝統の技を守りながらも、その年の米、その日の気候に合わせて、酒に心を砕きながら、より美味しい酒を求めて造り続けてきました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('10:00 〜 16:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・美山錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=5531;
UPDATE breweries SET description='奈良県生駒市に蔵を構える株式会社中本酒造店は、享保12年（1727年）創業の歴史を誇る老舗酒蔵です。作宝楼についてランチ予約について 創業からまもなく300年。私たちは、唯一無二の旨い酒を造り続けるだけでなく、奈良と生駒の歴史と伝統を守りながら、これからの300年も地域にとって欠かせない存在でありたいと願っています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('自慢', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒・古酒', ''), brewing_features) WHERE id=5784;
UPDATE breweries SET description='奈良県北葛城郡広陵町に蔵を構える長龍酒造 株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。series吉野杉の樽酒─ Yoshinosugi no Tarusake ─ ニッポン伝統の酒「吉野杉の樽酒」 古来、お祝い事や行事には欠かせない樽酒の鏡開き。創業者が大いなる情熱をもって、幾多の困難を乗り越え、独自の製法を創りあげ、日本初の『瓶詰め樽酒』として昭和39年に誕生。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('飯田 豊彦', ''), president_name), toji_name=COALESCE(NULLIF('制廃止', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('雄町・祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=5792;
