UPDATE breweries SET description='香川県観音寺市に蔵を構える川鶴酒造株式会社は、明治24年（1891年）創業の歴史を誇る老舗酒蔵です。香川県産米へのこだわり お米の味わいを余さず詰め込んだような、旨みが心地よく広がるような味わいが「川鶴」のお酒の共通点です。四国霊場八十八カ所第69番札所である七宝山観音寺に由来する観音寺市は香川県の西 端に位置する町で、古銭・寛永通宝を模した巨大な砂絵「銭形砂絵」で知られます。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('川人 裕一郎', ''), president_name), toji_name=COALESCE(NULLIF('組合研究会', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('四季醸造', ''), brewing_features) WHERE id=5594;
UPDATE breweries SET description='滋賀県大津市に蔵を構える有限会社平井商店は、万治元年（1658年）創業の歴史を誇る老舗酒蔵です。仕込み水には良質な比良山系・鈴鹿山脈琵琶湖流入伏流水（軟水）を使用し、能登杜氏・丹波杜氏の伝統の技を受け継ぎながら、米の旨味を引き出す真摯な酒造りを追求しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=5982;
UPDATE breweries SET description='奈良県五條市に蔵を構える株式会社 山本本家は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。仕込み水には良質な伏見の白菊水（中硬水）を使用し、丹波杜氏の伝統の技を受け継ぎながら、米の旨味を引き出す真摯な酒造りを追求しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=5796;
UPDATE breweries SET description='奈良県御所市に蔵を構える葛城酒造 株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。昔ながらの手作業で手間をかけることで微妙な味と個性の伝統を守っています。特に最近は醸造造りが多くなにより繊細に綿密な味に仕上がっているため微妙な変化についていけない酒も存在します。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('8:30～17:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('五百万石', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=5794;
UPDATE breweries SET description='奈良県吉野郡下市町に蔵を構える藤村酒造 株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。厳寒の醸造期において醸し出された 一級品の酒を造っております。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=5804;
UPDATE breweries SET description='奈良県奈良市に蔵を構える株式会社 今西清兵衛商店は、明治17年（1884年）創業の歴史を誇る老舗酒蔵です。味、コク、香り、すべての点で高品質を誇った南都諸白の伝統を現在に伝えることが、春鹿創業以来の変わることなき姿勢です。これからも春鹿の製造理念である「米を磨く・水を磨く・技を磨く・心を磨く」に基づき、辛口を中心に高品質な酒の醸造に専念していきます。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('社長 今', ''), president_name), toji_name=COALESCE(NULLIF('古川次郎 入蔵', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('氷温貯蔵', ''), brewing_features) WHERE id=5779;
UPDATE breweries SET description='香川県綾歌郡綾川町に蔵を構える綾菊酒造株式会社は、寛政2年（1790年）創業の歴史を誇る老舗酒蔵です。綾菊酒造は創業当時から地元香川県産米での酒造りを基本としており、特にオオセトでの酒造りは国重名誉杜氏が過去に10年もの歳月を掛け、研究に研究を重ねて築き上げた歴史があり、綾菊として非常に強い想いのある米です。蔵のある綾川町山田地区では平成16年ごろまで香川の酒米として「オオセト」がたくさん栽培され、綾菊酒造もその地元で獲れた米を使用して日本酒を醸造しておりました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・雄町', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=5590;
UPDATE breweries SET description='香川県小豆郡小豆島町に蔵を構える小豆島酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。ここから見上げた場所にある宮山には醸造の神様、松尾神社が鎮座しているほど。醤油造りだけでなく、食品加工業も盛んな小豆島には香川県産業技術センター発酵食品研究所があります。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=5589;
UPDATE breweries SET description='奈良県御所市に蔵を構える油長酒造 株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。About私たちの酒造り 古典技法に現代技術を重ね合わせ今だからできる酒造り 奈良に伝わる、寺院醸造を探求する酒造り ※鷹長は御所まち蔵で醸造しています。「古の奈良に伝わる忘れ去られた技法を、当時の文献を頼りに現代の醸造家が再現する」をブランドメッセージとして、「水端」を醸しております。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('愛山', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('木桶・無濾過', ''), brewing_features) WHERE id=5793;
UPDATE breweries SET description='茨城県つくば市に蔵を構える合資会社浦里酒造店は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。仕込み水には良質な筑波山・久慈川水系伏流水（中軟水）を使用し、南部杜氏・越後杜氏の伝統の技を受け継ぎながら、米の旨味を引き出す真摯な酒造りを追求しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('自醸清酒鑑', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・五百万石・美山錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=5519;
UPDATE breweries SET description='奈良県奈良市に蔵を構える倉本酒造 株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。寒暖差の大きいこの地で良質な稲を育て、 自社の山で採取される山水を汲む…… 1871年の創業から今日に至るまで、 倉本酒造は、地の利を活かした酒造りをしてきました。その伝統を継承しながら、 この土地、この蔵だからできる日本酒の新たなスタンダードを目指して。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('有志', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('木桶・古酒', ''), brewing_features) WHERE id=5781;
UPDATE breweries SET description='岩手県一関市に蔵を構える世嬉の一酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。一人蔵人作業 今年の東北魂ビールプロジェクトのビール醸造しました。奥羽山脈より湧き出づる地下水と、厳選された酒米を吟醸酒造りに定評がある南部杜氏の技で醸す、世嬉の一酒造の日本酒。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('佐藤 航', ''), president_name), toji_name=COALESCE(NULLIF('部屋', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・五百万石', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('長期熟成・古酒', ''), brewing_features) WHERE id=5580;
UPDATE breweries SET description='滋賀県草津市に蔵を構える古川酒造有限会社は、明治元年（1868年）創業の歴史を誇る老舗酒蔵です。草津の水・風土・近江米にこだわり、自然の中で時間と手間を厭わず丹精込めた伝統の手作りを行っております。古川酒造では、地元滋賀県が開発した近江米「みずかがみ」と、湖南アルプスから琵琶湖に注ぐきれいな伏流水を使い、明治以前の創業時から現在も変わらず「佐瀬式木槽絞り」でお酒を絞ります。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('9:30～18:30', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('木桶', ''), brewing_features) WHERE id=5985;
UPDATE breweries SET description='滋賀県甲賀市に蔵を構える望月酒造株式会社は、寛政元年（1789年）創業の歴史を誇る老舗酒蔵です。仕込み水には良質な比良山系・鈴鹿山脈琵琶湖流入伏流水（軟水）を使用し、能登杜氏・丹波杜氏の伝統の技を受け継ぎながら、米の旨味を引き出す真摯な酒造りを追求しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=5994;
UPDATE breweries SET description='香川県綾歌郡綾川町に蔵を構える勇心酒造株式会社は、安政元年（1854年）創業の歴史を誇る老舗酒蔵です。ものづくりに込めた哲学 About RICEPOWER ライスパワー®エキスについて お米と独自の発酵技術から生み出した「ライスパワーエキス」を使用した商品や、昔ながらの手造りのお酒をお届けしています。造り酒屋として創業した勇心酒造は、香川の豊かな自然の恵みのもとお酒造りに打ち込んできました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('徳山 孝仁', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=5591;
