UPDATE breweries SET description='奈良県吉野郡吉野町に蔵を構える株式会社 北岡本店は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。北岡本店は、「日本古来の酒造り技術を伝承し、おいしい酒を通じて、心温まる人間関係の成立に寄与する」をめざすものとして酒造りに取り組んでいます。「やたがらす」の北岡本店はその宿場町の中心地に店を構え、創業者惣兵衛は古金屋（換金、手形の取扱い）を営んでいたといい、七代目になって惣十郎が明治元年（1868）酒、醤油、油造り等の事業を一本化し、酒造業専業に切り替えました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('北岡 篤', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('9:00～17:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=5803;
UPDATE breweries SET description='滋賀県甲賀市に蔵を構える美冨久酒造株式会社は、大正6年（1917年）創業の歴史を誇る老舗酒蔵です。豊かな自然、清らかな水、そして職人の技が織りなす、深く、やさしく、心に残る味わい。その両方の技術を駆使して、天からの恵みによって育まれた お米の旨味を最大限活かして醸し出す純米譲造。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('代表取締役', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('山廃', ''), brewing_features) WHERE id=5988;
