UPDATE breweries SET description='滋賀県湖南市に蔵を構える北島酒造株式会社は、文化2年（1805年）創業の歴史を誇る老舗酒蔵です。8月の量り売りは、7月27日(木）～29日(土）「湖の凪　生酛　八〇　火入」です。繊細で多様な味の表現の決め手は、伝統製法に裏付けされた確かな技にあります。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('近江', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('9:00～17:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝・渡船', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛・きもと', ''), brewing_features) WHERE id=5986;
UPDATE breweries SET description='滋賀県長浜市に位置する佐藤酒造株式会社は、平成22年（2010年）に創業しました。ひと夏冷温熟成させたこだわりの秋限定酒「湖濱　純米吟醸酒　ひやおろし」の販売がいよいよ始まります!　売切れ御免!! いよいよ2019新酒「湖濱しぼりたて」、活性濁り酒「しろうま」販売開始いたします。酒粕にこだわりお肌への保湿力を追求した『酒粕パック』誕生!! 特別純米酒 湖濱から生み出された“酒粕”を使用した贅沢な酒粕パックです。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('佐藤硬史 住所', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過生原酒・無濾過・原酒・古酒', ''), brewing_features) WHERE id=6004;
UPDATE breweries SET description='奈良県桜井市に蔵を構える西内酒造は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。【談山】西内酒造 – 【談山】「大名庄屋酒」「貴醸酒」「累醸酒」「卑弥呼の里」など数々の賞を受賞したお酒を代表する奈良県桜井市の明治初期創業の小さな酒造酒造『西内酒造』 大名庄屋酒酒蔵の香り高い、酵素・酵母の活きたフレッシュな、にごり酒。貴醸酒仕込み水の代わりに日本酒で仕込んだ贅沢な日本酒。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('古酒', ''), brewing_features) WHERE id=5799;
