UPDATE breweries SET description='滋賀県草津市に蔵を構える太田酒造株式会社は、明治7年（1874年）創業の歴史を誇る老舗酒蔵です。遠祖「道灌」の徳を偲んで 草津 道灌蔵・不盡蔵 主銘柄である日本酒「道灌」や「湖弧艪」をはじめ、様々な酒類は不盡蔵にて造っております。米を磨き、技を磨き、心を磨いて、感動のある酒造りをしませんか。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('滋賀県草津', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('山廃', ''), brewing_features) WHERE id=5984;
UPDATE breweries SET description='滋賀県蒲生郡に蔵を構える松瀬酒造株式会社は、万延元年（1860年）創業の歴史を誇る老舗酒蔵です。《（県名）トロフィー》は各カテゴリーにおける最高賞《トロフィー》にはわずかに及ばなかったものの高い評価を得た次席の銘柄に授与される賞です。「松の司」であるためには、地元で育んだ酒米や地下120Mから吸上げる仕込み水など地元素材のセレクトから始まります。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('松瀬 忠幸', ''), president_name), toji_name=COALESCE(NULLIF('自醸清酒品', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('渡船', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛', ''), brewing_features) WHERE id=5995;
UPDATE breweries SET description='滋賀県甲賀市に蔵を構える笑四季酒造株式会社は、明治25年（1892年）創業の歴史を誇る老舗酒蔵です。当社の基幹となる商標「笑四季」は、創業２代目竹島仙治郎により命名されました。笑四季の哲学である「天地自然の理に従う」のもとに、滋賀県内、そして我々の目の届く範囲だけの優良な原料米を選びぬき、手作業と最新技術の融合により、五感を研ぎ澄ませながら寒造りを行なっております。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('代表取締役', ''), president_name), toji_name=COALESCE(NULLIF('竹島充修', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('雄町・渡船', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過', ''), brewing_features) WHERE id=5989;
