UPDATE breweries SET description='滋賀県甲賀市に蔵を構える藤本酒造株式会社は、明和元年（1764年）創業の歴史を誇る老舗酒蔵です。Toggle navigation 重厚な山廃仕込と淡麗な吟醸造りという異質なものの調和を目指す。『和醸良酒』（働く蔵人の和があれば、自然と良い酒が醸し出せるという当蔵創業者の理念）のもと、チームワークを重視し円滑な人間関係を築くということを常に念頭に置いて清酒を醸しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('代表取締役 藤本', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('山廃・無濾過生原酒・無濾過・原酒', ''), brewing_features) WHERE id=5987;
