UPDATE breweries SET description='富山県魚津市に蔵を構える株式会社魚津酒造は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。魚津酒造の前身、本江酒造は「北洋」の醸造を開始しました。立山山麓の豊富な伏流水に地元魚津の風を吹き込み、様々なアイデアと技術で「北洋・帆波」を進化させてきました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('秘書 道又', ''), president_name), toji_name=COALESCE(NULLIF('富居 純一', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=6073;
UPDATE breweries SET description='徳島県阿南市に蔵を構える津乃峰酒造㈱は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。弊社は創業昭和28年より、日本一社の津峯神社の御神酒として「清酒津乃峰」を醸造してまいりました。『山は津乃峰、酒は津乃峰』のキャッチと共に半世紀、皆様のますますのご繁栄を祈念しつつ、日々醸造技術向上に取り組んでおります。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=6045;
UPDATE breweries SET description='奈良県香芝市に蔵を構える澤田酒造 株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。基本に忠実でありながらも既成概念にとらわれず、向上心と情熱、丁寧さをもって臨む澤田酒造の酒造り。濃厚な旨味と爽やかな酸味が融合する奈良酒の良き伝統を継承した清酒『歓喜光』。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('七代目当主', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=5789;
UPDATE breweries SET description='滋賀県長浜市に蔵を構える冨田酒造有限会社は、天文3年（1534年）創業の歴史を誇る老舗酒蔵です。地元の農家に酒米栽培を依頼、米を削りすぎない低精白純米酒や、無農薬栽培米・在来種復刻米の醸造にも取り組みます。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('神力', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛・木桶', ''), brewing_features) WHERE id=6005;
UPDATE breweries SET description='奈良県御所市に蔵を構える千代酒造 株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。奈良の地酒 「篠峯」「櫛羅」 醸造元 千代酒造 『美味しすぎないお酒』が美味しくなること お酒を造るうえでいわゆる『美味しいお酒』を造る事は可能な時代になってきました。しかしながら、そのお酒をさまざまな個性に分けていくベースは仕込み水ですので、日本酒は”米の酒”であると同時に”水の酒”であるともいえます。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=5795;
UPDATE breweries SET description='富山県に蔵を構える千代鶴酒造合資会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。銘柄の由来の文字起こし 製造工場のある地域は大昔、桜井と云われその地に水を供給している川を桜井川 と称した初代。当時裏の間に折々丹頂鶴の舞い降り遊ぶのを見て自分の生還を祝って来たもの 解し、酒の銘柄を目出度い千代鶴と改した 四代の今日もその目度い銘柄を継承している 初代が耕三、2代目が義平、3代目が知義という事が分かります。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('黒田 一義', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=6074;
UPDATE breweries SET description='富山県富山市に蔵を構える株式会社桝田酒造店は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。明治初期桝田家初代兵三郎は長男亀次郎とともに岩瀬から北海道旭川に渡り酒造業を起こします。妻の願いを受け亀次郎は帰郷を決意、明治38年より岩瀬の地にて「岩泉」の銘柄で再び酒造りを始めます。歴史ある建造物は国登録有形文化財・重要伝統的建造物群としても親しまれており、伝統と革新を融合させた味わいを全国の日本酒ファンへ届けています。', description_generated=1, president_name=COALESCE(NULLIF('桝田隆一郎', ''), president_name), toji_name=COALESCE(NULLIF('三盃幸一', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・雄町・山田穂', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=6076;
UPDATE breweries SET description='富山県下新川郡朝日町に蔵を構える林酒造場は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。寛永３年創業400年見つめ続けた富山の風土と魂 良い酒をよりおいしく味わっていただくため製造量は少なくとも手造りに徹し富山の地酒の文化を伝承しています。林酒造場は、江戸時代、加賀藩最大の関所“境関所”に武士として勤めた創業者が、寛永3(1626)年、傍らに酒を造ったのが最初とされています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('9:00～17:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・雄町・五百万石・祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=6070;
UPDATE breweries SET description='徳島県鳴門市に蔵を構える㈱本家松浦酒造場は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。仕込み水には良質な吉野川水系・四国山地伏流水（軟水）を使用し、阿波杜氏の伝統の技を受け継ぎながら、米の旨味を引き出す真摯な酒造りを追求しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('10:00 ～ 18:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=6047;
UPDATE breweries SET description='富山県富山市に蔵を構える玉旭酒造有限会社は、1948年 (昭和23年)年に創業しました。淡麗辛口まろやかな口当たり 低温長期型の吟醸造りで仕込み、吟醸香が高く、淡麗辛口にしてまろやかな口当たり特徴です。淡麗な中にコクと旨みのある昔ながらの辛口本醸造。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過・原酒', ''), brewing_features) WHERE id=6080;
UPDATE breweries SET description='奈良県橿原市に蔵を構える喜多酒造 株式会社は、享保3年（1718年）創業の歴史を誇る老舗酒蔵です。創業者の喜多利兵衞（きたりへい）は生来のこだわり者で、水と米を選りすぐり、自身が納得いくまで酒屋として旗揚げしなかったと伝え聞いています。そんな創業者の意思を受け継ぎ、私たちは三百年におよび「美味しいお酒」にこだわり続けています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('見学', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=5787;
