UPDATE breweries SET description='徳島県美馬市に蔵を構える司菊酒造㈱は、明治29年（1896年）創業の歴史を誇る老舗酒蔵です。素材にこだわり、手仕事を増やし、米、米麹のみで醸す純米酒造りを追求しています。バッコス amazon店 司菊酒造について | 司菊酒造 代表取締役社長　久岡 征司 徳島県美馬市美馬町字妙見93 0883-63-6061 0883-63-4930 1896年（明治29年） 銘柄を「鬼龍（きりゅう）」として創業。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('代表取締役', ''), president_name), toji_name=COALESCE(NULLIF('手造', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=6050;
