UPDATE breweries SET description='山梨県北杜市に蔵を構える株式会社八巻酒造店は、文久2年（1862年）創業の歴史を誇る老舗酒蔵です。八巻酒造店 山梨県北杜市 酒造店 日本酒 地酒 純米大吟醸酒 純米酒 伝統の味を守り、未来へつなぐ 八巻酒造店は、文久二年(1862年)の創業、150年以上の歴史を持つ由緒ある蔵元です。私たちは、「時流に流されず、芯がぶれずに、伝統の味を受け継いでいく」という信念のもと、地元の水と米にこだわった、地域に根差した酒造りを続けております。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=6162;
UPDATE breweries SET description='富山県に蔵を構える富美菊酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。小規模ながら強い意思とこだわりを持って、 高品質の酒造りに臨んでいます。1916年創業の富山の酒造会社が、新たな伝統となる革新の酒造りに挑戦する。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('杜氏', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・雄町・五百万石', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過生原酒・無濾過・原酒・四季醸造・瓶燗火入れ', ''), brewing_features) WHERE id=6077;
