UPDATE breweries SET description='富山県富山市に蔵を構える吉乃友酒造有限会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。静寂と情熱が同居する「暁（あかつき）」、そして光の躍動を体現した「晄（ひかり）」の2種類をぜひお楽しみください。私たちは純米酒蔵としての誇りを胸に、精米から酒造りに至る全工程において、徹底したこだわりを追求してきました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('代表取締役 三井', ''), president_name), toji_name=COALESCE(NULLIF('杜氏 青木', ''), toji_name), opening_hours=COALESCE(NULLIF('8:00～17:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・五百万石', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=6078;
UPDATE breweries SET description='山梨県大月市に蔵を構える笹一酒造株式会社は、寛文元年（1661年）創業の歴史を誇る老舗酒蔵です。自家井戸から湧き出る御前水を仕込水として使用し、地元で契約栽培された山田錦や夢山水といった酒造好適米を贅沢に使用し、手作りで丁寧にお酒にしています。後に花田屋を継承し、初代蔵元となった天野久が、1919年に現在の笹一酒造と改名して統合した三百有余年の歴史を持つ会社です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('天野  怜', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過生原酒・無濾過・原酒', ''), brewing_features) WHERE id=6170;
