UPDATE breweries SET description='群馬県渋川市に蔵を構える聖酒造株式会社は、天保12年（1841年）創業の歴史を誇る老舗酒蔵です。上州赤城山西南麓の自然水と蛍の舞う緑豊かな自然環境の中で酒造りを始め、八代１8０年の長きにわたりその伝統と技を継承しています。日本酒一覧を見る 聖酒造の酒造り創業天保12年(1841年) 清酒【かんとうのはな】醸造元酒蔵について 創業天保12年(1841年) 聖酒造の直営店です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・雄町・五百万石・渡船', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛・原酒・中取り', ''), brewing_features) WHERE id=6529;
UPDATE breweries SET description='群馬県藤岡市に蔵を構える松屋酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。醸造元の合名会社田島酒造店様が閉業して地元のお客様から復活の要望を頂いておりました。長年の歴史を持つ伝統的な銘柄ですので弊社も責任を持って製造を引き継いで行きます。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・五百万石・祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=6536;
UPDATE breweries SET description='徳島県三好市に蔵を構える芳水酒造㈲は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。代々受け継がれる技と心でひとつひとつ丁寧に醸し出されるその味わいは、飲む人々の心に深く染み渡り、人と人との絆を深めます。自然の恵みと職人の技が融合した私たちの酒を、ぜひ大切な人と共にお楽しみください。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=6054;
UPDATE breweries SET description='北海道亀田郡七飯町に位置する箱館醸蔵 有限会社は、令和3年（2021年）に創業しました。道内では比較的温暖な気候、肥沃な土壌、そして生産者の情熱が育む酒米は、大きく粒が揃い、タンパク質の含有率が低く、酒に品の良い旨味をもたらします。また、箱館醸蔵では『四季醸造』を取り入れています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('東谷浩樹', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('吟風・彗星・きたしずく', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('四季醸造', ''), brewing_features) WHERE id=6552;
