UPDATE breweries SET description='千葉県山武市に蔵を構える守屋酒造は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。産学連携　焼酎の仕込 委託醸造 《産学連携での焼酎造りについて》 先日ウイスキーの話をしていたところ、蒸溜の取り組みについて多くの方からお問い合わせをいただきました。) 白砂清松、豊かな自然環境に育まれた千葉県九十九里の酒蔵「守屋酒造」は、個性輝く蔵元として明治二十六年の創業以来百三十余年、皆様に愛され続けて参りました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('神力', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛・きもと・原酒・長期熟成', ''), brewing_features) WHERE id=4301;
UPDATE breweries SET description='群馬県沼田市に蔵を構える大利根酒造有限会社は、明治35年（1902年）創業の歴史を誇る老舗酒蔵です。日本酒には日本の文化・技術・歴史のすべてが入っています。大自然に育まれ、伝統手法により醸し出された手造り地酒の逸品。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('代表取締役', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('9:00 〜 18:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=6541;
UPDATE breweries SET description='富山県氷見市に蔵を構える株式会社高澤酒造場は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。髙澤酒造場は、昔ながらの手作りにこだわり「槽搾り」を守り伝えている酒蔵です。清酒 有磯 曙 醸造元 髙澤酒造場 オンラインストア営業日 今月(2026年8月) 翌月(2026年9月) (      発送業務休日) お支払いについて ●銀行振込 ・合計商品代金＋送料をお振込みください。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('髙澤 龍一', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・五百万石', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=6081;
UPDATE breweries SET description='奈良県宇陀市に蔵を構える株式会社 久保本家酒造は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。奈良・宇陀の豊かな自然の懐で、久保本家酒造は創業以来、自然の力を信じる酒造りを続けてきました。伝統の技と、悠久の時間が育む、唯一無二の味わいをお届けします。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('久保 順平', ''), president_name), toji_name=COALESCE(NULLIF('加藤', ''), toji_name), opening_hours=COALESCE(NULLIF('8:00〜17:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛・きもと', ''), brewing_features) WHERE id=5801;
UPDATE breweries SET description='北海道函館市に位置する函館五稜乃蔵株式会社は、令和3年（2021年）に創業しました。地元の「亀尾町産」をはじめとする厳選した北海道産の酒造好適米と地元の水を使用し、 手造りの伝統的な手法で1本1本のもろみを丁寧に仕込む、 小仕込み・高品質の酒造りをしていき、 函館をはじめとする多くの人が喜んでくれる地酒を目指していきます。函館空港から車で15分、南茅部地区の縄文遺跡やトラピスチヌ修道院にも近いアクセスの良いところ、 魚介類をはじめとした函館の美味しい食にあった地酒を造り、多くの方に訪れていただけるよう 醸造過程をご覧いただける直営Shopも充実しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('漆嵜 照政', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('吟風・彗星・きたしずく', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=6553;
UPDATE breweries SET description='北海道磯谷郡蘭越町に蔵を構える株式会社 森ノ醸造所は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。森ノ醸造所 | Mori No Brewery – 北海道蘭越の大地で生まれた―雪、火、海、森。米と米麹、醸造家の思想と技術が織りなすSparkling Sake。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('10:00-15:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=6551;
UPDATE breweries SET description='鹿児島県いちき串木野市に蔵を構える濵田酒造株式会社は、明治元年（1868年）創業の歴史を誇る老舗酒蔵です。現在は伝兵衛蔵・傳藏院蔵・金山蔵という3つの蔵を有し、各々の蔵が『伝統』『革新』『継承』という弊社の核となる焼酎づくりの理念を体現しています。革新の原点伝統の黒麹仕込み だいやめ～DAIYAME～ 後世へ語り継ぎたい「だいやめ文化」への想いを込めた創業150年目の逸品。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('木桶・原酒', ''), brewing_features) WHERE id=6172;
UPDATE breweries SET description='北海道釧路市に蔵を構える福司酒造株式会社は、大正8年（1919年）創業の歴史を誇る老舗酒蔵です。仕込み水には良質な大雪山・日高山脈雪解け伏流水（超軟水）を使用し、南部杜氏・社員醸造の伝統の技を受け継ぎながら、米の旨味を引き出す真摯な酒造りを追求しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('限定', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=6565;
