UPDATE breweries SET description='北海道根室市に蔵を構える株式会社 碓氷勝三郎商店は、明治20年（1887年）創業の歴史を誇る老舗酒蔵です。根室市が育んだ清酒＜北の勝＞ 清酒北の勝は、今から百有余年前の明治２０年９月に根室市で誕生した由緒ある銘柄。自然に恵まれた環境にくわえ、酒造りの基本に徹した伝統の技術が、 この芳醇でデリケートな味わいを生みだしてきたのです。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=6566;
