UPDATE breweries SET description='群馬県みどり市に蔵を構える近藤酒造株式会社は、明治8年（1875年）創業の歴史を誇る老舗酒蔵です。当社は、明治8年（1875年）創業以来、日本酒を造り、人々へお届けすることで、地域貢献につながる事業へと取り組んでまいりました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('自醸清酒鑑', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('雄町・祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=6544;
UPDATE breweries SET description='高知県に蔵を構える菊水酒造は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。その名は古の中国の伝説に由来すると伝えられています。また、昭和元年に日本で最初となる冷蔵貯蔵設備を酒蔵へと導入し、温暖な土佐の気候の中で良質な清酒づくりを実現するなど、名水と、名酒づくりに挑む杜氏たちの情熱が私たち菊水酒造の誇りなのです。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('雑記 高知', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=6743;
