UPDATE breweries SET description='北海道旭川市に蔵を構える髙砂酒造株式会社は、明治32年（1899年）創業の歴史を誇る老舗酒蔵です。1991年に日本清酒㈱に入社し、札幌酒造工場で技師として仕事を始め、「現代の名工」として労働大臣表彰を受けた故・津村 弥（わたる）翁の下で約10年間、酒造りのすべてを学ぶ。造りや水の違いを感じつつ、前任の西 和夫杜氏やベテラン蔵人に教わりながら、蔵の特徴を捉え髙砂の醸造を学んだ。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('森本良久', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('吟風・彗星・きたしずく', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=6560;
UPDATE breweries SET description='群馬県高崎市に蔵を構える美峰酒類株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。研究開発から製造まで、全てのプロセスにおいて品質にこだわり、お客様に安心してお召し上がりいただける酒を提供しております。当社の製品は、独自の原料、水を使用し、伝統の味を守りながらも、新しい味わいや香りを生み出しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('社長 瀬尾', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=6534;
