UPDATE breweries SET description='北海道上川郡東川町に蔵を構える三千櫻酒造株式会社は、明治10年（1877年）創業の歴史を誇る老舗酒蔵です。次の百年へ酒造りを繋ぐ 143年目の決断次の百年へ酒造りを繋ぐ 明治10年創業。その思いを込めて、中津川で培ってきた酒造りの技と魂のすべてを注ぎ、「三千櫻らしい酒」を造り続けます。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('山田耕司 連絡先', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('彗星・きたしずく・祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=6563;
UPDATE breweries SET description='高知県に蔵を構える松尾酒造は、明治6年（1873年）創業の歴史を誇る老舗酒蔵です。創業から150年を経た今も、「一番喜んでもらえる土佐のおさけは何か」を考えながら酒造りをしています。醸造に用いるお米は、全て高知県産のものを使用しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・吟の夢', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=6748;
UPDATE breweries SET description='高知県に蔵を構える西岡酒造店は、天明元年（1781年）創業の歴史を誇る老舗酒蔵です。西岡酒造は、この地で江戸時代中期の天明元年（1781年）に、初代井筒屋仁助が創業し、現在九代目に至っている２３０余年の歴史を持つ蔵元です。西岡酒造は、この地で江戸時代中期の天明元年（1781年）に、初代井筒屋仁助が創業し、現在９代目に至っている230余年の歴史を持つ蔵元です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('西岡大介 住所', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=6755;
UPDATE breweries SET description='高知県に蔵を構える川澤酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。自然豊かな高知の風土とともに 標高700ｍ、寒風山の森が幾年もの歳月をかけて育んだ清らかな谷水を、独自の方法で処理し、仕込み水として用いています。マイクロブリュワリーで通年醸す、フレッシュな味わい 少人数で対応できる設備を特注し、小さな酒蔵ならではのミニマムな醸造スタイルを確立。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('川澤 亨', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=6751;
