UPDATE breweries SET description='北海道旭川市に蔵を構える男山株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。四季を生かした伝統の醸造技術を現代へと紡ぎ、変わりゆく時代とともに新たな挑戦を続け、現在では約40種類の商品が生み出されています。日本酒の歴史と文化を伝える資料舘 『男山』350 年の歴史と共に、日本の伝統産業のひとつである酒造り文化を伝える資料館。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('限定', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('きたしずく', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=6562;
