UPDATE breweries SET description='滋賀県高島市に蔵を構える株式会社福井弥平商店は、寛延元年（1748年）創業の歴史を誇る老舗酒蔵です。「芳弥Ｘ」は伝統の生酛仕込を礎に、萩乃露の最新技術を駆使し、旨さの更新、未踏の旨さ実現を目指す意欲作。「渡船（わたりぶね）」はこのお酒 … 続きを読む 「雨垂れ石を穿つ 渡船」の出荷を開始しています（もみ殻バイオ炭を活用した循環型栽培「渡船」を使用しています）2026.05.15萩乃露の意欲作「生酛仕込 特別純米芳弥Ｘ」ご予約承り中。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('名工賞 平成', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('渡船', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛', ''), brewing_features) WHERE id=6011;
UPDATE breweries SET description='高知県に蔵を構える高木酒造は、1615年 (元和元年)年に創業しました。伝統の味と新たな土佐体感地酒をこれからも。酒蔵として町の伝統や歴史を次の世代へつないでいきたい。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('高木直之 住所', ''), president_name), toji_name=COALESCE(NULLIF('一年目', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('吟の夢', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=6746;
UPDATE breweries SET description='北海道増毛郡増毛町に蔵を構える国稀酒造株式会社は、明治15年（1882年）創業の歴史を誇る老舗酒蔵です。渚（なぎさ）の魅力とこだわり 「渚」は、日本酒になじみのない方や女性にも飲みやすい、爽やかな微炭酸感が楽しめるスパークリング日本酒です。自然の力を受けて育ったお米を精米歩合40％まで贅沢に磨き上げることで、原料由来の純粋な美味しさだけを抽出しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('限定', ''), president_name), toji_name=COALESCE(NULLIF('自醸清酒鑑', ''), toji_name), opening_hours=COALESCE(NULLIF('9:00 ～ 17:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('五百万石・吟風', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛・原酒・長期熟成・古酒', ''), brewing_features) WHERE id=6557;
