UPDATE breweries SET description='高知県に蔵を構える司牡丹酒造は、慶長8年（1603年）創業の歴史を誇る老舗酒蔵です。歴史と文化　司牡丹の由来・社宝「芳醇無比乃巻」 司牡丹の由来・社宝「芳醇無比乃巻」 南国土佐、高知市を離れて西へ２６ ｋｍ、山紫水明の佐川町は銘酒「司 牡丹」醸造の地として名があります。歴史ある建造物は国登録有形文化財としても親しまれており、伝統と革新を融合させた味わいを全国の日本酒ファンへ届けています。', description_generated=1, president_name=COALESCE(NULLIF('代表取締役', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=6754;
