UPDATE breweries SET description='群馬県沼田市に蔵を構える株式会社永井本家は、明治34年（1901年）創業の歴史を誇る老舗酒蔵です。天然に磨かれた水、澄み切った空気といった自然環境に恵まれ、醸造環境にも適した地。それらを生かし手造りを基本に酒を醸しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('袋吊り', ''), brewing_features) WHERE id=6543;
UPDATE breweries SET description='宮崎県えびの市に蔵を構える明石酒造株式会社は、明治24年（1891年）創業の歴史を誇る老舗酒蔵です。BREWER蔵人の情熱 呑む人の心を明るく円満にすることを大切に、日々の生活の愉しみや喜びとなるうまい焼酎づくりのため、今日も変わらず真摯に取り組む職人の姿。HISTORY明月の誕生 南九州有数の米どころえびの市にある明治二十四年創業の明石酒造。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('明石秀人 所在地', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=6876;
UPDATE breweries SET description='宮崎県日南市に蔵を構える古澤醸造合名会社は、明治25年（1892年）創業の歴史を誇る老舗酒蔵です。古澤醸造合名会社（公式） 南国の太陽日南の海にいだかれて 創業明治二十五年西暦1892年 今日では宮崎唯一の土蔵となりました。創業以来の県内唯一の土蔵造りの醸造蔵と、麹室で麹蓋を使い、永い歴史に支えられ、気候、風土に生きた手造りを頑固に守り続けている。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=6888;
UPDATE breweries SET description='熊本県葦北郡津奈木町に蔵を構える亀萬酒造合資会社は、大正5年（1916年）創業の歴史を誇る老舗酒蔵です。親から子へ孫へと愛される 手造りにこだわった郷土の酒 3代目が見守る中、4代目が始めたのは常識を覆す「一切混ぜない」酒造り。醸造最南端の蔵ならではの南国らしいコクのある、自分がうまいと信じた、最高のものを造るため社員一丸となって醸し続けています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=6768;
