UPDATE breweries SET description='富山県に蔵を構える銀盤酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。銀盤酒造では、酒命を宿す仕込み水に、日本名水百選にも選ばれた黒部川扇状地湧水群の軟水を使用しております。良質の水と良質の米、このふたつに、杜氏、蔵人、酒蔵の技や情熱が加わって「心に残る旨い酒」が生まれます。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('山岸逸人 創業年', ''), president_name), toji_name=COALESCE(NULLIF('荻野 久男', ''), toji_name), opening_hours=COALESCE(NULLIF('9:00 - 17:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=6072;
