UPDATE breweries SET description='高知県に位置する藤娘酒造は、昭和18年（1943年）に創業しました。『熟練した杜氏の技と最高の素材』 四万十川の伏流水を100％無濾過で使用し、最高の米と伝統の技をもって醸すことでこの土地ならではの柔らかな飲み飽きしない味と香りをお届けいたします。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('9:00～17:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=6758;
UPDATE breweries SET description='宮崎県日南市に蔵を構える櫻の郷酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。日本最大の甕貯蔵庫を持つ宮崎の焼酎蔵 長期甕貯蔵により焼酎の秘めたる味わいを引き出した「無月」シリーズや、知る人ぞ知るこだわりの銘酒「赤魔王」シリーズをはじめとする様々な本格焼酎・リキュール・スピリッツのブランドを展開しています。甕貯蔵により奥深い味わいをまとった本格焼酎とスッキリ味のリキュール、こだわりの国産クラフトジン・スピリッツ。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('寺田 和弘', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('古酒', ''), brewing_features) WHERE id=6892;
UPDATE breweries SET description='群馬県利根郡川場村に蔵を構える土田酒造株式会社は、明治40年（1907年）創業の歴史を誇る老舗酒蔵です。私たちは醸造技術や日本酒文化を次世代へと継ぐべく、日々挑戦を続けています。生酛（きもと）造りとは、蔵にすみついている乳酸菌が降りるのをひたすら待つという造り方です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛・きもと', ''), brewing_features) WHERE id=6540;
UPDATE breweries SET description='宮崎県日南市に蔵を構える井上酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。原料から製法、貯蔵まで焼酎造りの全てにこだわり、最高級の味と品質を追求した本格焼酎。伝統を受け継ぐだけでなく、 当蔵は1894年（明治27年）、榎原神社の門前町に清酒製造の蔵として創業しました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('寺田 和弘', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=6891;
