UPDATE breweries SET description='大分県豊後大野市に位置する藤居醸造は、昭和4年（1929年）に創業しました。藤居醸造はこの地で昔ながらの焼酎造りを行っている小さな蔵です。「本当においしい麦焼酎を味わっていただきたい」、そんな思いを胸に、 昭和4年の創業以来、完全手造りを貫いています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('木桶', ''), brewing_features) WHERE id=7110;
