UPDATE breweries SET description='熊本県上益城郡山都町に蔵を構える通潤酒造株式会社は、明和7年（1770年）創業の歴史を誇る老舗酒蔵です。「JAかみましき酒米部会」のご協力により使う酒米のほぼ100%を、山都町で契約栽培していただいております。「JAかみましき酒米部会」のご協力により使う酒米のほぼ100%を、山都町で契約栽培していただいております。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('山下林八', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=6761;
UPDATE breweries SET description='長崎県壱岐市に蔵を構える壱岐の蔵酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。大陸から蒸留技術が伝わったのは、室町時代から安土桃山時代にかけて（16世紀）。500年の歴史に磨かれた伝統的な製法が認められ、1995年にはWTO（世界貿易機関）のトリプス協定によって「地理的表示（※GI壱岐）」の産地指定を受けました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('代表取締役 石橋', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒・長期熟成・低温発酵', ''), brewing_features) WHERE id=6990;
UPDATE breweries SET description='群馬県利根郡川場村に蔵を構える永井酒造株式会社は、明治19年（1886年）創業の歴史を誇る老舗酒蔵です。初代永井庄治がこの地の水に出会い酒造りを始めました。仕込み水の確保のため深い森林を所有し、酒蔵周辺は大自然に囲まれ、蔵の前には豊かな水田が見渡す限り広がっています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('永井 則吉', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('古酒', ''), brewing_features) WHERE id=6542;
UPDATE breweries SET description='長崎県平戸市に蔵を構える有限会社森酒造場は、明治28年（1895年）創業の歴史を誇る老舗酒蔵です。かつては宮中の役職を指していましたが、 その特異な職務、特殊技能を身につけた者という意味で 「玄人」の元となった言葉でもあります。平戸路の蔵元、森酒造場 平戸は日本で最初に、海外貿易の拠点として栄えた港町で、 400年前にポルトガル・オランダ・イギリスなどの商館が 私どもの蔵は、その様な町に明治28年「小松屋」の屋号で 森幸吉の手により創業されました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('社長 森', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('9:00～17:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛', ''), brewing_features) WHERE id=6985;
UPDATE breweries SET description='大分県臼杵市に蔵を構える小手川酒造は、安政2年（1855年）創業の歴史を誇る老舗酒蔵です。蔵元紹介ムービー(850k) 創業の安政２年（1855年）より酒造を営み、以来一貫して手造りにこだわった酒を造り続けています。小手川酒造は作家野上弥生子の生家で、創業は安政2年(1855年)の蔵元です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('小手川 励人', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=7121;
UPDATE breweries SET description='宮崎県西臼杵郡高千穂町に位置する神楽酒造株式会社は、昭和29年（1954年）に創業しました。長期貯蔵酒ひむかのくろうま KUROUMA taru ABOUT KAGURASHUZO 「神話のふる里」 宮崎県高千穂町にて創業以来宮崎の綺麗な水と国産の原料にこだわりお酒造りを続けてきました。神楽酒造は昭和29年、神話のふるさと宮崎県高千穂町にて創業し、以来常に品質の向上を図り、「優れた焼酎をお客様にお届けする事」を社是として、愛される商品づくりを目指して参りました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('佐藤猶薫 永眠', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=6899;
UPDATE breweries SET description='長崎県平戸市に蔵を構える福田酒造株式会社は、元禄元年（1688年）創業の歴史を誇る老舗酒蔵です。創業者福田長治兵衛門の言葉、『酒づくりは、心でつくり、風が育てる。西洋とアジアの両方の視点を持つクリエーターにお願いしたのは、300年ほど続く福田の歴史・伝統を活かしつつ異国への眼差しをとりいれ、ここ平戸から世界にむけて福田酒造を発信していきたいという思う未来があるからです。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('団体', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('9:00～15:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('長期熟成', ''), brewing_features) WHERE id=6986;
UPDATE breweries SET description='大分県竹田市に蔵を構える佐藤酒造は、大正6年（1917年）創業の歴史を誇る老舗酒蔵です。仕込み水には良質な九重連山・久住高原湧水群（軟水）を使用し、丁寧な手造りの精神を受け継ぎながら、米の旨味を引き出す真摯な酒造りを追求しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=7128;
