UPDATE breweries SET description='大分県佐伯市に蔵を構える大地酒造は、明治18年（1885年）創業の歴史を誇る老舗酒蔵です。オンラインショッピング オンラインショッピング オンラインショッピング 佐伯の清酒と焼酎の伝統文化を後世に残そうと事業を承継しました。お酒づくりで最も重要と言っても過言ではない仕込み水。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・美山錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過', ''), brewing_features) WHERE id=7113;
