UPDATE breweries SET description='大分県玖珠郡九重町に蔵を構える八鹿酒造は、元治元年（1864年）創業の歴史を誇る老舗酒蔵です。地「酒蔵のある町「九重」」 神「酒造りと伝統の技」 酒づくりは、人づくり。酒造りには、豊かな自然環境をはじめ、美しい水、空気、そして人の技術と精神が必要です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('三代目', ''), president_name), toji_name=COALESCE(NULLIF('渾身', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・五百万石', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('四季醸造', ''), brewing_features) WHERE id=7116;
