UPDATE breweries SET description='長崎県諫早市に蔵を構える株式会社杵の川は、天保10年（1839年）創業の歴史を誇る老舗酒蔵です。長崎県内でも有数の穀倉地帯である諫早市の米農家さんの技術と情熱に支えられた良いお米です。酒造り５０年以上の熟練の蔵人、清酒専門評価者の資格を持つ蔵人、様々な技能、経験を持つ蔵人たち。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('直営', ''), president_name), toji_name=COALESCE(NULLIF('瀬頭', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=6980;
UPDATE breweries SET description='大分県日田市に蔵を構える老松酒造は、寛政元年（1789年）創業の歴史を誇る老舗酒蔵です。受け継がれてきた伝統のなかで、一人ひとりの想いがつながって 絆となり、やがて大きな力となる。寛政元年（1789年）、老松酒造の初代は、 日田地方にある泉より湧き出る水の美味しさに惹かれ、 この天然水をつかって酒造りをすることを決意し創業致しました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('長期熟成・古酒', ''), brewing_features) WHERE id=7109;
UPDATE breweries SET description='大分県玖珠郡玖珠町に蔵を構える亀の井酒造は、享保元年（1716年）創業の歴史を誇る老舗酒蔵です。toggle navigation 江戸時代の享保年間に創業して三百余年 九重連山の豊富な地下水と清冽な気候の中 永きに渡り真心込めて醸す亀の井酒造の酒 是非一度、お試し下さい。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('長野 雄人', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・五百万石', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('山廃', ''), brewing_features) WHERE id=7125;
UPDATE breweries SET description='大分県豊後大野市に蔵を構える浜嶋酒造は、明治22年（1889年）創業の歴史を誇る老舗酒蔵です。』アルコール飲料にもいろいろありますが、米を発酵させて出来た醸造酒である日本酒の毛細血管にまで染み渡るような心地良い酔いが大好きです。しかし、ちょうど私が15歳の冬(昭和54年)、母が病に倒れ、蔵は急遽製造をストップし17年間委託醸造で金鷹を醸してきました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('浜嶋 弘文', ''), president_name), toji_name=COALESCE(NULLIF('醸造家 浜嶋', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・雄町・五百万石', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('山廃', ''), brewing_features) WHERE id=7123;
UPDATE breweries SET description='宮崎県日南市に蔵を構える小玉醸造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。仕込み水には良質な霧島山系・祖母傾山水系伏流水（中軟水）を使用し、丁寧な手造りの精神を受け継ぎながら、米の旨味を引き出す真摯な酒造りを追求しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('潤平', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=6884;
UPDATE breweries SET description='大分県国東市に蔵を構える南酒造は、明治元年（1868年）創業の歴史を誇る老舗酒蔵です。上に書かれた意匠は創業からの屋号「喜納屋」を表す。南酒造の商品には2年ほど寝かせた20度と25度の「とっぱい」のほか、特に出来のいいものを粗濾過で5年寝かせ、創業以来の屋号を名前に冠した「喜納屋」がありますが、これも出来映えに納得しなければ発売しない年もある、というこだわりようです。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('古酒', ''), brewing_features) WHERE id=7118;
UPDATE breweries SET description='大分県由布市に蔵を構える小野酒造株式会社は、明治39年（1906年）創業の歴史を誇る老舗酒蔵です。そんな土地で家族数人だけで営む小さな田舎蔵ですが、少量ながらもこだわりの減圧蒸留麦焼酎、常圧蒸留麦焼酎、県産原料リキュールすべて自社にて製造、心温まる酒造りをモットーに日々、切磋琢磨しております。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=7134;
UPDATE breweries SET description='長崎県壱岐市に蔵を構える重家酒造株式会社は、大正13年（1924年）創業の歴史を誇る老舗酒蔵です。20ヶ所の水源を掘り、辿り着いた仕込み水と、肥沃な土地で育まれた壱岐産の酒米を用い、壱岐の風土が感じられる日本酒を造っております。伝統と革新により、更なる高みを目指して―。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('就任', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('8:00～17:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('雄町・祝・愛山・赤磐雄町', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=6989;
UPDATE breweries SET description='宮崎県延岡市に蔵を構える佐藤焼酎製造場株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。私どもの蔵は明治38年の創業から100年という長い年月をかけて、焼酎造りに励んできました。そして、その伝統と現在の蔵人の高い意識と技術が絡み合い、活気に満ちた焼酎造りを続けています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('山岸 逸人', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=6867;
UPDATE breweries SET description='大分県宇佐市に位置する三和酒類株式会社は、昭和33年（1958年）に創業しました。FACILITY INTRODUCTION 原酒をはぐくむ静かな情熱。深い自然がもたらす澄んだ空気と清らかな水の恵みのある日田の豊かな環境の中で情熱を込めて原酒を製造しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('大城勤', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=7132;
