UPDATE breweries SET description='大分県豊後大野市に蔵を構える吉良酒造は、明治4年（1871年）創業の歴史を誇る老舗酒蔵です。日本百名山から湧き出る水と広がる肥沃な大地から生まれる地元の米を使い、吉良酒造は明治4年創業以来、代々受け継がれてきた技と味を守り続けてきました。麹を室で仕込む手造りにこだわる5代目の確かな腕と、夫婦がわが子のように「時に優しく、時に厳しく」仕込んだ酒には、飲み手を笑顔にしたいという思いが込められています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=7140;
UPDATE breweries SET description='大分県速見郡日出町に蔵を構える二階堂酒造は、慶応2年（1866年）創業の歴史を誇る老舗酒蔵です。「麻地酒」の伝統を受け継ぎむぎ100%の焼酎が生まれたのは現六代目当主の時代である。若き当主は天然醸造ゆえに腐敗しやすい「麻地酒」を改良するために醸造酒から蒸留酒へ切り替え焼酎の製造を開始する。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('二階堂裕一', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=7139;
UPDATE breweries SET description='長崎県佐世保市に蔵を構える潜龍酒造株式会社は、元禄元年（1688年）創業の歴史を誇る老舗酒蔵です。潜龍酒造　長崎県佐世保市にある日本酒「本陣」の醸造元 – 300年醸した季節の恵みを味わう1本。地の水、地の米、地の人にこだわり、 昔ながらの製法で酒造りを行っています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('代表取締役 山下', ''), president_name), toji_name=COALESCE(NULLIF('中山 直', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=6987;
UPDATE breweries SET description='大分県竹田市に位置する萱島酒類は、平成21年（2009年）に創業しました。しかし、竹田の町中で「福寿屋」の看板を掲げ、創業以来一日一日と焼酎造りに向かいあっている日々の中で、少しずつですが、地元の方々の目に止まり、手に取って頂けるようになりつつあります。清酒造りの蔵元である萱島酒造の米麹への思い入れと長年培ってきた経験が活かされた焼酎は、米由来の甘みと柔らかさが特徴の、どこにもない萱島酒類だけの焼酎に仕上がっています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('萱島 進', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=7141;
