UPDATE breweries SET description='大分県国東市に蔵を構える矢野酒造場は、明治16年（1883年）創業の歴史を誇る老舗酒蔵です。原料米は地元大分県産ひのひかり 原料米は地元産にこだわり、大分県産米「ひのひかり」を使用しています。手仕事の酒づくりの味わいを大切にするため、矢野酒造場の醸造銘柄は糖類を一切添加していません。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('矢野 秀', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=7126;
UPDATE breweries SET description='佐賀県伊万里市に蔵を構える松浦一酒造株式会社は、享保元年（1716年）創業の歴史を誇る老舗酒蔵です。本年も松浦一酒造は「手づくりのまごころ生きるうまい酒」創業から続く信念を忘れず、ふるさとの文化、先人の教えに感謝し、心豊かに酔える酒を造り続けてまいります。今回４０８銘柄もの酒が出品され、利き酒部門では全体の１０％が各賞を受賞しました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・雄町・祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=7208;
UPDATE breweries SET description='佐賀県みやき町に蔵を構える天吹酒造合資会社は、元禄元年（1688年）創業の歴史を誇る老舗酒蔵です。酒蔵見学シミュレーションへ 天吹のこだわりCOMMITMENT 永い歴史の中で蓄積された技を引き継いだ蔵人達が、自然界の力に魅せられて、真摯に美酒造りを追求しています。300年の長い歴史を持つ天吹は実りの多い佐賀平野で収穫された酒米と脊振山系のまろやかな伏流水、新しい酵母である花酵母、そして歴史の中で蓄積された技を引き継いだ蔵人たちが、真摯に美酒造りを追求しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('雄町', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=7196;
