UPDATE breweries SET description='大分県豊後大野市に蔵を構える牟礼鶴酒造は、明治37年（1904年）創業の歴史を誇る老舗酒蔵です。明治37年初代森環（もりたまき）が、 清酒「牟禮鶴」の製造を開始。もともと蔵元の後継者として 焼酎製造の素人だった私が 造るにあたり心掛けたのは、 一つは先人の技術を忠実に守ること。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('杜氏', ''), president_name), toji_name=COALESCE(NULLIF('森健太郎', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=7122;
UPDATE breweries SET description='大分県国東市に蔵を構える萱島酒造は、明治6年（1873年）創業の歴史を誇る老舗酒蔵です。西の関は永い悠久の時間の中で地元に密着した伝統手造り手法を発展的に継承し甘い辛いを超越した日本酒本来の旨さを絶えず追求して参ります。代表銘柄「西の関」は、明治20年代に二代目米三郎が、西は西日本、関は横綱の意味で「西日本の代表酒」になりたいとの大きな望みと努力を心に誓って命名したものです。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('萱島 進', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・八反錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=7124;
