UPDATE breweries SET description='大分県佐伯市に蔵を構えるぶんご銘醸は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。頼りになるのは、杜氏たちの経験と昔より継承した技。原材料への限りないこだわりをもつこの焼酎、QIAJAPAN（有機穀物認証機関）により認証された麦と大麦精麦法でつくられた、類い希な資質をもつ完全有機麦焼酎である。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('狩生 豊辞任', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=7127;
UPDATE breweries SET description='島根県邑智郡邑南町に蔵を構える池月酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。「この土地で酒を醸す意義」 ー全量地元産の酒米を使用ー 池月酒造では仕込み水と同じ水脈で、蔵から半径15km以内の 水田で育てられた酒米を使い酒造りをします。自然豊かなこの地域は水も豊かで、池月酒造では天然の湧き水を山中より 蔵内に引き込み、仕込み水として使っています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('代表取締役 末田', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=7282;
UPDATE breweries SET description='大分県日田市に蔵を構える井上酒造は、文化元年（1804年）創業の歴史を誇る老舗酒蔵です。本年でこの地で創業して以来222年目となり先人達の尽力により今日の日があります。歴史と伝統は日田の大鶴の皆様方に支えられてきたからこそ、少しずつその幹を太くしてきました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('後藤 康男', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('木桶・四季醸造', ''), brewing_features) WHERE id=7142;
UPDATE breweries SET description='佐賀県鹿島市に蔵を構える有限会社馬場酒造場は、寛政7年（1795年）創業の歴史を誇る老舗酒蔵です。初代馬場夘左衛門に始まり、現在は８代目馬場第一郎が代表として、 また杜氏として日本酒の伝統と文化を受け継いでいます。初代馬場夘左衛門に始まり、現在は、 ８代目馬場第一郎が代表として、また杜氏として日本酒の伝統と文化を受け継いでいます。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('物語', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('中取り', ''), brewing_features) WHERE id=7215;
UPDATE breweries SET description='佐賀県鹿島市に蔵を構える富久千代酒造有限会社は、明治32年（1899年）創業の歴史を誇る老舗酒蔵です。『鍋島』ブランドは75年の時を経て、唯一無二の酒を求め、 地元に愛され誇られる地酒造りを志した3代目の飯盛直喜が、 こだわりの米と水を用いて1998年にゼロからスタートしました。手造りによる麹造りや丁寧な仕込み、それらは酒造りに関わる全員の強い信念によって支えられています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('飯盛直喜', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=7218;
UPDATE breweries SET description='佐賀県嬉野市に蔵を構える井手酒造有限会社は、明治元年（1868年）創業の歴史を誇る老舗酒蔵です。創業当時の面影をそこそこ残す酒蔵は、ひんやりと落ち着いた雰囲気である。加えて、二代続けての杜氏らが伝統の味を守り、地域の風土とマッチしたものに仕上げています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('東敦子就任', ''), president_name), toji_name=COALESCE(NULLIF('山口杜氏', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('低温発酵', ''), brewing_features) WHERE id=7211;
UPDATE breweries SET description='島根県雲南市に蔵を構える木次酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。お酒造りに使います仕込み水は蔵のすぐ近くの山に湧き出る岩清水を使い、お米もすべて当蔵があります雲南市内産を使っております。お酒が美味しくなる技術や製法、また必要と判断したものは積極的に取り入れています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('杜氏', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・五百万石', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過生原酒・無濾過・原酒', ''), brewing_features) WHERE id=7288;
UPDATE breweries SET description='長崎県対馬市に蔵を構える白嶽酒造株式会社は、大正8年（1919年）創業の歴史を誇る老舗酒蔵です。登場人物：兄・海幸彦（うみさちひこ／海佐知毘古／ホデリノミコト）と弟・山幸彦（やまさちひこ／山佐知毘古／ホオリノミコト）※山幸彦の子孫は初代天皇・神武天皇へと続き、日本の歴史の重要な一部となりました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('伊藤 真太郎', ''), toji_name), opening_hours=COALESCE(NULLIF('9:00〜18:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒・古酒', ''), brewing_features) WHERE id=6988;
UPDATE breweries SET description='島根県安来市に蔵を構える青砥酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。仕込み水には良質な中国山地・宍道湖水系伏流水（軟水）を使用し、出雲杜氏の伝統の技を受け継ぎながら、米の旨味を引き出す真摯な酒造りを追求しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=7292;
UPDATE breweries SET description='大分県由布市に蔵を構える麻生本店は、明治元年（1868年）創業の歴史を誇る老舗酒蔵です。自然と人の技が織りなす、昔ながらの手づくりの味わいをお届けします。大分県由布市庄内町にて、明治元年（1868年）創業。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('麻生 裕輔', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=7138;
UPDATE breweries SET description='大分県日田市に位置するクンチョウ酒造は、昭和7年（1932年）に創業しました。日本酒の伝統を守り革新を続ける大分県日田市の酒蔵クンチョウ酒造 お知らせ・イベント情報 通販カタログ「蔵元直送便」登録 SHOP　/　GALLERY カフェ＆ギャラリー旅の舎sakabayashi 高速日田インターから車で約5分。ABOUT KUNCHO まち、ひと、自然、受け継がれてきた技が醸し出すクンチョウの酒造りをご紹介。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('直送便', ''), president_name), toji_name=COALESCE(NULLIF('近藤 義一', ''), toji_name), opening_hours=COALESCE(NULLIF('9:00～16:30', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=7136;
UPDATE breweries SET description='佐賀県嬉野市に蔵を構える瀬頭酒造株式会社は、寛政元年（1789年）創業の歴史を誇る老舗酒蔵です。寛政元年、初代瀬頭多次兵衛が「丸平正宗」の銘柄で創業。創業以来の願いは「正直な酒をつくる」こと、時が経っても変わることなく受け継がれており、時間をかけ、手間をかけ、ゆっくりと、とても贅沢な伝統製法を守り、本物の日本酒を醸し続けております。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('代表取締役 瀬頭', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=7212;
UPDATE breweries SET description='佐賀県嬉野市に蔵を構える五町田酒造株式会社は、大正11年（1922年）創業の歴史を誇る老舗酒蔵です。銘柄：「東一」には“東洋一の酒を目指す”という思いを込めています。創業当初は、銘柄：「日本一」のみにて出荷しておりましたが、日本より広域の東洋一を目指す意気込みで名付けました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('瀬頭 一平', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=7213;
UPDATE breweries SET description='大分県宇佐市に蔵を構える縣屋酒造は、正徳2年（1712年）創業の歴史を誇る老舗酒蔵です。この重松義種の子供の「徳左工衛門義徳」はフロンティアスピリッツに満ちあふれた熱血漢で、三人の息子と一緒に醸造業を始めた。重松徳左工衛門義徳を初代として引き継がれる中、四代目柳兵衛が身代の建て直しを図り、福岡の曽根の造り酒屋に修行に出て、高度な技術を取得することによって五代目、六代目と隆盛を極めることになった。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=7111;
UPDATE breweries SET description='佐賀県鹿島市に位置する幸姫酒造株式会社は、昭和9年（1934年）に創業しました。祐徳稲荷神社の御神酒 指定釀造元 佐賀県鹿島市の日本酒ブランドなら幸姫酒造 創業1934年佐賀県鹿島市にある祐徳稲荷神社の御神酒 指定釀造元 SACHIHIME幸姫について 90年続く小さな酒蔵。PRODUCTS商品情報 人々の幸福を祈り、こだわり抜かれた製法で造られた数々のお酒。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('9:00～12:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過生原酒・無濾過・原酒・長期熟成', ''), brewing_features) WHERE id=7216;
UPDATE breweries SET description='大分県宇佐市に蔵を構える久保酒蔵は、寛政元年（1789年）創業の歴史を誇る老舗酒蔵です。久保　黒麹（常圧蒸留） 愛媛県産はだか麦だけで仕込んだコクと甘みと呑みごたえの楽しめる手造り麦焼酎です。久保　樫樽長期貯蔵（常圧蒸留） 麦焼酎の原酒を樫樽でじっくりと熟成させたスモーキーでまろやかな口当たりを楽しめる手造り麦焼酎です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('8:00～17:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=7137;
UPDATE breweries SET description='佐賀県鹿島市に蔵を構える矢野酒造株式会社は、寛政8年（1796年）創業の歴史を誇る老舗酒蔵です。2026年1月13日お知らせ清酒の価格改定のお知らせ 銘柄の紹介sake竹の園（たけのその） 五代目和良の時代、大正天皇の即位という慶事に、皇族を表す言葉である「竹の園生」（たけのそのう）の名を戴き「清酒 竹の園」は誕生いたしました。今一度原点を振り返り、酒造りに関わるあらゆる微生物の力強い躍動を味わいに体現すべく、小手先の技術に頼らない伝統的な製法で醸造していくという思いを込め、「竹の園 還ル」は誕生いたしました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('矢野元英', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝・愛山', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('山廃', ''), brewing_features) WHERE id=7214;
UPDATE breweries SET description='島根県邑智郡邑南町に蔵を構える玉櫻酒造有限会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。当初は一部のお酒に契約栽培米を使っていましたが、現在（2020年）は契約農家さんも増え、全てのお酒に地元産契約栽培米を使用しています。原料米由来の味の違いを楽しむため、できるだけ単一品種のお米で仕込んでいます。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('五百万石', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛・無濾過', ''), brewing_features) WHERE id=7300;
