UPDATE breweries SET description='島根県仁多郡奥出雲町に位置する奥出雲酒造株式会社は、平成16年（2004年）に創業しました。世界遺産は、国連食糧農業機関（FAO：本部・ローマ）が次世代に受け継ぐべき伝統的な農業や農村文化の保護を目的に、 世界的に貴重な農林水産業システムを認定するものです。世界遺産は、国連食糧農業機関（FAO：本部・ローマ）が次世代に受け継ぐべき伝統的な農業や農村文化の保護を目的に、 世界的に貴重な農林水産業システムを認定するものです。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('代表取締役 糸原', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('9:00～18:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('雄町・五百万石', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('全量純米', ''), brewing_features) WHERE id=7291;
UPDATE breweries SET description='島根県隠岐郡隠岐の島町に位置する隠岐酒造株式会社は、昭和47年（1972年）に創業しました。隠岐の島には、環境省選定「名水百選」に選ばれた湧水が二カ所あり、清らかな仕込み水に恵まれています。杜氏の長年 培ってきた経験と技術、そしてコンピューターを利用した細心なデータ管理がうまく融合して、初めて「納得のいくお酒造り」が出来ると確信しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('長谷川 哲', ''), president_name), toji_name=COALESCE(NULLIF('自醸清酒品', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・雄町・五百万石', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛・原酒', ''), brewing_features) WHERE id=7281;
