UPDATE breweries SET description='島根県雲南市に位置する株式会社田部竹下酒造は、令和4年（2022年）に創業しました。庄屋を務めていた竹下家が田部家から酒造の権利を譲り受け、屋号を「宮中屋」と称し醸造を始めたのは慶応二年（1866年）。同年11月7日に仕込みを始め、2023年1月に新たな酒「奥出雲前綿屋試験醸造」を発表。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=7304;
UPDATE breweries SET description='島根県出雲市に蔵を構える株式会社酒持田本店は、明治10年（1877年）創業の歴史を誇る老舗酒蔵です。現在の位置：トップ / 酒造り〜日本酒ができるまで〜 詳しい酒造りの工程から酒造りに関する用語集、酒持田本店のこだわりなどをご紹介します。杜氏をはじめとする蔵人たちの情熱と、熟練された技術により醸されて香り高く味わい深い日本酒へとかわっていくのです。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('山廃・原酒・古酒', ''), brewing_features) WHERE id=7296;
UPDATE breweries SET description='島根県出雲市に蔵を構える板倉酒造有限会社は、明治4年（1871年）創業の歴史を誇る老舗酒蔵です。仕込み水には良質な中国山地・宍道湖水系伏流水（軟水）を使用し、出雲杜氏の伝統の技を受け継ぎながら、米の旨味を引き出す真摯な酒造りを追求しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・雄町', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛・山廃・原酒', ''), brewing_features) WHERE id=7284;
UPDATE breweries SET description='島根県鹿足郡津和野町に蔵を構える株式会社財間酒場は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。財間酒場 公式ウェブサイト top of page ZAIMA SAKABA財間酒場 ZAIMA SAKABA200年の伝統とこだわりの味財間酒場とは。会社情報​伝統と挑戦の味財間酒場は、寛政3年（西暦1791年）創業。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=7307;
UPDATE breweries SET description='栃木県小山市に蔵を構える杉田酒造は、明治9年（1876年）創業の歴史を誇る老舗酒蔵です。静かな田園風景広がる「上泉（かみいずみ）」に明治初期に初代「杉田房吉（ふさきち）」が新潟より移り、始めたのが杉田酒造です。酒のコンセプトは「日本酒らしい日本酒」 明治6年（1873年）4月に初代「杉田房吉(ふさきち）」が新潟県中越より移り創業。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝・強力', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛', ''), brewing_features) WHERE id=7353;
UPDATE breweries SET description='栃木県栃木市に蔵を構える相良酒造は、天保2年（1831年）創業の歴史を誇る老舗酒蔵です。天保2年（1831年）、相良與平により創業。越後国刈羽郡（現在の新潟県柏崎市）に生まれた初代與平は、自身が理想とする酒造りに適した水を探し求めて現在の地に辿り着き、そこで相良彦四郎の名跡を継いで酒造業を始めたと伝えられています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('相良 沙奈恵', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('五百万石・祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('氷温貯蔵', ''), brewing_features) WHERE id=7343;
UPDATE breweries SET description='島根県大田市に蔵を構える一宮酒造有限会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。大学4年間で醸造学について学び、卒業後家業を継ぐべく大田市へ戻る。当社では良質の酒米はもちろん、特に水にこだわり、雄大な三瓶山の麓から湧き出る伏流水を仕込みに使用しております。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('三姉妹', ''), president_name), toji_name=COALESCE(NULLIF('酒蔵 拘泥', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=7305;
UPDATE breweries SET description='島根県浜田市に蔵を構える日本海酒造株式会社は、明治21年（1888年）創業の歴史を誇る老舗酒蔵です。酒造りに使用する酒米は五百万石を主に使っており、浜田市弥栄町の農家と契約栽培をし、最適な環境と澄んだ水で育った米を最大限に活かした日本酒を杜氏と蔵人が造り上げます。原材料名：米（国産）、米こうじ（国産米）、醸造アルコール 720ml［箱：有り］ 環日本海 大吟醸 荒波 山田錦を35％まで精米。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('小原広明 蔵元', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・五百万石・八反錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('山廃・無濾過生原酒・無濾過・原酒・袋吊り', ''), brewing_features) WHERE id=7294;
UPDATE breweries SET description='栃木県矢板市に蔵を構える森戸酒造は、明治7年（1874年）創業の歴史を誇る老舗酒蔵です。秋には稲が実り、春には蛙が鳴き夏には蛍が舞う田園風景の中、米作りから拘りながらも、歴史と伝統に縛られることなく挑戦を続ける酒蔵です。杜氏として昔から守るべき技術を守り、最新技術からも目をそらさずにしっかり向き合い、日々ひたむきに酒造りに取り組んでいます。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('森戸 康雄', ''), president_name), toji_name=COALESCE(NULLIF('引退', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=7350;
UPDATE breweries SET description='栃木県塩谷郡塩谷町に蔵を構える松井酒造店は、慶応元年（1865年）創業の歴史を誇る老舗酒蔵です。「松」と「寿」二つのおめでたい言葉が重なる銘柄「松の寿」をお選びいただけたら幸いです。酒と塩の浄め水を発売 2023/1/21(土）ミヤラジ出演 WAKAZE三軒茶屋醸造所 在庫状況【2018.2.25更新】 満喫とちぎ日和　とちぎテレビ出演 未成年者の飲酒は法律で禁じられています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('兼杜氏 松井', ''), president_name), toji_name=COALESCE(NULLIF('交代', ''), toji_name), opening_hours=COALESCE(NULLIF('9:00～17:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=7348;
