UPDATE breweries SET description='島根県出雲市に蔵を構える富士酒造合資会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。特別契約栽培の出雲産佐香錦を使用し、佐香錦の持つコクとキレを最大限に活かしました。出雲杜氏の伝統の吟醸造りを継承し、心地よい吟醸の風味が楽しめます。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('今岡 稔晶', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=7287;
UPDATE breweries SET description='島根県松江市に蔵を構える米田酒造株式会社は、明治29年（1896年）創業の歴史を誇る老舗酒蔵です。代表銘柄「豊の秋」の名付けの通り、すべての五穀の豊穣を祈り食文化の創造に貢献します。これからも皆様に至福のひとときを提供できるよう、伝統技術を継承しつつ、より質の高い酒造りに邁進して参ります。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('会長 田部長右衛', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=7290;
UPDATE breweries SET description='栃木県小山市に蔵を構える小林酒造は、明治5年（1872年）創業の歴史を誇る老舗酒蔵です。日光山系の豊富な地下水や、雄大で繊細な自然の恩恵を受け、創業明治5年以来、150年にわたり酒造りを続けています。鳳凰美田 醸造元小林酒造について紹介いたします。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=7359;
