UPDATE breweries SET description='栃木県小山市に蔵を構える西堀酒造は、明治5年（1872年）創業の歴史を誇る老舗酒蔵です。西堀酒造｜若盛 門外不出 醸造元／日光街道小山蒸溜所 栃木県小山市の酒蔵。→受賞歴へ 最高齢プロフェッショナルの教え（徳間文庫）に登場する故・継枝杜氏の技術を土台とする伝統的な製法から、常識に囚われない革新的な製法まで、美味しさとともに驚きと感動を届ける「自由闊達なる酒造り」を目指します。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('代表取締役', ''), president_name), toji_name=COALESCE(NULLIF('自醸清酒鑑', ''), toji_name), opening_hours=COALESCE(NULLIF('8:00～17:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒・瓶燗火入れ', ''), brewing_features) WHERE id=7356;
