UPDATE breweries SET description='広島県江田島市能美町に蔵を構える津田酒造株式会社は、明治26年（1893年）創業の歴史を誇る老舗酒蔵です。津田酒造では、当蔵元代表銘柄「清酒　島の香」をはじめ、純米酒、純米吟醸酒など飲みやすくみやすく飲み飽きない愛されるお酒をお届けすることを大切にしています。津田酒造オンラインショップ 通年で販売している銘柄をはじめ、おもたせや御礼品、ご贈答などに最適な銘酒セット商品、季節限定のお酒をインターネットでご購入いただけます。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('津田 真由美', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=7930;
UPDATE breweries SET description='広島県東広島市西条岡町に蔵を構える山陽鶴酒造株式会社は、大正元年（1912年）創業の歴史を誇る老舗酒蔵です。山田錦を心を込めて醸した大吟醸から、燗酒におすすめな本醸造、すっきりした甘味を味わうにごり酒まで。西条独特の軟水を使用し、変わらぬ伝統を背景に喉ごしのよい清酒本来の「甘酸辛苦渋」が一体になって融けあう日本酒をおとどけしています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=7924;
UPDATE breweries SET description='広島県呉市仁方本町に蔵を構える相原酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。仕込み水には良質な賀茂山系・太田川軟水伏流水（軟水）を使用し、広島杜氏の伝統の技を受け継ぎながら、米の旨味を引き出す真摯な酒造りを追求しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('代表取締役', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・愛山', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=7936;
