UPDATE breweries SET description='和歌山県有田郡有田川町に蔵を構える髙垣酒造株式会社は、天保11年（1840年）創業の歴史を誇る老舗酒蔵です。高垣酒造 – 高野山の麓にて天保11年創業の小さな老舗蔵 高野山の麓にて天保11年創業の小さな老舗蔵 takagakishuzo こんにちは、髙垣酒造です。Instagram でフォロー 初代髙垣又右衛門から続く酒造りへの思いは今も変わらない 比較的温暖な気候の和歌山ですが、密教の聖地と言われる高野山の標高は約900m。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('淳一', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・五百万石・祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒・古酒', ''), brewing_features) WHERE id=8818;
UPDATE breweries SET description='広島県広島市安芸区に蔵を構える合名会社梅田酒造場は、大正5年（1916年）創業の歴史を誇る老舗酒蔵です。広島東部の船越周辺に五軒有った造り酒屋も、現在は他の四軒は廃業して梅⽥酒造場のみ、地に根付いた⽇本酒を醸造しています。本洲一のこだわり｜本洲一 公式サイト – 本洲一 醸造元｜梅田酒造場 にごり酒・古酒・その他 にごり酒・古酒・その他 当社は、広島市の東部安芸区船越町にある小さな蔵元です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過・古酒', ''), brewing_features) WHERE id=7914;
