UPDATE breweries SET description='和歌山県伊都郡かつらぎ町に蔵を構える初桜酒造株式会社は、慶応2年（1866年）創業の歴史を誇る老舗酒蔵です。高野山の般若湯と九度山真田忍び、紀州かつらぎ川上酒の醸造元です。しかし、大手酒造メーカーによる工場での管理された日本酒醸造が主流となり、自然に任せた地酒の製造は、時代に取り残され、かつらぎの蔵元は、とうとう初桜酒造のみとなってしまいました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('10:00～17:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=8821;
