UPDATE breweries SET description='広島県福山市に蔵を構える株式会社岡本亀太郎本店は、安政2年（1855年）創業の歴史を誇る老舗酒蔵です。保命酒オンラインショップ 岡本亀太郎本店のこだわり 岡本亀太郎本店の「保命酒」は、16種類の薬味を秘伝のレシピで味醂に漬け込んだ薬味酒です。岡本亀太郎本店の保命酒は、桂皮などの薬味十六種を、丁寧に仕込んだ自社醸造の味醂酒に漬け込み、じっくりと成分を浸出させて造る薬味酒（和製リキュール）です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('保命酒', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=7892;
UPDATE breweries SET description='広島県東広島市西条本町に蔵を構える賀茂鶴酒造株式会社は、明治6年（1873年）創業の歴史を誇る老舗酒蔵です。2023（令和5）年9月、賀茂鶴はおかげさまで創業150年を迎えます。伝統を受け継ぎ妥協のない酒造りに情熱を注ぐ蔵人の心。歴史ある建造物は西条酒蔵通り・近代化産業遺産としても親しまれており、伝統と革新を融合させた味わいを全国の日本酒ファンへ届けています。', description_generated=1, president_name=COALESCE(NULLIF('直営店', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒・古酒', ''), brewing_features) WHERE id=7918;
