UPDATE breweries SET description='鹿児島県鹿児島市に蔵を構える三和酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。創業当時の商品は、ラベルに気品高く幸運のシンボルとして親しまれている「鶴」を三羽配し、 長寿の象徴の「鶴」にあやかり商品が末長く愛されるよう 「三和鶴」と命名されました。その誕生から約５０年後、創業地の鹿児島県薩摩川内市から眼下に雄大な桜島を拝する鹿児島市に拠点を移し、昔ながらの製法である甕壺仕込みと木樽蒸留にこだわった蔵として、焼酎造りを続けています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('松元太 会社概要', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=57747;
