UPDATE breweries SET description='広島県東広島市安芸津町に蔵を構える株式会社今田酒造本店は、明治元年（1868年）創業の歴史を誇る老舗酒蔵です。銘柄名「富久長」は、安芸津の醸造家、三浦仙三郎翁につけていただいたものです。三浦仙三郎は1847年に安芸津町三津に生まれ、軟水醸造法を発明。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('今田 美穂', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('直汲み', ''), brewing_features) WHERE id=7895;
UPDATE breweries SET description='広島県竹原市に蔵を構える藤井酒造株式会社は、文久3年（1863年）創業の歴史を誇る老舗酒蔵です。酵母や乳酸菌が棲みつき、 この環境が受け継がれてきました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('藤井義大 所在地', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛・木桶・全量純米', ''), brewing_features) WHERE id=7893;
UPDATE breweries SET description='広島県福山市に蔵を構える株式会社天寶一は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。特別栽培米 辛口純米大吟醸 特別栽培米 辛口純米大吟醸 特別栽培米 辛口純米大吟醸 生酛純米大吟醸「久二-hisaji-」 生酛純米大吟醸「久二-hisaji-」 生酛純米大吟醸「久二-hisaji-」 派手さではなく、料理と寄り添うこと。全量広島県産米にこだわり、千本錦、八反錦、山田錦、萌えいぶきなどを使用。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・千本錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛・直汲み', ''), brewing_features) WHERE id=7901;
UPDATE breweries SET description='和歌山県和歌山市に蔵を構える株式会社世界一統は、明治17年（1884年）創業の歴史を誇る老舗酒蔵です。1907年（明治40年）常楠が師事していた大隈重信が、主力銘柄の酒名を「世界一統」と命名。伝統技術の粋を集めた味わいが、特別な日の食事を一層華やかなものにしてくれます。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=8831;
UPDATE breweries SET description='広島県東広島市安芸津町に蔵を構える柄酒造株式会社は、嘉永元年（1848年）創業の歴史を誇る老舗酒蔵です。そのために私たちは伝統とこれからを結び、心を込めて、ゆっくりと丁寧に酒を醸し続けます。広島県産の酒造好適米のみを使用したこだわりの地酒です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('八反錦・千本錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=7896;
UPDATE breweries SET description='鹿児島県薩摩川内市に蔵を構える田苑酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。それを一定したクオリティに仕上げるのがブレンド技術。受け継がれてきたフロンティア・スピリッツを胸に、世界にひとつの美味しさを求めていきます。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=57769;
UPDATE breweries SET description='鹿児島県指宿市に蔵を構える指宿酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。口当たりがまろやかですっきりした味わいの後に「キレ」がある、創業当初よりの代表銘柄。昔ながらの黒麹を使用し、製法にこだわりました 鹿児島県産の採れたての梅を、利右衛門ブランドの芋焼酎に漬け込んだ贅沢な梅酒。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('入魂', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=57764;
