UPDATE breweries SET description='和歌山県海南市に位置する中野BC株式会社は、昭和7年（1932年）に創業しました。リサーチセンター食品科学研究所 FRAGRANT KISHU waka-和香-（和アロマ） グループ会社一覧企業理念会社概要社長挨拶 100年企業を目指し、独自の技術と情熱をもって歩んで参りました。「中野醤油店」として開業し、他社に類を見ない技術を追求し、その成果として蒸熱法「大豆蒸熱法」を生み出しました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・雄町・備前雄町', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過・原酒・長期熟成・氷温貯蔵', ''), brewing_features) WHERE id=8825;
UPDATE breweries SET description='鹿児島県阿久根市に蔵を構える大石酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。私ども大石酒造は、創業の年より百年を超える歴史と共に、鹿児島県の恵まれた風土の中に小さな蔵を構え、これまで代々五代にわたり焼酎造りに専念して参りました。大石酒造の創業者、大石長次郎が焼酎製造免許を手にいれたのは明治三十二年と言われております。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('鹿児島県阿', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=57775;
UPDATE breweries SET description='鹿児島県いちき串木野市に蔵を構える若松酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。若松酒造は享保4年（西暦1719年）創業以来現在に至るまで、当地鹿児島県いちき串木野市湊町で焼酎造りに携わりたくさんのお客様とともに歩んでまいりました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=57755;
UPDATE breweries SET description='岩手県盛岡市に蔵を構える株式会社あさ開は、明治4年（1871年）創業の歴史を誇る老舗酒蔵です。明治４年の創業より、日本酒『あさ開』は、米、水、技に恵まれたこの地で豊かな自然に磨かれ、愛すべき人々に育まれてきました。南部藩士だった七代目・村井源三が武士を辞め、明治 4 年（１８７１年）に現在地で酒づくりをはじめたのがその創業にあたります。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('会長 豊岡', ''), president_name), toji_name=COALESCE(NULLIF('自醸清酒鑑', ''), toji_name), opening_hours=COALESCE(NULLIF('9:00〜18:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過・原酒', ''), brewing_features) WHERE id=33101;
