UPDATE breweries SET description='高知県に蔵を構える酔鯨酒造有限会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。私たちはそのような高知県のお酒の特徴である”食中酒”をさらに追及して「香りおだやか」で「キレがあり」ながら「旨味をしっかり出す」芳醇辛口な酒造りの技術を磨いてきました。自社酵母（ 9 号系由来）でじっくりと発酵させ、あと味がすっきりとした、暑い夏にピッタリな純米酒に仕上げました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('浜蔵', ''), president_name), toji_name=COALESCE(NULLIF('土居教治', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・吟風・八反錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒・長期熟成', ''), brewing_features) WHERE id=6750;
