UPDATE breweries SET description='鹿児島県伊佐市に蔵を構える大口酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。「伊佐錦」「黒伊佐錦」などの銘柄の他に、地元のブランド米「伊佐米」を使用した 伊佐地区限定焼酎「伊佐舞」などがあり、県内をはじめ全国一円に展開しています。当地は気候や良質の水など、焼酎造りの天然環境に恵まれ、素材や原料の厳選のほか、伝統の技と近代的製法が融合して、その製品に深い味わいを醸し出しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('有満 隆明', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=57779;
UPDATE breweries SET description='鹿児島県大島郡龍郷町に蔵を構える奄美大島酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。高倉 浜千鳥乃詩 じょうご 本格奄美黒糖焼酎の製造・販売 | 奄美大島酒造 素材へのあくなきこだわり 奄美大島酒造で製造している黒糖焼酎は、100%奄美大島産純黒糖のみを使用しています。私たちがこだわり続ける理由がここにあります。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('有村 成生', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒・長期熟成・古酒', ''), brewing_features) WHERE id=57833;
