UPDATE breweries SET description='沖縄県那覇市に位置する宮里酒造所は、昭和21年（1946年）に創業しました。仕込み水には良質な首里首里城下湧水・琉球石灰岩湧水（硬水）を使用し、丁寧な手造りの精神を受け継ぎながら、米の旨味を引き出す真摯な酒造りを追求しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=57912;
UPDATE breweries SET description='熊本県球磨郡あさぎり町に蔵を構える松の泉酒造合資会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。2026年 4月 24日 球磨焼酎「松の泉」と「特別清水仕込　水鏡無私」優等賞受賞のご報告 この程開催されました、熊本国税局令和８年酒類鑑評会の本格焼酎部門で、弊社の２銘柄が、その品質と製造技術に高い評価をいただき、優等賞を受賞いたしました。受賞銘柄 ●松の泉　（まつのいずみ） 球磨焼酎の本当の美味しさを知っている、人吉・球磨の人々に長年ご愛飲いただいている米焼酎です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=57877;
UPDATE breweries SET description='沖縄県北谷町に蔵を構える北谷長老酒造工場株式会社は、嘉永元年（1848年）創業の歴史を誇る老舗酒蔵です。その前身となる玉那覇酒造は、首里赤田町にて創業。小人数で造るため年間の生産量が限られており、大量生産はできませんが、伝統製法にのっとり、味がブレないように丁寧な酒造り心がけています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('玉那覇 徹', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('9:00～18:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('古酒', ''), brewing_features) WHERE id=57892;
