UPDATE breweries SET description='沖縄県石垣市に位置する仲間酒造株式会社は、昭和23年（1948年）に創業しました。木製の蒸し機や地釜蒸留器などを今も大切に使い、１９４８年創業当時の製法を大切に、丁寧に造り続けています。地元で愛される泡盛を目指し、銘柄は「宮之鶴」１種類のみ。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=57914;
