UPDATE breweries SET description='鹿児島県奄美市に蔵を構える株式会社西平本家は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。奄美黒糖焼酎 | 西平本家  大正14年創業 熊本国税局 令和8年酒類鑑評会 奄美黒糖焼酎「氣（白麹仕込み）」が優等賞受賞。蔵と歴史｜奄美黒糖焼酎 | 西平本家  大正14年創業 （株）西平本家は、大正14年、初代 西平守常氏が喜界島に渡って創業、昭和2年に奄美市（旧名瀬市）に移転、奄美黒糖焼酎の製造販売を行ってまいりました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('東小薗 弘貴', ''), president_name), toji_name=COALESCE(NULLIF('代表受賞 令和', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=57811;
UPDATE breweries SET description='沖縄県与那国町に位置する株式会社 どなん酒造は、昭和33年（1958年）に創業しました。熱く焼けるのど越しは南の島の太陽の暑さを連想させるような情熱のお酒です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('大嵩長重 設立', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('長期熟成・古酒', ''), brewing_features) WHERE id=57907;
UPDATE breweries SET description='沖縄県西原町に位置する株式会社石川酒造場は、昭和24年（1949年）に創業しました。地域社会に貢献する企業として、技術の研鑽と資質の向上に努める。昔ながらの甕仕込み製法を採用し一石甕を使い、職人の技術と手間隙をかけて仕込みを行っている。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('社長 樽', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('8:30～17:30', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('古酒', ''), brewing_features) WHERE id=57901;
UPDATE breweries SET description='沖縄県恩納村に位置する合資会社恩納酒造所は、昭和24年（1949年）に創業しました。昔ながらの伝統の造りを継承し、創業から変わらぬ味と香りを守り続ける。萬座 10年古酒 40度 「琉球泡盛 萬座」とは 青い海に突出した断崖絶壁の上に広がる景勝地、 万座毛のほど近くに1949年(昭和24年)創業。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('佐渡山 誠', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒・古酒', ''), brewing_features) WHERE id=57917;
UPDATE breweries SET description='沖縄県那覇市に蔵を構える瑞穂酒造株式会社は、嘉永元年（1848年）創業の歴史を誇る老舗酒蔵です。商品ページ（外部サイト） Frontier Spirit 〜 縁を繋ぎ文化を創る 1848年創業…その170年の歴史と共に継承された、技術、繋がり、そして開拓者精神。沖縄が笑顔溢れる場所になることを夢見て… 沖縄から世界を目指す、多様な酒造り 長い歴史の中で培ってきた酒造りの伝統とFrontier Spiritは、泡盛だけにとどまらず、様々な酒造りに息づいています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=57913;
UPDATE breweries SET description='沖縄県島尻郡久米島町に位置する株式会社久米島の久米仙は、昭和24年（1949年）に創業しました。伝統的に継承されてきた泡盛の製法に従って、今でも泡盛の原料にはタイ産の米が使われていますが、ここにもアジアと琉球をつなぐ歴史の1ページを垣間見る ことができます。幾世紀もの歴史に育まれ、 静かに円熟の年月を刻んできた泡盛の神髄は、今も久米島の久米仙に受け継がれ、豊潤で清冽な美酒の味わいを皆様に届け続けています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('島袋 正也', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('古酒', ''), brewing_features) WHERE id=57908;
UPDATE breweries SET description='沖縄県宮古島市に位置する菊之露酒造株式会社は、昭和3年（1928年）に創業しました。常に泡盛の「ど真ん中のおいしさ」を追求し続ける私たちの、こだわりの商品についてご紹介します。その後、お米を蒸していくのですが、気温や温度の変化によって、細かな調整が必要になってくるため、泡盛職人が培ってきた技術と勘の魅せどころです。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('下地 一盛', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('古酒', ''), brewing_features) WHERE id=57905;
UPDATE breweries SET description='沖縄県石垣市に位置する有限会社髙嶺酒造所は、昭和24年（1949年）に創業しました。泡盛ファンだけでなく、泡盛を初めて飲むという方にもおすすめの高嶺酒造の代表銘柄です。１,８００㎖、７２０㎖、６００㎖、１００㎖ 石垣島の名勝地川平湾をイメージして造り出されたという代表銘柄のひとつ。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('古酒', ''), brewing_features) WHERE id=57925;
