UPDATE breweries SET description='沖縄県恩納村に蔵を構える咲元酒造株式会社は、明治35年（1902年）創業の歴史を誇る老舗酒蔵です。沖縄の泡盛・古酒の咲元酒造 100有余年守り続けた、伝統の泡盛 古酒成分をたっぷり含んだ自慢の原酒をじっくりと貯蔵。咲元酒造とは明治35年創業の100年以上の老舗で、2代目の佐久本政良は戦後昭和21年に「首里酒造廠」として最初に泡盛作りを許され、泡盛復興の父と呼ばれていた職人です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒・古酒・低温発酵', ''), brewing_features) WHERE id=57920;
UPDATE breweries SET description='熊本県球磨郡錦町に蔵を構える六調子酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。日本三大急流の一つ「球磨川」が九州山地を矢のように流れ下り一息入れる球磨盆地で、清冽な水と、たわわに実った米を原料に情味豊かな人々の手で造られ、貯蔵の歳月に磨きぬかれた「球磨焼酎」の銘柄です。蒸留酒の味を決定づける最終工程、ブレンディングにも並々ならぬこだわりを持ちます。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒・長期熟成・古酒', ''), brewing_features) WHERE id=57883;
UPDATE breweries SET description='沖縄県与那国町に位置する合名会社崎元酒造所は、昭和2年（1927年）に創業しました。伝統的な手造り製法の琉球泡盛・花酒 日本最西端の酒造所 崎元酒造 与那国島には現在（2009年）3つの酒造所がありますが、その中でも一番古い酒造所が崎元酒造で、昭和2年に農業を本職とした17人の出資者が共同の酒造所を設立しました。平成18年の4月にティンダハナタの頂上付近に酒造蔵を新規移転し、今では八重山諸島の小さな蔵元にしか残っていない、泡盛600年の歴史を伝承する昔ながらの古式地釜蒸留機を使用し、少人数で伝統的な手造り製法でお酒を造り続けています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=57919;
UPDATE breweries SET description='沖縄県石垣市に位置する請福酒造有限会社は、昭和24年（1949年）に創業しました。受付時間　平日10:00-17:00 0980-84-4118 八重山地方での絶大なシェアを誇る「直火請福」や純粋な100％古酒「請福VINTAGE」等、請福酒造がこだわり抜いた泡盛です。一九四九年に漢那憲副、文江夫妻により、新川村で漢那酒屋として創業いたしました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('売店', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('10:00～17:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('古酒', ''), brewing_features) WHERE id=57922;
