UPDATE breweries SET description='沖縄県名護市に蔵を構える合資会社津嘉山酒造所は、大正13年（1924年）創業の歴史を誇る老舗酒蔵です。About Tsukayama awamori distillery 代表銘柄は國華、従業員3名の小さな酒造所。大正13年創業なので今年でちょうど百年目。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過・原酒・古酒', ''), brewing_features) WHERE id=57930;
UPDATE breweries SET description='熊本県球磨郡多良木町に蔵を構える株式会社恒松酒造本店は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。熊本県球磨郡の豊かな自然、水にこだわり、原料にこだわる 熊本県球磨地方で栽培したムラサキマサリを手作業で選別し、黒麹で仕込んだ本格芋焼酎です。球磨焼酎とは「球磨の水」「球磨の地での醸造、ボトリング」を条件に、世界に認められた米焼酎です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('情報', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過・原酒・古酒', ''), brewing_features) WHERE id=57889;
UPDATE breweries SET description='沖縄県今帰仁村に位置する有限会社今帰仁酒造は、昭和23年（1948年）に創業しました。今帰仁酒造 - 泡盛・古酒の製造 販売 IMUGE.（イムゲー）について 泡盛であり続けること今帰仁であること 1948年創業以来、私たちは今帰仁の地で酒造りを行ってきました。酒造りと共に伝統文化である泡盛を伝えていく。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('長期熟成・古酒', ''), brewing_features) WHERE id=57915;
