UPDATE breweries SET description='沖縄県に蔵を構える有限会社髙嶺酒造所は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。泡盛ファンだけでなく、泡盛を初めて飲むという方にもおすすめの高嶺酒造の代表銘柄です。１,８００㎖、７２０㎖、６００㎖、１００㎖ 石垣島の名勝地川平湾をイメージして造り出されたという代表銘柄のひとつ。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('古酒', ''), brewing_features) WHERE id=60307;
UPDATE breweries SET description='沖縄県那覇市に位置する久米仙酒造株式会社は、昭和27年（1952年）に創業しました。創業者から受け継いだ「伝統を大切にしながら、泡盛の新しい可能性を求めて一歩進んだ泡盛づくり」をモットーに、これからもチャレンジを続けてまいります。OKINAWA ISLAND BLUE 日本の焼酎文化の起源にあたる沖縄の泡盛古酒の製造技術を生かした新時代のウイスキー 加水を控えた50度の力強さと干しぶどうやはちみつを思わせるまろやかな甘み。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('比嘉 洋一', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒・古酒', ''), brewing_features) WHERE id=57909;
UPDATE breweries SET description='沖縄県名護市に位置する株式会社龍泉酒造は、昭和14年（1939年）に創業しました。杜氏の勘と経験の積み重ねにより、手間暇を惜しまず丁寧に伝統の酒造りを守り継いでいます。いつも世も伝統の泡盛を造り続けていくことのできる酒造所を目指しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒・古酒', ''), brewing_features) WHERE id=57918;
