UPDATE breweries SET description='沖縄県糸満市に位置する上原酒造株式会社は、昭和22年（1947年）に創業しました。トップページ - 琉球泡盛 糸満最古の泡盛酒造所「上原酒造」 上原酒造は1947年創業。上原酒造の酒は、沖縄のもたらす様々な恵みと泡盛業界初の「電子技法」によって生み出されています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('代表取締役', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒・古酒', ''), brewing_features) WHERE id=57931;
UPDATE breweries SET description='沖縄県大宜味村に位置するやんばる酒造株式会社は、昭和25年（1950年）に創業しました。やんばるつながリキュール 地元やんばるのこだわり食材から生まれる贅沢なリキュール 琉球泡盛/UFU-YANBARU～世界自然遺産ミニボトル～ 【祝】世界自然遺産登録。今から約75年前、1950年（昭和25年）に大宜味村田嘉里地区で、地域の人たちの出資により創業いたしました。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('古酒', ''), brewing_features) WHERE id=57934;
UPDATE breweries SET description='熊本県人吉市に蔵を構える合資会社大和一酒造元は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。仕込み水には良質な阿蘇外輪山・白川水源湧水群（中硬水）を使用し、蔵元杜氏・熊本杜氏の伝統の技を受け継ぎながら、米の旨味を引き出す真摯な酒造りを追求しています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('9:00～17:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒・古酒', ''), brewing_features) WHERE id=57891;
UPDATE breweries SET description='沖縄県沖縄市に蔵を構える新里酒造株式会社は、弘化3年（1846年）創業の歴史を誇る老舗酒蔵です。沖縄最古の蔵元 先代から伝統を受け継ぎ、 次代へ進化を仕継ぐ新里酒造 新里酒造の創業は、弘化三年（１８４６年） 現存する沖縄の酒造所としては、もっとも古い酒造所と云われています。新里酒造は、その一人として認められて以来、伝統の技と精神を受け継いで以来、現在七代目当主がこののれんを守っています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('先代', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('古酒', ''), brewing_features) WHERE id=57924;
