UPDATE breweries SET description='沖縄県那覇市に蔵を構える有限会社識名酒造は、大正7年（1918年）創業の歴史を誇る老舗酒蔵です。泡盛「時雨」の伝統の味わいと香りをお届けします。黒麹の源流、タイ米へのこだわり 黄麹や白麹が使われる日本酒や焼酎に対し、泡盛に使われるのは100%黒麹菌（くろこうじきん）のみ。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('古酒', ''), brewing_features) WHERE id=57923;
