UPDATE breweries SET description='鹿児島県大島郡知名町に蔵を構える原田酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。奄美の自然と情熱が込められた本格焼酎は、口に含めば黒糖の優しい香りと米麹由来の芳醇な風味が広がり、古くから多くのファンに愛飲されてきました。代表銘柄の「昇龍」や「満月」、使用する原酒が異なるプレミアムな昇龍「三種の神氣」など原田酒造の商品ラインナップなどをご紹介します。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒・古酒', ''), brewing_features) WHERE id=57836;
