UPDATE breweries SET description='沖縄県石垣市に位置する有限会社八重泉酒造は、昭和30年（1955年）に創業しました。八重泉酒造はじまりのクラフトジン『YAESEN GIN 01』誕生 お中元・夏ギフトにおすすめのお酒 創業1955年。⼿間のかかる直⽕蒸留と、⻑期に渡る樽貯蔵を融合させるといった 伝統と⾰新が融合された酒造りに取り組んでいます。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('座喜味 盛行', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('古酒', ''), brewing_features) WHERE id=57932;
UPDATE breweries SET description='鹿児島県に蔵を構える農業法人 八千代伝酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。マルチン・ルターが残した言葉は、ここ鹿児島垂水で、 今も醸造家の心に火を灯し続ける。パワフルな辣腕を振るった創業初代“八木栄吉”、志高く政治の道にも進んだ二代目“八木栄一”、30年の焼酎造りへの思いを実現させ蔵再興を果たした三代目“八木栄壽”、そして私四代目“八木健太郎”が伝統産業焼酎造りのバトンを繋いでいます。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('代表取締役', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=65988;
