UPDATE breweries SET description='青森県に蔵を構える八戸酒類株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。清冽な自然水と、津軽・南部の豊富な良質米を用いて南部流儀の伝統技法と五感で醸す手造りの「八戸のうまし酒」です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('直売所', ''), president_name), toji_name=COALESCE(NULLIF('自醸清酒鑑', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦・華吹雪・華想い', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('生酛・山廃・無濾過・原酒', ''), brewing_features) WHERE id=70732;
UPDATE breweries SET description='鹿児島県に蔵を構える濵田酒造株式会社 傳藏院蔵は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。現在は伝兵衛蔵・傳藏院蔵・金山蔵という3つの蔵を有し、各々の蔵が『伝統』『革新』『継承』という弊社の核となる焼酎づくりの理念を体現しています。革新の原点伝統の黒麹仕込み だいやめ～DAIYAME～ 後世へ語り継ぎたい「だいやめ文化」への想いを込めた創業150年目の逸品。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('木桶・原酒', ''), brewing_features) WHERE id=65973;
UPDATE breweries SET description='鹿児島県に蔵を構える雲海酒造株式会社 出水蔵は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。伝統の技を継承しながら常に新たな価値を生み出し、よりおいしいお酒をお客様にお届けしたいという思いを胸に、酒造りの可能性を追求していくことこそが、私たちの変わらぬ姿勢です。伝統の技を継承しながら常に新たな価値を生み出し、よりおいしいお酒をお客様にお届けしたいという思いを胸に、酒造りの可能性を追求していくことこそが、私たちの変わらぬ姿勢です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('代表取締役', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=65998;
UPDATE breweries SET description='鹿児島県に蔵を構える鹿児島酒造㈱黒瀬杜氏伝承蔵は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。そこで1500年頃から醪を蒸留して焼酎を造る技術が伝わり、薩摩の地に定着しました。その創世記に活躍したのが黒瀬金次郎であり、鹿児島酒造㈱黒瀬杜氏伝承蔵の初代杜氏黒瀬安光は三男にあたります。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('無濾過', ''), brewing_features) WHERE id=66015;
