UPDATE breweries SET description='熊本県球磨郡錦町に蔵を構える常楽酒造株式会社は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。球磨川に流れる最上の天然水を使い、 熊本県産原料を中心に選び抜かれた国産原料にこだわり、惜しみなく使用し、 仕込まれて造られる焼酎は、まさに贅沢の極み。地産地消にこだわり、球磨産のなめらかなヨーグルトを使って仕込んだヨーグルトリキュールをはじめ、採れたての新鮮な果実を、自慢の純米焼酎に漬け込んだ本格派のフルーツリキュール酒など、多種多様。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('見学 期間', ''), president_name), toji_name=COALESCE(NULLIF('歴三十数年', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('', ''), brewing_features) WHERE id=57873;
UPDATE breweries SET description='滋賀県長浜市に位置するハッピー太郎醸造所は、令和4年（2022年）に創業しました。ハッピー太郎醸造所は、さまざまな副原料を使った「クラフトどぶろく」を主軸に、糀、甘酒、味噌など、多様な現代の食卓に溶け込む発酵食品を製造・開発・販売しております。醸造所見学BREWERY TOUR 普段は入れない醸造所の内部をご覧いただける貴重な体験です。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('11:00〜18:00', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('木桶', ''), brewing_features) WHERE id=62598;
UPDATE breweries SET description='熊本県球磨郡あさぎり町に蔵を構える合資会社高田酒造場は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。これまでの伝統を守りつつ、これからも米焼酎のイメージを覆すような新しい球磨焼酎を造り続けます。焼酎は全て手造りで、昔ながらの石蔵の麹室、カメ（甕）仕込みを受け継ぎ、こだわりの少量生産を守っています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('山田錦', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=57886;
