UPDATE breweries SET description='鹿児島県に蔵を構えるみしま焼酎 無垢の蔵は、明治43年（1910年）創業の歴史を誇る老舗酒蔵です。焼酎みしま村/メンドン飲み比べセット グラス１個プレゼント 25度　720ml 以下で取り扱っています 原酒ならではの飲み応え 長期貯蔵原酒　みしま村 以下で取り扱っています 鹿児島県三島村黒島、公設公営で醸造された本格芋焼酎です。また、本プロジェクトでみしま焼酎無垢の蔵で焼酎を造るにあたり、濵田酒造様を始めとした⽼舗の焼酎製造関連企業様の技術支援をいただいており、皆様の支えによって焼酎プロジェクトは運営されています。伝統の技を守りつつ、現代の食文化に寄り添う高品質な美酒を醸し続けています。', description_generated=1, president_name=COALESCE(NULLIF('', ''), president_name), toji_name=COALESCE(NULLIF('養成', ''), toji_name), opening_hours=COALESCE(NULLIF('', ''), opening_hours), main_rice_varieties=COALESCE(NULLIF('祝', ''), main_rice_varieties), brewing_features=COALESCE(NULLIF('原酒', ''), brewing_features) WHERE id=57843;
